code:
// A tour of the core language in one linear program: values and their
// widths, the array family, slices, structs, control flow as expressions,
// functions with several results, optionals and references. The other
// samples assume what this one shows.
//
// Build and run (from this directory):
//   goose -o tour.c 01_tour.goose && cl tour.c && tour

// A function taking a slice accepts every array kind and any sub-range of
// one, without a copy: the slice is a reference to the elements plus a count.
fn total(xs: i64[:]) -> i64 {
    var t = 0;
    for x in xs { t += x; }
    return t;
}

// Several results are a calling convention, not a tuple type. By custom a
// trailing bool (or error code) says whether the rest is meaningful.
fn divide(a: i64, b: i64) -> i64, bool {
    if b == 0 { return 0, false; }
    return a / b, true;
}

// "Maybe an element": an optional is a nullable reference into the input.
fn first_at_least(xs: i64[:], min: i64) -> i64? {
    for &x in xs { if x >= min { return x; } }
    return null;
}

// Untyped parameters make a function generic; each call instantiates it for
// the argument types it gets.
fn larger(a, b) { if a > b { a } else { b } }

// A struct is packed data in declaration order. Fields may carry defaults,
// which a literal can then leave out.
struct Point { x: f64, y: f64 }
struct Player { name: u8[..16], pos: Point, hp: i32 = 100, alive: bool = true }

fn main() {
    // --- scalars -----------------------------------------------------------
    // `let` binds a constant, `var` a variable. An integer literal adapts to
    // the type it meets; on its own it is an i64, the default for counts and
    // indices. The sized types are for data.
    let answer = 42;
    var count: i32 = 0;
    let byte: u8 = 255;
    let ratio = 0.75;
    let single: f32 = 1.5;
    let yes = 3 > 2;
    count += 1;
    count++;
    print("answer=", answer, " count=", count, " byte=", byte, " ratio=", ratio,
          " single=", single, " yes=", yes);

    // Arithmetic runs at the operands' own width: u8 + u8 is an 8-bit add.
    // A narrower type widens into a wider one implicitly; nothing narrows
    // without a cast.
    let wrapped: u8 = byte + 1;          // unsigned math wraps by definition
    let widened = byte + answer;         // the u8 widens into the i64
    let narrowed = answer as u8;         // range-checked in debug, truncates in release
    print(wrapped, " ", widened, " ", narrowed);
    // `%` is Euclidean, so the result is never negative: `x % n` is always
    // a valid index into an array of length n, whatever the sign of x.
    print(-7 % 3, " ", 7 % -3);

    // --- the array family --------------------------------------------------
    // Every array is inline, packed element data; the kinds differ in how
    // the size behaves. A fixed array has a constant size and no metadata.
    var fixed: i32[4] = [1, 2, 3, 4];
    fixed[0] = 10;
    let zeros: f64[8] = [0.0; 8];        // fill form
    // The grow-only array is the workhorse: a push is a pointer bump on the
    // data stack, nothing is ever moved or reallocated, and references into
    // it stay valid as it grows -- the promise a vector<T> cannot make, and
    // the one the data-structure samples build on.
    var grow: i64[>..] = [];
    for i in 5 { grow.push(i * i); }
    // A grow-shrink array also pops: the natural stack and queue.
    var stack: i64[>..<] = [];
    stack.push(1); stack.push(2); stack.push(3);
    let top = stack.pop();
    // A limited array has a fixed capacity, so it lives inline anywhere a
    // fixed value can: in a struct, as an array element, in a local.
    var small: u8[..8] = [];
    small.push('h'); small.push('i');
    // A variable array is sized at construction and frozen afterwards.
    let frozen: i64[] = [7, 8, 9];
    print(fixed, " ", zeros.len, " ", grow, " ", stack, " ", top, " ",
          small, " ", small.len, "/", small.cap, " ", frozen);

    // A string is a u8 array: no string type, no allocation. A literal is
    // static data, a builder is a growable u8 array, and `format`, `str`
    // and `print` render anything as text into one of those.
    var s: u8[>..] = [];
    s.append("hello");
    s.push(' ');
    format(s, "x", 1, " ", 2.5);
    print(s, " (", s.len, " bytes)");

    // --- slices ------------------------------------------------------------
    // `a[x..y]` is a view of elements x up to y; `^k` counts from the end.
    // A slice cannot dangle: the checker ties it to the array that owns the
    // elements, and that array cannot shrink under it.
    let middle = grow[1..4];
    let last_two = grow[^2..];
    print(middle, " ", last_two, " ", total(middle), " ", total(grow), " ", total(fixed_sum(fixed)));

    // --- structs -----------------------------------------------------------
    // A Player is one flat value: the name's bytes live inside it, not behind
    // a pointer, so an array of players is one contiguous block.
    var p = Player { name: "gus", pos: Point { 1.0, 2.0 } };
    p.hp -= 30;
    p.pos = p.pos + Point { 0.5, 0.5 };  // arithmetic is elementwise on same-typed structs
    print(p);
    print(p.name, " at ", p.pos.x, ",", p.pos.y, " hp ", p.hp);

    // --- control flow as expressions ---------------------------------------
    // `if` and `match` are expressions: no ternary, no temporary assigned in
    // each branch.
    let kind = if p.hp > 50 { "healthy" } else { "hurt" };
    let level = match p.hp { 0 => "dead", 1..50 => "low", _ => "fine" };
    print(kind, " ", level);
    // `guard` states what the code after it relies on; its else must leave.
    // `block` gives `break` a target, so a chain of checks can bail out with
    // a value without a loop.
    let verdict = block {
        guard p.alive else { break "gone"; }
        guard p.hp > 0 else { break "dead"; }
        "standing"
    };
    print(verdict);

    // --- loops -------------------------------------------------------------
    var acc = 0;
    for i in 3 { acc += i; }             // 0, 1, 2
    for i in 10..13 { acc += i; }        // 10, 11, 12
    for x in fixed { acc += x; }         // copies of the elements
    for &x in fixed { x *= 2; }          // references: the mutation form
    for x, i in frozen { acc += x * i; } // with the index
    var n = 0;
    while n < 3 { n++; }
    loop { n--; if n == 0 { break; } }
    print(acc, " ", fixed, " ", n);

    // --- several results, optionals, references ----------------------------
    // Two results come back together, as part of the calling convention:
    // no tuple type, nothing packed and unpacked.
    let q, ok = divide(7, 2);
    let q2, ok2 = divide(1, 0);
    print(q, " ", ok, " ", q2, " ", ok2);
    // An optional must be narrowed before use: inside the `if` it is a plain
    // reference to the element it found.
    let big = first_at_least(grow, 5);
    if big { print("first >= 5 is ", big); } else { print("none"); }
    let none = first_at_least(grow, 100);
    print(none == null);
    // A reference reads and writes as its target; `.=` binds it (where `=`
    // would copy the element) and retargets it, and `.==` asks whether two
    // references name the same target.
    var r .= grow[0];
    r = 100;
    r .= grow[1];
    r += 1;
    print(grow, " ", grow.index_of(r), " ", r .== grow[1]);
    print(larger(3, 9), " ", larger(2.5, 1.5));
}

// A fixed i32 array widened into an i64 array, so `total` can take it: the
// slice type names the element type exactly, and i32 is not i64.
fn fixed_sum(xs: i32[4]) -> i64[4] {
    return [xs[0], xs[1], xs[2], xs[3]];
}

// Where values live, and what that buys. Goose has no allocator: every
// dynamic value is owned by a variable and lives on a data stack, growth is
// a pointer bump, and the only "free" is a scope ending. This program walks
// through the consequences one at a time, with the numbers to show for it.
//
// Build and run (from this directory):
//   goose -o memory.c 02_memory.goose && cl memory.c && memory

import slot_pool;
import std;

struct Item { id: i32, weight: f32 }

// A limited array is fixed-size storage with a length: capacity inline,
// no pointer, so a struct holding one is still one flat value.
struct Row { label: u8[..12], cells: i32[..8] }

fn reset(buf: u8[>..]&) { buf.clear(); }

fn main() {
    // 1. A grow-only array never moves its elements. A reference taken
    //    early stays valid however much is pushed afterwards, which is what
    //    a vector<T> or Vec<T> cannot promise: they reallocate.
    var items: Item[>..] = [];
    let first: Item& = items.push(Item { 1, 0.5 });
    for i in 2..100001 { items.push(Item { i as i32, i * 0.5 }); }
    first.weight = 99.5;                 // through the reference, 100000 pushes later
    print(items.len, " items, first weight ", items[0].weight);

    // 2. Scope exit is the free. A buffer declared in a loop body is fresh
    //    each iteration and gone at the closing brace: the data stack's top
    //    is reset to where it was, no destructor runs, no list is walked.
    for round in 3 {
        var scratch: u8[>..] = [];
        for i in 10000 { scratch.push((i % 256) as! u8); }
        print("round ", round, ": ", scratch.len, " bytes of scratch");
    }

    // 3. Or keep one buffer and clear it. A grow-only array may shrink at
    //    a point where nothing in scope refers into it -- the compiler
    //    knows every place a reference into it was stored, and names the
    //    holder if one is live -- so a reused line buffer costs nothing
    //    per line, here through a helper that clears its argument.
    var line: u8[>..] = [];
    for i in 3 {
        reset(line);
        format(line, "line ", i + 1, " of 3");
        print(line);
    }

    // 4. Nested containers stay flat. An array of strings is one block:
    //    lengths and bytes back to back, no pointer per string, where a
    //    vector<string> is an allocation per element. Dropping it is the
    //    same pointer reset as dropping an array of integers.
    var words: u8[][>..] = [];
    for i in 5 { words.push(str("word", i)); }   // built straight into the element
    var bytes = 0;
    for w in words { bytes += w.len; }
    print(words.len, " words, ", bytes, " bytes of text, ", words.len * 4 + bytes,
          " bytes in total (4-byte lengths)");

    // 5. Fixed-size values are copied on assignment; a resizable is not
    //    copied unless the program says so, because that copy is O(n).
    var a: i64[>..] = [1, 2, 3];
    var b = copy(a);
    b.push(4);
    var item2 = items[1];                // a copy: Item is fixed-size
    item2.weight = 0.0;
    print(a, " ", b, " ", items[1].weight);

    // 6. A grow-shrink array pops as well: the natural stack, queue and
    //    scratch heap. References into it live in variables only, so a pop
    //    can never leave a stored reference behind.
    var stack: i64[>..<] = [];
    for i in 5 { stack.push(i * 10); }
    var popped = 0;
    while stack.len > 2 { popped += stack.pop(); }
    print(stack, " popped ", popped);

    // 7. Limited arrays live inline: a struct with two of them is one flat
    //    value with a fixed size, so an array of them is indexable and every
    //    row is next to the previous one in memory.
    var rows: Row[>..] = [];
    for r in 3 {
        var row = Row { label: "row", cells: [] };
        format(row.label, r);
        for c in r + 1 { row.cells.push((r * 10 + c) as i32); }
        rows.push(row);
    }
    for row in rows { print(row.label, ": ", row.cells, " (", row.cells.len, "/", row.cells.cap, ")"); }

    // 8. When lifetimes really are not nested -- a cache, a mutable graph --
    //    a `slot_pool` keeps a freelist of slots. Every slot stays a
    //    valid Item forever, so a stale reference can read a wrong value but
    //    never corrupt memory; that is the whole extent of unsafety.
    var pool = slot_pool<Item> {};
    let s0 = pool.alloc_index(Item { 10, 1.0 });
    let s1 = pool.alloc_index(Item { 11, 1.0 });
    pool.free(s0);
    let s2 = pool.alloc_index(Item { 12, 2.0 });   // takes slot s0 back
    print("slots ", s0, " ", s1, " ", s2, ", pool length ", pool.items.len);
    let node: Item& = pool.alloc_ref(Item { 13, 3.0 });
    pool.free_ref(node);
    print("pool length ", pool.items.len);
}

// Strings. There is no string type: a string is any u8 array, a string
// literal is static bytes, a builder is a growable u8 array, and a "view"
// into text is a u8 slice that the checker keeps from dangling. This
// program does the usual things -- build, search, split, parse, format --
// and never copies a byte it does not have to.
//
// Build and run (from this directory):
//   goose -o strings.c 03_strings.goose && cl strings.c && strings

import std;

// A struct with an inline small string: no pointer, no allocation, and a
// `format` overload so print/str/format render it the way it wants.
struct Person { name: u8[..16], age: i32 }

fn format(out: u8[>..]&, p: Person) {
    format(out, p.name, " (", p.age, ")");
}

fn main() {
    // --- building ----------------------------------------------------------
    // A builder is a grow-only byte array on the data stack: appending is a
    // pointer bump, nothing is reallocated, and it goes away with the scope.
    var s: u8[>..] = [];                 // the builder: append, push, format
    s.append("Hello");
    s.push(',');
    s.push(' ');
    format(s, "world! ", 6 * 7, " ", 2.5);
    print(s, " [", s.len, " bytes]");
    let joined = str("pi=", 3.14159, " e=", 2.71828);   // a fresh string, built straight into joined
    print(joined);
    // Padded and based numbers, fixed decimals.
    var t: u8[>..] = [];
    format_int(t, 255, 16, 4, '0'); t.push(' ');
    format_int(t, 255, 2, 10, ' '); t.push(' ');
    format_flt(t, 2.0 / 3.0, 3);
    print(t);

    // --- views into text ---------------------------------------------------
    // A slice is a reference plus a length: `line[a..b]` is the text between
    // a and b, no copy. trim/split/find return slices into the input.
    let line = "  key = some value  ";
    let body = trim(line);
    let eq = find(body, "=");
    let key = trim(body[..eq]);
    let value = trim(body[eq + 1..]);
    print("'", body, "' -> '", key, "' / '", value, "'");
    print(starts_with(body, "key"), " ", ends_with(body, "value"), " ", find(body, "zzz"));

    // --- splitting -----------------------------------------------------------
    // split returns an array of slices into its input: a few bytes per part
    // and no text copied, where most languages hand back a list of strings.
    let csv = "alice,30,paris,,bob,25";
    let parts = split(csv, ',');         // an array of slices, all into csv
    print(parts.len, " parts: ", parts);
    var upper: u8[>..] = [];
    each_split("one two  three", ' ') {  // no array built: a block per part
        if it.len > 0 {
            upper.append(it);
            to_upper(upper[^it.len..]);  // in place, on the copy just appended
            upper.push('|');
        }
    };
    print(upper);
    var out: u8[>..] = [];
    join(out, parts, " | ");
    print(out);

    // --- parsing -------------------------------------------------------------
    for p in parts {
        let v, ok = parse_int(p);
        if ok { print("  number ", v); } else { print("  text '", p, "'"); }
    }
    let f, fok = parse_flt("-2.5e3");
    print(f, " ", fok);
    let h, hok = parse_int("ff", 16);
    print(h, " ", hok);

    // --- comparing and sorting -------------------------------------------
    // An array of variable-size strings cannot be sorted in place (its
    // elements are not all the same size), but an array of slices into it
    // can, and that sorts the strings without moving a byte of text.
    var names: u8[][>..] = [];
    names.push("delta"); names.push("alpha"); names.push("charlie"); names.push("bravo");
    var views: u8[:][>..] = [];
    for n in names { views.push(n[..]); }
    sort(views) { a, b => compare(a, b) < 0 };
    print(views);
    print(compare("abc", "abd"), " ", compare("b", "a"), " ", "abc" == "abc");

    // --- replacing, case -------------------------------------------------
    var r: u8[>..] = [];
    format_replaced(r, "the cat sat on the mat", "at", "og");
    print(r);
    var lower: u8[>..] = [];
    lower.append("MiXeD Case");
    to_lower(lower);
    print(lower);

    // --- bytes and code points -------------------------------------------
    // Text is bytes; UTF-8 is a convention the library understands.
    let greek = "αβγ";
    print(greek.len, " bytes, ", greek[0], " first byte");
    var cps = 0;
    each_utf8(greek) { cps++; };
    var back: u8[>..] = [];
    each_utf8(greek) { push_utf8(back, it + 1); };   // the next letter each
    print(cps, " code points; shifted: ", back);
    // A byte is a number: print shows 97, and it takes a push to append one.
    var caps: u8[>..] = [];
    for c in "abc" { caps.push(c - 'a' + 'A'); }
    print("abc"[0], " ", caps, " ", str('a'));

    // --- inline strings in structs -----------------------------------------
    // A Person is one flat value: the name's bytes live in the struct, so an
    // array of them is a single block, sortable and copyable as plain data.
    var people: Person[>..] = [];
    people.push(Person { name: "ada", age: 36 });
    people.push(Person { name: "grace", age: 45 });
    var p2 = Person { name: "", age: 20 };
    format(p2.name, "linus");            // a limited array is a builder too, up to its capacity
    people.push(p2);
    print(people);
    for &p in people { p.age += 1; }
    print(str(people[0]), " ", people[2].name.len, "/", people[2].name.cap);
}

// Error handling. Goose has no exceptions and no Result type; it has three
// idioms, and this program uses each where it fits: a trailing bool (or
// code) for a two-outcome call, an optional for "found or not", and
// `return ... from` for a failure deep inside nested calls that should land
// in one place. Plus the ones that end the program: assert and abort.
//
// Build and run (from this directory):
//   goose -o errors.c 04_errors.goose && cl errors.c && errors

import std;

struct User { name: u8[..16], age: i32 }

// 1. A trailing bool: the caller writes `let v, ok = ...` and tests ok.
fn parse_age(s: u8[:]) -> i32, bool {
    let v, ok = parse_int(trim(s));
    if !ok || v < 0 || v > 150 { return 0, false; }
    return v as i32, true;
}

// 2. An optional: a reference to the element, or null. The caller must
//    narrow it with if/guard before touching it.
fn find_user(users: User[:], name: u8[:]) -> User? {
    for &u in users { if u.name == name { return u; } }
    return null;
}

// 3. return-from: any failure inside the nested parsing below returns from
//    `load` directly, unwinding parse_record and parse_field with it. Those
//    two return plain values and carry no error type, and the happy path
//    pays nothing for the possibility. The error is the last result, by
//    convention; "" means none.
fn load(text: u8[:]) -> User[>..], u8[] {
    var users: User[>..] = [];
    var lineno = 0;
    each_split(text, '\n') {
        lineno++;
        if it.len > 0 { users.push(parse_record(it, lineno)); }   // built straight into the element
    };
    return users, "";
}

fn parse_record(line: u8[:], lineno: i64) -> User {
    let comma = find(line, ",");
    guard comma >= 0 else { return [], str("line ", lineno, ": expected name,age") from load; }
    let name = parse_field(line[..comma], lineno);
    let age, ok = parse_age(line[comma + 1..]);
    guard ok else { return [], str("line ", lineno, ": bad age '", trim(line[comma + 1..]), "'") from load; }
    return User { name: name, age: age };
}

fn parse_field(s: u8[:], lineno: i64) -> u8[..16] {
    let t = trim(s);
    guard t.len > 0 else { return [], str("line ", lineno, ": empty name") from load; }
    guard t.len <= 16 else { return [], str("line ", lineno, ": name too long") from load; }
    return t;
}

fn report(text: u8[:]) {
    let users, err = load(text);
    if err.len > 0 { print("error: ", err); return; }
    print("loaded ", users.len, " users");
    for u in users { print("  ", u.name, " ", u.age); }
}

fn main() {
    // A two-outcome call, tested inline.
    for s in ["42", " 7 ", "-3", "abc", "200"] {
        let age, ok = parse_age(s);
        if ok { print("'", s, "' -> ", age); } else { print("'", s, "' is not an age"); }
    }

    // An optional, narrowed by `if` and by `guard`.
    var users: User[>..] = [];
    users.push(User { name: "ada", age: 36 });
    users.push(User { name: "linus", age: 20 });
    let found = find_user(users, "linus");
    if found { print("found ", found.name, ", age ", found.age); }
    let missing = find_user(users, "nobody");
    if missing == null { print("nobody is not a user"); }
    block {
        let u = find_user(users, "ada");
        guard u else { print("no ada"); break; }
        u.age += 1;                      // narrowed: a plain reference here
        print("ada is now ", u.age);
    }

    // Deep failures landing in one place.
    report("ada, 36\nlinus, 20\n");
    report("ada, 36\nlinus\n");
    report("ada, 36\n, 20\n");
    report("ada, x\n");
    report("averyveryverylongname, 1\n");

    // The ones that stop the program: assert for invariants, abort for a
    // fatal condition with a message, exit for a deliberate end with a code.
    // None of them fire here.
    assert(users.len == 2);
    if users.len > 100 { abort("too many users"); }
    if users.len == 0 { exit(1); }
    print("done");
}

// Algebraic data types, the only dynamic polymorphism in the language: no
// inheritance, no vtables. The classic shapes example, with the two things
// that make Goose's version different -- an enum value can be stored
// *fixed* (every value the size of the largest variant, indexable and
// overwritable) or *variable* (each value exactly its variant's size, text
// included, walked sequentially or reached through an index kept beside the
// array) -- and case functions, which are `match` written as an overload
// set: the virtual-call idiom.
//
// Build and run (from this directory):
//   goose -o shapes.c 05_shapes.goose && cl shapes.c && shapes

import math;

enum Shape {
    Circle { r: f64 },
    Rect { w: f64, h: f64 },
    Tri { a: f64, b: f64, c: f64 },
    Dot,
}

// Case functions: one overload per variant, called with the enum value.
// The call dispatches on the tag; the checker requires every variant to
// have exactly one applicable overload, so a new variant is a compile error
// here until it gets its case.
fn area(s: Shape.Circle) -> f64 { PI * s.r * s.r }
fn area(s: Shape.Rect) -> f64 { s.w * s.h }
fn area(s: Shape.Tri) -> f64 {
    let p = (s.a + s.b + s.c) / 2.0;     // Heron's formula
    sqrt(p * (p - s.a) * (p - s.b) * (p - s.c))
}
fn area(s: Shape.Dot) -> f64 { 0.0 }

fn sides(s: Shape.Circle) -> i64 { 0 }
fn sides(s: Shape.Rect) -> i64 { 4 }
fn sides(s: Shape.Tri) -> i64 { 3 }
fn sides(s: Shape.Dot) -> i64 { 0 }

// `match` is the inline form; `_` covers the rest.
fn name(s: Shape) -> u8[:] {
    match s {
        Circle c => "circle",
        Rect r => if r.w == r.h { "square" } else { "rectangle" },
        _ => "other",
    }
}

// Scaling a fixed-mode value in place: the whole value is replaced, which
// is allowed exactly because nothing can point inside a fixed-mode payload.
fn scaled(s: Shape, k: f64) -> Shape {
    match s {
        Circle c => Shape.Circle { r: c.r * k },
        Rect r => Shape.Rect { w: r.w * k, h: r.h * k },
        Tri t => Shape.Tri { a: t.a * k, b: t.b * k, c: t.c * k },
        Dot => Shape.Dot,
    }
}

// A drawing's marks: shapes, and labels with text. A Label holds its text
// itself, a varint length and then the bytes, right after the tag, so the
// marks in a variable-mode array are one flat run of bytes, strings
// included, with no pointer anywhere. (An enum in Rust or C++ has one fixed
// size: its string variant would be a fixed-size string object, and every
// element would be as big as the largest variant.) The text makes Mark a
// variable-size type, so it is only ever stored in variable mode.
enum Mark {
    Circle { r: f64 },
    Rect { w: f64, h: f64 },
    Label { text: u8[varint] },
    Dot,
}

// Packed marks have no fixed stride, so `marks` cannot be indexed, but an
// index beside it can be: each entry is one mark's offset from the base of
// `marks` (`in marks`, 4 bytes), and loading one is an add. The array such
// offsets are measured from is a global; a local array can be indexed the
// same way with plain 8-byte references, `(Mark..&)[>..]`.
var marks:   Mark..[>..]                  = [];
var mark_at: (Mark..&<u32 in marks>)[>..] = [];

fn main() {
    // --- fixed mode: an ordinary array of enum values ----------------------
    // Each element is 1 tag byte + the largest payload (three f64s): 25 bytes,
    // the layout a Rust enum or a C++ variant also has; `match` reads the
    // payload in place, with no boxing and no virtual call.
    var shapes: Shape[>..] = [];
    shapes.push(Shape.Circle { r: 1.0 });
    shapes.push(Shape.Rect { w: 2.0, h: 3.0 });
    shapes.push(Shape.Tri { a: 3.0, b: 4.0, c: 5.0 });
    shapes.push(Shape.Dot);
    shapes.push(Shape.Rect { w: 2.0, h: 2.0 });
    var total = 0.0;
    for s in shapes {
        print(name(s), " ", s, " area ", area(s), " sides ", sides(s));
        total += area(s);
    }
    print("total area ", total);
    // Indexable and replaceable: element 3 becomes a different variant.
    shapes[3] = Shape.Circle { r: 0.5 };
    for &s in shapes { s = scaled(s, 2.0); }
    print(shapes);

    // --- variable mode: each element as big as its own variant -------------
    // A Dot is 1 byte, a Circle 9, a Rect 17: half the memory of the fixed
    // array for this mix. The price is sequential access: no indexing (short
    // of keeping an index, below), and an element can never change variant,
    // since its neighbors are packed right behind it. In exchange, references
    // into a payload are allowed.
    var packed: Shape..[>..] = [];
    packed.push(Shape.Circle { r: 1.0 });
    packed.push(Shape.Dot);
    packed.push(Shape.Rect { w: 2.0, h: 3.0 });
    packed.push(Shape.Dot);
    packed.push(Shape.Tri { a: 3.0, b: 4.0, c: 5.0 });
    var dots = 0;
    var widest = 0.0;
    for s in packed {                    // variable-size elements bind by reference
        match s {
            Dot => block { dots++; },
            Rect &r => block { r.w += 1.0; widest = r.w; },   // edits the payload in place, inside the array
            _ => block {},
        }
        print(name(s), " ", area(s));
    }
    print(dots, " dots, widest rect now ", widest);
    print(packed);

    // --- variable mode with an index: random access ------------------------
    // push builds each mark in place at the end of `marks` and returns a
    // reference to it, which the index keeps as that mark's offset.
    mark_at.push(marks.push(Mark.Label { text: "hello, goose" }));
    mark_at.push(marks.push(Mark.Circle { r: 1.5 }));
    mark_at.push(marks.push(Mark.Dot));
    mark_at.push(marks.push(Mark.Rect { w: 2.0, h: 3.0 }));
    mark_at.push(marks.push(Mark.Label { text: "x" }));
    for i in [3, 0, 4, 1, 2] {           // any order; each lookup is one add
        match mark_at[i] {
            Circle c => print(i, ": circle ", c.r),
            Rect r => print(i, ": rect ", r.w, " by ", r.h),
            Label l => print(i, ": label \"", l.text, "\""),
            Dot => print(i, ": dot"),
        }
    }
    // A Label is its tag, a 1-byte length and its text: 14 + 9 + 1 + 17 + 3.
    print(marks.len, " marks in ", bytes_of(marks).len, " bytes");
}

// Functions: generics without declaring them, overloading, UFCS, function
// values that compile to plain loops, nested functions that see their
// enclosing locals, and a `return` from inside a block that leaves the
// whole enclosing function. Everything here is resolved at compile time;
// there are no function pointers and nothing is boxed.
//
// Build and run (from this directory):
//   goose -o functions.c 06_functions.goose && cl functions.c && functions

import std;

// An untyped parameter is a generic one: the function is compiled once per
// argument type it is called with.
fn twice(x) { x + x }

// Explicit type parameters say that two arguments must agree.
fn span<T>(a: T, b: T) -> T { if a > b { a - b } else { b - a } }

// Overloads resolve on the argument types; a slice parameter takes any
// array kind, or a sub-range of one.
fn describe(x: i64) -> u8[>..] { str("int ", x) }
fn describe(x: f64) -> u8[>..] { str("float ", x) }
fn describe(xs: i64[:]) -> u8[>..] { str(xs.len, " ints, first ", xs[0]) }

// A higher-order function: F is a function value, a compile-time parameter.
// Calling F(...) inlines the block; this compiles to the loop it looks like.
fn each_pair<T, F>(xs: T[:]) {
    for i in 0..xs.len - 1 { F(xs[i], xs[i + 1]); }
}

// A HOF may return what its block produces, without saying what that is:
// the block is typechecked at each call, so U is whatever F returns.
fn best_by<T, F>(xs: T[:]) -> T {
    var b = xs[0];
    var bk = F(b);
    for x in xs[1..] {
        let k = F(x);
        if k > bk { b = x; bk = k; }
    }
    return b;
}

// A HOF that stops early: the block may `return` from the *caller*, which
// gives a hand-written iterator the same power as a for loop.
fn each_step<F>(lo: i64, hi: i64, step: i64) {
    var i = lo;
    while i < hi { F(i); i += step; }
}

struct Employee { name: u8[..12], dept: u8[..8], salary: i32 }

// The function that `return`s through each_step.
fn first_multiple_of_7(lo: i64, hi: i64) -> i64 {
    each_step(lo, hi, 3) { if it % 7 == 0 { return it; } };
    return -1;
}

fn main() {
    print(twice(21), " ", twice(1.5), " ", span(3, 8), " ", span(2.5, 1.0));
    var xs: i64[>..] = [4, 8, 15, 16, 23, 42];
    // UFCS: x.f(a) is f(x, a), for any function.
    print(describe(7), "; ", 2.5.describe(), "; ", xs.describe(), "; ", describe(xs[2..]));
    print(twice(3).describe());

    // Blocks: the implicit `it`, or named parameters. No allocation, no
    // indirect call: each one is compiled into its caller.
    var gaps: i64[>..] = [];
    each_pair(xs) { a, b => gaps.push(b - a); };   // writes an enclosing local
    print("gaps ", gaps);
    print("biggest gap ", max(gaps), " at ", max_by(gaps) { it });
    print(first_multiple_of_7(10, 40), " ", first_multiple_of_7(10, 12));

    // The standard library is written this way too. filter and map build
    // their result straight into the variable receiving it: no intermediate
    // array, no allocation, and the block is inlined into their loop.
    let evens = xs.filter() { it % 2 == 0 };
    let squares = xs.map() { it * it };
    let total = fold(xs, 0) { acc, x => acc + x };
    print(evens, " ", squares, " ", total, " ", xs.any() { it > 40 }, " ", xs.count() { it < 10 });

    var staff: Employee[>..] = [];
    staff.push(Employee { name: "ada", dept: "eng", salary: 120 });
    staff.push(Employee { name: "grace", dept: "eng", salary: 135 });
    staff.push(Employee { name: "linus", dept: "ops", salary: 90 });
    staff.push(Employee { name: "ken", dept: "ops", salary: 95 });
    let top = best_by(staff) { it.salary };
    print("top earner ", top.name);
    sort(staff) { a, b => a.salary > b.salary };
    for e in staff { print("  ", e.name, " ", e.dept, " ", e.salary); }

    // A nested function reads and writes the locals around it, like a block,
    // and can be called by name more than once.
    var budget = 0;
    var seen = 0;
    fn spend(e: Employee&) {
        budget += e.salary;
        seen++;
    }
    for &e in staff { if e.dept == "eng" { spend(e); } }
    print("eng budget ", budget, " over ", seen, " people");

    // A named function as a value, where a block would be too long.
    fn by_name(a: Employee, b: Employee) -> bool { compare(a.name[..], b.name[..]) < 0 }
    sort(staff, by_name);
    for e in staff { print("  ", e.name); }
}

// The sieve of Eratosthenes: the classic tight loop. Everything here runs
// at the width it is declared at -- the flags are bytes, the loop counters
// are i32 -- and the compiler proves every index in range, so the inner
// loop is the same three instructions C would emit, with a bounds check
// nowhere in sight.
//
// Build and run (from this directory):
//   goose -o sieve.c 07_sieve.goose && cl sieve.c && sieve

import std;
import os;

let N = 10000000;

fn main() {
    // One byte per candidate, all "prime" until crossed out: ten million
    // bytes in one block, filled in place by resize.
    var flags: u8[>..] = [];
    flags.resize(N + 1, 1);
    flags[0] = 0;
    flags[1] = 0;
    let t0 = clock();
    var i = 2;
    while i * i <= N {
        if flags[i] == 1 {
            // Cross out the multiples from i*i on: smaller ones were hit
            // by a smaller prime already.
            var j = i * i;
            while j <= N { flags[j] = 0; j += i; }
        }
        i++;
    }
    let t1 = clock();

    // Collect the primes. `%` is Euclidean, so bucketing by residue needs
    // no care about signs; here it counts the primes by their last digit.
    var primes:        i32[>..] = [];
    var by_last_digit: i64[10]  = [0; 10];
    for n, k in flags {
        if n == 1 {
            primes.push(k as i32);
            by_last_digit[k % 10] += 1;
        }
    }
    // Twin primes: pairs two apart.
    var twins = 0;
    for k in 1..primes.len {
        if primes[k] - primes[k - 1] == 2 { twins++; }
    }
    print(primes.len, " primes up to ", N);
    // Timing goes to stderr, so the output proper stays the same run to run.
    var note: u8[>..] = [];
    format(note, "sieve took ");
    format_flt(note, (t1 - t0) * 1000.0, 1);
    format(note, " ms\n");
    write_stderr(note);
    print("last ten: ", primes[^10..]);
    print("twin pairs: ", twins);
    print("by last digit: ", by_last_digit);
    // A checksum in wrapping unsigned arithmetic, which is what unsigned
    // types mean: no overflow checks, no surprises.
    var h: u32 = 0;
    for p in primes { h = h * 31 + p as u32; }
    print("hash ", h);
}

// Arbitrary-precision integers on an array of 32-bit limbs, least
// significant first. Multiplying two limbs needs a 64-bit product and a
// carry, which is exactly the arithmetic Goose's typed integers express:
// `u32 * u32` is a 32-bit multiply, so the code says `as u64` where it
// wants the wide one, and the carries are visible instead of accidental.
// Computes 100!, the 500th Fibonacci number and 2^1000, and prints them in
// decimal with repeated division.
//
// Build and run (from this directory):
//   goose -o bignum.c 08_bignum.goose && cl bignum.c && bignum

import std;

let BASE: u64 = 4294967296;              // 2^32

// A number is its limbs; the value 0 is an empty array. Grow-only is
// enough: normalizing pops leading zero limbs, which a grow-only array
// allows wherever nothing in scope refers into it, and nothing ever points
// into a number. Fresh results are built into whatever receives them, so
// `let f = factorial(100)` allocates nothing on the way.
fn from_int(v: u64) -> u32[>..] {
    var n: u32[>..] = [];
    var x = v;
    while x > 0 { n.push(x as! u32); x = x >> 32; }
    return n;
}

// n = n * m + a, in place: one pass over the limbs with a running carry.
fn mul_add_small(n: u32[>..]&, m: u32, a: u32) {
    var carry = a as u64;
    for &limb in n {
        let t = limb as u64 * m + carry;   // a 64-bit multiply; u32 * u32 would wrap at 32
        limb = t as! u32;                // the low half stays, the rest carries
        carry = t >> 32;
    }
    if carry > 0 { n.push(carry as! u32); }
}

fn add(a: u32[:], b: u32[:]) -> u32[>..] {
    var r:     u32[>..] = [];
    var carry: u64      = 0;
    for i in max(a.len, b.len) {
        let x: u64 = if i < a.len { a[i] } else { 0 };
        let y: u64 = if i < b.len { b[i] } else { 0 };
        let t = x + y + carry;
        r.push(t as! u32);
        carry = t >> 32;
    }
    if carry > 0 { r.push(carry as! u32); }
    return r;
}

// Schoolbook multiplication: r[i + j] accumulates a[i] * b[j].
fn mul(a: u32[:], b: u32[:]) -> u32[>..] {
    var r: u32[>..] = [];
    r.resize(a.len + b.len, 0);
    for i in a.len {
        var carry: u64 = 0;
        for j in b.len {
            let t = r[i + j] + a[i] as u64 * b[j] + carry;
            r[i + j] = t as! u32;
            carry = t >> 32;
        }
        r[i + b.len] = carry as! u32;
    }
    while r.len > 0 && r[r.len - 1] == 0 { r.pop(); }   // drop leading zeros
    return r;
}

// n / d in place, returning the remainder: the step decimal printing needs.
// The pop through the reference is checked at each call, against what the
// caller has in scope.
fn div_small(n: u32[>..]&, d: u32) -> u32 {
    var rem: u64 = 0;
    var i = n.len;
    while i > 0 {
        i--;
        let cur = rem << 32 | n[i];
        n[i] = (cur / d) as! u32;
        rem = cur % d;
    }
    while n.len > 0 && n[n.len - 1] == 0 { n.pop(); }
    return rem as! u32;
}

// Decimal text: peel off nine digits at a time from a working copy, then
// reverse the chunks into the output.
fn format(out: u8[>..]&, n: u32[>..]&) {
    if n.len == 0 { out.push('0'); return; }
    var work = copy(n);                  // the one copy, since division consumes its input
    var chunks: u32[>..] = [];           // nine decimal digits per entry, freed with the call
    while work.len > 0 {
        let chunk = div_small(work, 1000000000);
        chunks.push(chunk);
    }
    var first = true;
    each_rev(chunks) { c =>
        if first { format(out, c); first = false; }
        else { format_uint(out, c as u64, 10, 9, '0'); }
    };
}

fn factorial(k: i64) -> u32[>..] {
    var n = from_int(1);
    for i in 2..k + 1 { mul_add_small(n, i as u32, 0); }
    return n;
}

fn fib(k: i64) -> u32[>..] {
    var a = from_int(0);
    var b = from_int(1);
    for i in k {
        let c = add(a, b);
        a = copy(b);
        b = copy(c);
    }
    return a;
}

fn pow2(k: i64) -> u32[>..] {
    var n = from_int(1);
    for i in k { mul_add_small(n, 2, 0); }
    return n;
}

fn digits(n: u32[>..]&) -> i64 { str(n).len }

fn main() {
    let f100 = factorial(100);
    print("100! = ", f100);
    print("  ", f100.len, " limbs, ", digits(f100), " digits");
    let f500 = fib(500);
    print("fib(500) = ", f500);
    let p = pow2(1000);
    print("2^1000 has ", digits(p), " digits and ends in ...", str(p)[^12..]);
    // (2^500)^2 == 2^1000, through the general multiply.
    let h = pow2(500);
    let sq = mul(h, h);
    print("2^500 squared matches: ", sq == p);
    // 100! / (99 * 100) == 98!
    var q = copy(f100);
    div_small(q, 99);
    div_small(q, 100);
    print("100! / 9900 == 98!: ", q == factorial(98));
}

// Sorting and searching, written out: insertion sort, a recursive merge
// sort, and binary search, all over slices, so they work on any array kind
// and on any sub-range of one. Then the same jobs through the standard
// library, and timings on a million integers. The merge sort shows the one
// rule recursion has in Goose: a recursive function owns no growable
// locals, so the scratch buffer belongs to the caller and is passed in.
//
// Build and run (from this directory):
//   goose -o sorting.c 09_sorting.goose && cl sorting.c && sorting

import std;
import os;

fn insertion_sort(xs: i32[:]) {
    for i in 1..xs.len {
        let v = xs[i];
        var j = i;
        while j > 0 && xs[j - 1] > v {
            xs[j] = xs[j - 1];
            j--;
        }
        xs[j] = v;
    }
}

// Sorts xs using tmp (at least as long) as scratch. Both halves are
// sub-slices, so no index arithmetic leaks into the merge, and a call costs
// only native stack: nothing is allocated per level.
recursive fn merge_sort(xs: i32[:], tmp: i32[:]) {
    if xs.len <= 16 { insertion_sort(xs); return; }
    let mid = xs.len / 2;
    merge_sort(xs[..mid], tmp[..mid]);
    merge_sort(xs[mid..], tmp[mid..]);
    var i = 0;
    var j = mid;
    var k = 0;
    while i < mid && j < xs.len {
        if xs[j] < xs[i] { tmp[k] = xs[j]; j++; } else { tmp[k] = xs[i]; i++; }
        k++;
    }
    while i < mid { tmp[k] = xs[i]; i++; k++; }
    while j < xs.len { tmp[k] = xs[j]; j++; k++; }
    copy_into(xs, tmp[..xs.len]);
}

// The index of v in a sorted slice, or -1.
fn bsearch(xs: i32[:], v: i32) -> i64 {
    var lo = 0;
    var hi = xs.len;
    while lo < hi {
        let m = (lo + hi) / 2;
        if xs[m] < v { lo = m + 1; } else { hi = m; }
    }
    if lo < xs.len && xs[lo] == v { lo } else { -1 }
}

fn is_sorted(xs: i32[:]) -> bool {
    for i in 1..xs.len { if xs[i - 1] > xs[i] { return false; } }
    return true;
}

fn random_ints(n: i64, seed: u64) -> i32[>..] {
    var r = rng { seed };
    var xs: i32[>..] = [];
    for i in n { xs.push(r.rand_int(1000000) as i32); }
    return xs;
}

fn timed(label: u8[:], t0: f64) {
    var note: u8[>..] = [];
    format(note, label, ": ");
    format_flt(note, (clock() - t0) * 1000.0, 1);
    format(note, " ms\n");
    write_stderr(note);                  // stderr, so stdout stays deterministic
}

struct City { name: u8[..12], pop: i32 }

fn main() {
    // A small array, by hand.
    var small: i32[>..] = [5, 2, 9, 1, 5, 6, 3];
    insertion_sort(small);
    print(small, " ", is_sorted(small));
    print(bsearch(small, 6), " ", bsearch(small, 4), " ", bsearch(small, 1));
    // A sub-range: only the middle five are sorted.
    var part: i32[>..] = [9, 8, 7, 6, 5, 4, 3, 2, 1];
    insertion_sort(part[2..7]);
    print(part);

    // A million ints, three ways. The scratch is one buffer for the whole
    // recursion, made once.
    let n = 1000000;
    var a = random_ints(n, 1);
    var scratch: i32[>..] = [];
    scratch.resize(n, 0);
    var t = clock();
    merge_sort(a, scratch);
    timed("merge sort", t);
    print(is_sorted(a), " ", a[0], " ", a[n / 2], " ", a[n - 1]);

    var b = random_ints(n, 1);
    t = clock();
    sort(b);                             // the library's quicksort
    timed("std sort", t);
    print(a == b);

    var c = random_ints(20000, 1);
    t = clock();
    insertion_sort(c);
    timed("insertion sort (20000)", t);
    print(is_sorted(c));

    // Searching the sorted million: a hand-written and the library search
    // agree, on hits and on misses.
    var hits = 0;
    var agree = true;
    for i in 0..1000 {
        let v = (i * 997) as i32;
        let k = bsearch(a, v);
        let k2, found = binary_search(a, v);
        if k >= 0 { hits++; }
        if (k >= 0) != found { agree = false; }
    }
    print(hits, " hits, agree ", agree);

    // Structs sort by a comparator; stable_sort keeps equal keys in their
    // original order, which matters when sorting by one field of several.
    var cities: City[>..] = [];
    cities.push(City { name: "oslo", pop: 700 });
    cities.push(City { name: "lima", pop: 9700 });
    cities.push(City { name: "bern", pop: 130 });
    cities.push(City { name: "rome", pop: 2800 });
    cities.push(City { name: "riga", pop: 600 });
    sort(cities) { a, b => a.pop > b.pop };
    for c in cities { print("  ", c.name, " ", c.pop); }
    stable_sort(cities) { a, b => a.name[0] < b.name[0] };   // by first letter only
    for c in cities { print("  ", c.name, " ", c.pop); }
}

// A sudoku solver by backtracking. The board is 81 bytes and the "used"
// sets are bitmasks in u16s: three fixed arrays of nine, one bit per digit.
// The search always fills the cell with the fewest candidates first, which
// is what turns a hard puzzle from millions of guesses into hundreds.
// The whole state is one 135-byte struct passed by reference down the
// recursion, and nothing is allocated anywhere.
//
// Build and run (from this directory):
//   goose -o sudoku.c 10_sudoku.goose && cl sudoku.c && sudoku

import std;
import os;

// Three fixed arrays inline: 135 bytes and no pointers, so a Board copies as
// a memcpy and the solver edits it in place through one reference.
struct Board { cells: u8[81], rows: u16[9], cols: u16[9], boxes: u16[9] }

var guesses = 0;

fn bit(d: u8) -> u16 { (1 << d) as! u16 }
fn box_of(i: i64) -> i64 { (i / 27) * 3 + (i % 9) / 3 }

fn place(b: Board&, i: i64, d: u8) {
    b.cells[i] = d;
    b.rows[i / 9] |= bit(d);
    b.cols[i % 9] |= bit(d);
    b.boxes[box_of(i)] |= bit(d);
}

fn unplace(b: Board&, i: i64, d: u8) {
    b.cells[i] = 0;
    b.rows[i / 9] &= ~bit(d);
    b.cols[i % 9] &= ~bit(d);
    b.boxes[box_of(i)] &= ~bit(d);
}

// The digits still possible at cell i, as a mask.
fn candidates(b: Board&, i: i64) -> u16 {
    let used = b.rows[i / 9] | b.cols[i % 9] | b.boxes[box_of(i)];
    ~used & 0x3FE                        // bits 1..9
}

fn parse(text: u8[:]) -> Board {
    var b = Board { cells: [0; 81], rows: [0; 9], cols: [0; 9], boxes: [0; 9] };
    var i = 0;
    for c in text {
        if c >= '1' && c <= '9' { place(b, i, c - '0'); i++; }
        else if c == '.' || c == '0' { i++; }
    }
    assert(i == 81);
    return b;
}

recursive fn solve(b: Board&) -> bool {
    // Pick the empty cell with the fewest candidates.
    var best = -1;
    var bestn = 10;
    for i in 81 {
        guard b.cells[i] == 0 else { continue; }
        let n = popcount(candidates(b, i));
        if n < bestn { best = i; bestn = n; }
    }
    if best < 0 { return true; }         // no empty cell left: solved
    if bestn == 0 { return false; }      // a cell with no options: dead end
    let cands = candidates(b, best);
    for d in 1..10 {
        guard cands & bit(d as! u8) != 0 else { continue; }
        guesses++;
        place(b, best, d as! u8);
        if solve(b) { return true; }
        unplace(b, best, d as! u8);
    }
    return false;
}

fn show(b: Board&) {
    var line: u8[>..] = [];
    for r in 9 {
        line.clear();
        for c in 9 {
            let d = b.cells[r * 9 + c];
            line.push(if d == 0 { '.' } else { '0' + d });
            if c == 2 || c == 5 { line.append(" | "); } else if c < 8 { line.push(' '); }
        }
        print(line);
        if r == 2 || r == 5 { print("------+-------+------"); }
    }
}

fn run(name: u8[:], puzzle: u8[:]) {
    var b = parse(puzzle);
    print(name, ":");
    show(b);
    guesses = 0;
    let t0 = clock();
    let ok = solve(b);
    let ms = (clock() - t0) * 1000.0;
    print(if ok { "solved" } else { "no solution" }, " after ", guesses, " guesses");
    show(b);
    var note: u8[>..] = [];
    format(note, name, ": ");
    format_flt(note, ms, 2);
    format(note, " ms\n");
    write_stderr(note);
    print("");
}

fn main() {
    run("easy", "53..7....6..195....98....6.8...6...34..8.3..17...2...6.6....28....419..5....8..79");
    // Arto Inkala's 2012 "world's hardest sudoku".
    run("hard", "8..........36......7..9.2...5...7.......457.....1...3...1....68..85...1..9....4..");
    // Only 17 clues: the minimum for a unique solution.
    run("sparse", "...8.1..........435............7.8........1...2..3....6......75..34........2..6..");
}

// Shortest paths through a maze, two ways: breadth-first search for the
// fewest steps, then Dijkstra for the cheapest route once water costs
// three steps a square. The maze is a string literal, the grid a flat byte
// array indexed by y * W + x, the BFS queue a grow-only array with a read
// head, and the priority queue a grow-shrink array used as a binary heap
// through the library's heap_push/heap_pop with a comparator block.
//
// Build and run (from this directory):
//   goose -o maze.c 11_maze.goose && cl maze.c && maze

import std;

let MAZE = "####################\n#S.....#...........#\n#.####.#.#########.#\n#.#....#.#.......#.#\n#.#.####.#.#####.#.#\n#.#....~~~~~.....#.#\n#.####.~~~~~.#####.#\n#......~~~~~.......#\n#.#####.####.#####.#\n#..................#\n#.#########.####.#E#\n####################";

struct Cell { x: i32, y: i32 }
struct Entry { cost: i32, at: i32 }    // heap entries: cost first

// Grid state, filled in by main and read by the searches.
var grid: u8[>..] = [];
var W = 0;
var H = 0;

fn at(x: i64, y: i64) -> u8 { grid[y * W + x] }
fn passable(x: i64, y: i64) -> bool { x >= 0 && y >= 0 && x < W && y < H && at(x, y) != '#' }
fn step_cost(x: i64, y: i64) -> i32 { if at(x, y) == '~' { 3 } else { 1 } }

// The four neighbours of a cell index, as an array the caller iterates.
fn neighbours(i: i64) -> i64[4] {
    [i - 1, i + 1, i - W, i + W]
}

fn find_char(c: u8) -> i64 {
    for g, i in grid { if g == c { return i; } }
    abort("maze has no such cell");
}

// Breadth-first: every edge costs one, so the first visit is the shortest.
// `parent` records how each cell was reached, for drawing the path.
fn bfs(start: i64, goal: i64, parent: i32[>..]&) -> i64 {
    // The queue never pops: a read head walks it while pushes extend it, so
    // it is a grow-only array, freed whole when the function returns.
    var queue: i32[>..] = [];
    queue.push(start as i32);
    parent[start] = start as i32;
    var head = 0;
    while head < queue.len {
        let i = queue[head] as i64;
        head++;
        if i == goal { break; }
        for n in neighbours(i) {
            if passable(n % W, n / W) && parent[n] < 0 {
                parent[n] = i as i32;
                queue.push(n as i32);
            }
        }
    }
    // Count the steps back to the start.
    var steps = 0;
    var i = goal;
    while i != start { i = parent[i]; steps++; }
    return steps;
}

// Dijkstra: pop the cheapest frontier cell, relax its neighbours. Stale
// heap entries (a cell reached again more cheaply) are skipped when popped.
fn dijkstra(start: i64, goal: i64, parent: i32[>..]&) -> i32 {
    var dist: i32[>..] = [];
    dist.resize(grid.len, 1000000);
    var heap: Entry[>..<] = [];          // grow-shrink: heap_pop shrinks it
    dist[start] = 0;
    parent[start] = start as i32;
    heap.heap_push(Entry { cost: 0, at: start as i32 }) { a, b => a.cost < b.cost };
    while heap.len > 0 {
        let e = heap.heap_pop() { a, b => a.cost < b.cost };
        let i = e.at as i64;
        if e.cost > dist[i] { continue; }
        if i == goal { break; }
        for n in neighbours(i) {
            guard passable(n % W, n / W) else { continue; }
            let c = e.cost + step_cost(n % W, n / W);
            if c < dist[n] {
                dist[n] = c;
                parent[n] = i as i32;
                heap.heap_push(Entry { cost: c, at: n as i32 }) { a, b => a.cost < b.cost };
            }
        }
    }
    return dist[goal];
}

// The cost of a found path, summed back along the parent links.
fn path_cost(parent: i32[:], start: i64, goal: i64) -> i32 {
    var cost: i32 = 0;
    var i = goal;
    while i != start {
        cost += step_cost(i % W, i / W);
        i = parent[i];
    }
    return cost;
}

// The maze with the found path drawn onto a copy of the grid.
fn show(parent: i32[:], start: i64, goal: i64) {
    var pic = copy(grid);
    var i = goal;
    while i != start {
        i = parent[i];
        if i != start { pic[i] = if grid[i] == '~' { 'o' } else { '*' }; }
    }
    for y in H { print(pic[y * W..(y + 1) * W]); }
}

fn main() {
    // Rows of the literal become the grid; the width is the first row's.
    each_split(MAZE, '\n') {
        if W == 0 { W = it.len; }
        assert(it.len == W);
        grid.append(it);
        H++;
    };
    let start = find_char('S');
    let goal = find_char('E');
    print(W, "x", H, " maze, start at ", start % W, ",", start / W, " goal at ", goal % W, ",", goal / W);

    var parent: i32[>..] = [];
    parent.resize(grid.len, -1);
    let steps = bfs(start, goal, parent);
    print("BFS: ", steps, " steps, cost ", path_cost(parent, start, goal), " with water at 3");
    show(parent, start, goal);

    fill(parent, -1);
    let cost = dijkstra(start, goal, parent);
    print("Dijkstra: cost ", cost);
    show(parent, start, goal);
}

// Huffman coding, end to end: count byte frequencies, build the code tree
// with a priority queue, read the codes off the tree, pack the text into
// bits, and decode it again. The tree lives in one array of nodes whose
// links are 2-byte self-relative offsets -- a node is 10 bytes and the tree
// for a 256-symbol alphabet fits in 6 KB -- and the priority queue is a
// grow-shrink array of node indices heap-ordered by weight.
//
// Build and run (from this directory):
//   goose -o huffman.c 12_huffman.goose && cl huffman.c && huffman

import std;

// A leaf has a symbol; an inner node has two children. The links point
// within the `nodes` array the node is stored in, never anywhere else.
struct Node { weight: i32, sym: i16, left: Node&<u16>?, right: Node&<u16>? }
struct Code { bits: u32, len: u8 }

let TEXT = "it was the best of times, it was the worst of times, it was the age of wisdom, it was the age of foolishness, it was the epoch of belief, it was the epoch of incredulity, it was the season of light, it was the season of darkness, it was the spring of hope, it was the winter of despair, we had everything before us, we had nothing before us, we were all going direct to heaven, we were all going direct the other way";

// Walks the tree, recording the path to each leaf as its code. Recursion
// passes the table down by reference; the tree nodes are referenced through
// their relative links, which load as ordinary references.
recursive fn assign(n: Node&, bits: u32, len: i64, codes: Code[256]&) {
    if n.sym >= 0 {
        codes[n.sym] = Code { bits: bits, len: len as! u8 };
        return;
    }
    let l = n.left;
    let r = n.right;
    assert(l);
    assert(r);
    assign(l, bits << 1, len + 1, codes);
    assign(r, bits << 1 | 1, len + 1, codes);
}

fn main() {
    // 1. Frequencies.
    var freq: i32[256] = [0; 256];
    for c in TEXT { freq[c] += 1; }

    // 2. One leaf per used symbol, all in the priority queue.
    var nodes: Node[>..] = [];
    var heap:  i32[>..<] = [];
    for f, c in freq {
        if f > 0 {
            nodes.push(Node { weight: f, sym: c as i16 });
            heap.heap_push((nodes.len - 1) as i32) { a, b => nodes[a].weight < nodes[b].weight };
        }
    }
    print(heap.len, " distinct symbols in ", TEXT.len, " bytes");

    // 3. Merge the two lightest until one tree remains. The new node links
    //    to its children by offset within the same array it is pushed into:
    //    a 2-byte link instead of an 8-byte pointer, and a tree that can be
    //    copied or written out as one block of bytes.
    while heap.len > 1 {
        let a = heap.heap_pop() { a, b => nodes[a].weight < nodes[b].weight } as i64;
        let b = heap.heap_pop() { a, b => nodes[a].weight < nodes[b].weight } as i64;
        nodes.push(Node { weight: nodes[a].weight + nodes[b].weight, sym: -1,
                          left: nodes[a], right: nodes[b] });
        heap.heap_push((nodes.len - 1) as i32) { a, b => nodes[a].weight < nodes[b].weight };
    }
    let root .= nodes[heap.pop()];
    print(nodes.len, " nodes, ", nodes.bytes_of().len, " bytes of tree");

    // 4. Codes.
    var codes: Code[256] = [default<Code>(); 256];
    assign(root, 0, 0, codes);
    var line: u8[>..] = [];
    for c in "aeiost ," {
        line.clear();
        line.push('\'');
        if c == ' ' { line.append("space"); } else { line.push(c); }
        format(line, "' x", freq[c], ": ");
        format_uint(line, codes[c].bits, 2, codes[c].len, '0');
        print(line);
    }

    // 5. Encode: append each code's bits, most significant first, into a
    //    byte array; `nbits` is the real length. `&` binds tighter than
    //    `==`, so the bit test needs no extra parentheses.
    var packed: u8[>..] = [];
    var nbits = 0;
    for c in TEXT {
        let code = codes[c];
        var k = code.len as i64;
        while k > 0 {
            k--;
            if nbits % 8 == 0 { packed.push(0); }
            if (code.bits >> k) & 1 == 1 { packed[nbits / 8] |= (0x80 >> (nbits % 8)) as! u8; }
            nbits++;
        }
    }
    print(nbits, " bits = ", packed.len, " bytes; ", (packed.len * 100) / TEXT.len, "% of the original");

    // 6. Decode: walk from the root, one bit per step, emitting at leaves.
    var out: u8[>..] = [];
    var cur .= root;
    for i in nbits {
        let bit = (packed[i / 8] >> (7 - i % 8)) & 1;
        let next = if bit == 0 { cur.left } else { cur.right };
        assert(next);
        cur .= next;
        if cur.sym >= 0 {
            out.push(cur.sym as! u8);
            cur .= root;
        }
    }
    print("round trip ok: ", out == TEXT);
    print(out[..40]);
}

// A doubly-linked list the Goose way. The nodes live in a `slot_pool`:
// a grow-only array with a freelist, so removing a node hands its slot
// back and the next insertion takes it, with no allocator involved. The
// links are 4-byte offsets measured from the pool's base (`in pool.items`), and
// the list has a sentinel node whose links start out pointing at itself
// (`self`), so the list is never empty and no link is ever null: every
// insertion and removal is the same four stores, with no special cases.
//
// Build and run (from this directory):
//   goose -o linked_list.c 13_linked_list.goose && cl linked_list.c && linked_list

import slot_pool;
import std;

struct Node { val: i64, prev: Node&<u32 in pool.items>, next: Node&<u32 in pool.items> }

var pool = slot_pool<Node> {};
// The sentinel: slot 0, allocated before main runs.
let head = pool.alloc_index_with() { Node { val: 0, prev: self, next: self } };

// Inserts a node holding v after p, and returns it.
fn insert_after(p: Node&, v: i64) -> Node& {
    // alloc_with takes a free slot if there is one, else pushes; the links
    // are stored as offsets from the pool's base, so a node holds no
    // addresses at all.
    let n .= pool.alloc_with() { Node { val: v, prev: p, next: p.next } };
    n.next.prev .= n;
    p.next .= n;
    return n;
}

// Unlinks n and frees its slot. The node keeps its bytes -- a stale
// reference would read a valid Node -- but the slot is reused next.
fn remove(n: Node&) {
    n.prev.next .= n.next;
    n.next.prev .= n.prev;
    pool.free_ref(n);
}

fn push_front(v: i64) -> Node& { insert_after(pool.items[head], v) }
fn push_back(v: i64) -> Node& { insert_after(pool.items[head].prev, v) }
// The sentinel test is an identity test: `==` on references compares the
// nodes they point at, `.==` the references themselves.
fn is_end(n: Node&) -> bool { n .== pool.items[head] }

fn pop_front() -> i64 {
    let n .= pool.items[head].next;
    assert(!is_end(n));
    let v = n.val;
    remove(n);
    return v;
}

// Visits every node, front to back.
fn each<F>() {
    var n .= pool.items[head].next;
    while !is_end(n) {
        let next .= n.next;              // read before F, which may remove n
        F(n);
        n .= next;
    }
}

fn show(label: u8[:]) {
    var line: u8[>..] = [];
    format(line, label, ":");
    each() { format(line, " ", it.val); };
    format(line, "   (", pool.items.len, " slots)");
    print(line);
}

fn main() {
    for i in 1..6 { push_back(i * 10); }
    push_front(5);
    show("built");

    // Removal while iterating is fine: the iteration reads the next link
    // before handing the node over.
    each() { if it.val % 20 == 0 { remove(it); } };
    show("evens removed");

    // Freed slots come back: three inserts, no growth.
    push_back(7);
    push_back(8);
    push_back(9);
    show("three more");

    print("popped ", pop_front(), " and ", pop_front());
    show("after pops");

    // Move-to-front, the operation an LRU cache is made of: unlink and
    // relink through the references, without touching the pool's length.
    var n .= pool.items[head].next;
    while !is_end(n) {
        let next .= n.next;
        if n.val == 9 {
            n.prev.next .= n.next;
            n.next.prev .= n.prev;
            n.prev .= pool.items[head];
            n.next .= pool.items[head].next;
            n.next.prev .= n;
            pool.items[head].next .= n;
        }
        n .= next;
    }
    show("9 moved to front");

    // Walk backwards through the prev links.
    var back: u8[>..] = [];
    var b .= pool.items[head].prev;
    while !is_end(b) { format(back, " ", b.val); b .= b.prev; }
    print("backwards:", back);
    print("a node is ", 8 + 4 + 4, " bytes: the value and two 4-byte links");
}

// A binary search tree in one grow-only array of nodes. Children are
// 4-byte self-relative links: an offset from the link's own address to the
// child, which is what lets the whole tree be moved or saved as a block.
// A link that is null is the offset 0. Insertion walks down with one
// reference that is retargeted with `.=`, and the recursive walks pass
// their output array down by reference, since a recursive function cannot
// own growable data of its own.
//
// Build and run (from this directory):
//   goose -o bst.c 14_bst.goose && cl bst.c && bst

import std;

struct Node { key: i32, count: i32 = 1, left: Node&<u32>?, right: Node&<u32>? }

// The tree is the pool plus the convention that slot 0 is the root.
fn insert(pool: Node[>..]&, key: i32) {
    if pool.len == 0 { pool.push(Node { key: key }); return; }
    var cur .= pool[0];                  // .= binds the element; = would copy it
    // The walk retargets that one reference; a null child is the offset 0.
    loop {
        if key == cur.key { cur.count += 1; return; }
        if key < cur.key {
            let l = cur.left;
            if l { cur .= l; continue; }
            cur.left .= pool.push(Node { key: key });   // a push never moves cur
            return;
        }
        let r = cur.right;
        if r { cur .= r; continue; }
        cur.right .= pool.push(Node { key: key });
        return;
    }
}

fn find(pool: Node[>..]&, key: i32) -> Node? {
    guard pool.len > 0 else { return null; }
    var cur .= pool[0];
    loop {
        if key == cur.key { return cur; }
        let next = if key < cur.key { cur.left } else { cur.right };
        guard next else { return null; }
        cur .= next;
    }
}

fn min_key(pool: Node[>..]&) -> i32 {
    var cur .= pool[0];
    loop {
        let l = cur.left;
        guard l else { break; }          // leaves the loop when null
        cur .= l;
    }
    return cur.key;
}

fn max_key(pool: Node[>..]&) -> i32 {
    var cur .= pool[0];
    loop {
        let r = cur.right;
        guard r else { break; }
        cur .= r;
    }
    return cur.key;
}

recursive fn in_order(n: Node&, out: i32[>..]&) {
    let l = n.left;
    if l { in_order(l, out); }
    for i in n.count { out.push(n.key); }
    let r = n.right;
    if r { in_order(r, out); }
}

recursive fn height(n: Node&) -> i64 {
    var h = 0;
    let l = n.left;
    if l { h = height(l); }
    let r = n.right;
    if r { h = max(h, height(r)); }
    return h + 1;
}

// The keys in [lo, hi], in order, pruning subtrees that cannot contain any.
recursive fn range(n: Node&, lo: i32, hi: i32, out: i32[>..]&) {
    let l = n.left;
    if l && n.key > lo { range(l, lo, hi, out); }
    if n.key >= lo && n.key <= hi { out.push(n.key); }
    let r = n.right;
    if r && n.key < hi { range(r, lo, hi, out); }
}

fn main() {
    var pool: Node[>..] = [];
    var r = rng { 7 };
    var inserted = 0;
    for i in 1000 {
        insert(pool, r.rand_int(500) as i32);
        inserted++;
    }
    print(inserted, " inserts, ", pool.len, " distinct keys, ", pool.bytes_of().len, " bytes of tree");
    print("height ", height(pool[0]), ", min ", min_key(pool), ", max ", max_key(pool));

    var sorted: i32[>..] = [];
    in_order(pool[0], sorted);
    print(sorted.len, " keys in order, first ten ", sorted[..10]);
    var ok = true;
    for i in 1..sorted.len { if sorted[i - 1] > sorted[i] { ok = false; } }
    print("sorted: ", ok);

    for k in [17, 42, 250, 499] {
        let n = find(pool, k as i32);
        if n { print(k, " present, seen ", n.count, " times"); } else { print(k, " absent"); }
    }
    var mid: i32[>..] = [];
    range(pool[0], 240, 260, mid);
    print("keys in 240..260: ", mid);

    // A second tree from sorted input degenerates into a list; the height
    // shows why balanced trees exist.
    var chain: Node[>..] = [];
    for i in 100 { insert(chain, i as i32); }
    print("100 sorted inserts: height ", height(chain[0]));
}

// Word frequencies of a text file: the program every language's tutorial
// writes, with one Goose twist. The counting map is keyed by slices into
// the text itself, so no word is ever copied -- the text is read once into
// one buffer, lowercased in place, and every key, every table row and the
// final report point into it.
//
// Build and run (from this directory):
//   goose -o word_freq.c 15_word_freq.goose && cl word_freq.c && word_freq [file]

import std;
import dictionary;
import os;

struct Entry { word: u8[:], count: i32 }

fn is_letter(c: u8) -> bool { (c >= 'a' && c <= 'z') || c == '\'' }

fn main() {
    // The file to read: the first argument, or the bundled text.
    var path: u8[>..] = [];
    if arg_count() > 1 { arg(1, path); } else { path.append("data/alice.txt"); }
    var text: u8[>..] = [];
    guard read_file(path, text) else { print("cannot read ", path); exit(1); }
    to_lower(text);

    // Count. `update` inserts 0 on a first sighting and then runs the block
    // on the stored value, so one lookup does both. A key is a slice, an
    // address and a length into `text`: the dictionary stores no strings.
    var counts = dictionary<u8[:], i32> {};
    var total = 0;
    var longest = text[0..0];
    var i = 0;
    while i < text.len {
        while i < text.len && !is_letter(text[i]) { i++; }
        let start = i;
        while i < text.len && is_letter(text[i]) { i++; }
        guard i > start else { continue; }
        let word = text[start..i];
        counts.update(word, 0) { it += 1; };
        total++;
        if word.len > longest.len { longest = word; }
    }

    // Into an array of rows, sorted by count and then alphabetically. A row
    // is a slice and a count, so sorting moves no text either.
    var rows: Entry[>..] = [];
    counts.each() { w, n => rows.push(Entry { word: w, count: n }); };
    sort(rows) { a, b => a.count > b.count || (a.count == b.count && compare(a.word, b.word) < 0) };

    print(path, ": ", text.len, " bytes, ", total, " words, ", rows.len, " distinct");
    print("longest word: ", longest);
    var once = 0;
    for r in rows { if r.count == 1 { once++; } }
    print(once, " words appear once");
    print("");
    print("  count  word");
    for r in rows[..15] {
        var line: u8[>..] = [];          // fresh per row; the closing brace frees it
        format_int(line, r.count, 10, 7, ' ');
        format(line, "  ", r.word);
        print(line);
    }
}

// Records with variable-size parts, kept flat. An order has a customer
// name and a list of items, each with a SKU string: in most languages that
// is a struct owning a string and a vector of structs owning strings, an
// allocation per part. Here every order is one contiguous run of bytes --
// varint lengths and numbers, strings inline, items inline -- and the
// whole order book is one array of them. The report groups totals per
// customer with a dictionary keyed by slices into the orders.
//
// Build and run (from this directory):
//   goose -o records.c 16_records.goose && cl records.c && records

import std;
import dictionary;

// varint fields are as wide as their value needs: an item with a short SKU
// and small numbers is about ten bytes, and an order is its items laid end
// to end after its header. Nothing here is a pointer.
struct Item { sku: u8[varint], qty: varint, cents: varint }
struct Order { id: varint, customer: u8[varint], items: Item[varint] }
struct Row { name: u8[:], total: i64, orders: i32 }

// Money renders as dollars everywhere it is printed.
struct Money { cents: i64 }
fn format(out: u8[>..]&, m: Money) {
    format(out, "$", m.cents / 100, ".");
    format_int(out, m.cents % 100, 10, 2, '0');
}

let CSV = "1001,alice,SKU-441:2:1999;SKU-7:1:500\n1002,bob,SKU-12:10:250\n1003,alice,SKU-7:3:500;SKU-900:1:12999;SKU-441:1:1999\n1004,carol,SKU-12:1:250;SKU-13:1:275\n1005,bob,SKU-900:2:12999\n1006,dave,SKU-1:1:99\n1007,carol,SKU-441:4:1999;SKU-7:2:500;SKU-12:2:250;SKU-13:2:275\n";

// "SKU:qty:cents;..." into items, built straight into the order's field.
fn parse_items(field: u8[:]) -> Item[>..] {
    var items: Item[>..] = [];
    each_split(field, ';') {
        let parts = split(it, ':');
        assert(parts.len == 3);
        let qty, ok1 = parse_int(parts[1]);
        let cents, ok2 = parse_int(parts[2]);
        assert(ok1 && ok2);
        items.push(Item { sku: parts[0], qty: qty, cents: cents });
    };
    return items;
}

fn order_total(o: Order&) -> i64 {
    var t = 0;
    for item in o.items { t += item.qty * item.cents; }
    return t;
}

fn main() {
    // Parse: one record per line, each a variable-size value pushed onto
    // the book. Slices of the CSV text feed the string fields, which copy
    // the bytes into place; the items are built directly into their field.
    var book: Order[>..] = [];
    each_split(CSV, '\n') {
        guard it.len > 0;
        let f = split(it, ',');
        let id, ok = parse_int(f[0]);
        assert(ok && f.len == 3);
        book.push(Order { id: id, customer: f[1], items: parse_items(f[2]) });
    };

    // Walk the book: sequential, by reference, nothing copied out.
    var grand = 0;
    var items = 0;
    var biggest = 0;
    var biggest_id = 0;
    for o in book {
        let t = order_total(o);
        grand += t;
        items += o.items.len;
        if t > biggest { biggest = t; biggest_id = o.id; }
    }
    print(book.len, " orders, ", items, " items, ", Money { grand }, " in total");
    print("biggest order #", biggest_id, " at ", Money { biggest });
    for o in book { if o.id == biggest_id { print(o); } }

    // Per customer. The keys are the customer strings inside the book.
    var per = dictionary<u8[:], i64> {};
    for o in book { per.update(o.customer[..], 0) { it += order_total(o); }; }
    var rows: Row[>..] = [];
    per.each() { name, total => rows.push(Row { name: name, total: total, orders: 0 }); };
    for &r in rows {
        for o in book { if o.customer == r.name { r.orders += 1; } }
    }
    sort(rows) { a, b => a.total > b.total };
    print("");
    print("customer  orders  total");
    for r in rows {
        var line = str(r.name);          // a fresh builder per row, gone at the brace
        while line.len < 10 { line.push(' '); }
        format_int(line, r.orders, 10, 6, ' ');
        format(line, "  ", Money { r.total });
        print(line);
    }

    // Per SKU: quantities sold.
    var sold = dictionary<u8[:], i64> {};
    for o in book {
        for item in o.items { sold.update(item.sku[..], 0) { it += item.qty; }; }
    }
    var skus: Row[>..] = [];
    sold.each() { sku, qty => skus.push(Row { name: sku, total: qty, orders: 0 }); };
    sort(skus) { a, b => a.total > b.total || (a.total == b.total && compare(a.name, b.name) < 0) };
    print("");
    for s in skus { print(s.name, ": ", s.total, " sold"); }
}

// An interactive calculator: reads a line, tokenizes it, parses it by
// recursive descent straight to a value, and prints the result. Variables
// are kept in a dictionary, so `x = 3 * (2 + y)` works. The tokens, the
// cursor and the line are locals of `evaluate`, and the tokenizer and the
// recursive-descent functions are nested inside it, using those as free
// variables instead of passing them around. Errors are the interesting
// part: a bad token, a missing parenthesis or a division by zero can
// happen deep inside the recursion, and each one is a single
// `return ... from evaluate`, which unwinds every parse frame in between
// and lands the message at the one place that reports it.
//
// Build and run (from this directory):
//   goose -o calc.c 17_calc.goose && cl calc.c && calc < data/calc.stdin
// or run it without redirection and type expressions at the prompt.

import std;
import dictionary;
import math;
import os;

enum Token {
    Num { v: f64 },
    Name { at: i32, len: i32 },          // a slice of the line, by position
    Op { c: u8 },                        // + - * / ( ) = ^
    End,
}

var vars = dictionary<u8[..16], f64> {};

// The message for a stray operator, built outside the parsing cycle (a
// function in a recursive cycle cannot own a builder) and constructed
// straight into the error result.
fn unexpected(c: u8) -> u8[>..] {
    var msg: u8[>..] = [];
    format(msg, "unexpected '");
    msg.push(c);                         // the byte itself, where str(c) would print its number
    msg.push('\'');
    return msg;
}

// One line: `name = expr` or `expr`. Every deep failure returns here.
fn evaluate(line: u8[:]) -> f64, u8[] {
    // Tokens are fixed-mode enum values in a plain array: 9 bytes each,
    // indexable, and the parser walks them with one cursor. The array is a
    // fresh local per line, gone when evaluate returns.
    var tokens: Token[>..] = [];
    var pos = 0;

    fn tokenize() {
        var i = 0;
        while i < line.len {
            let c = line[i];
            if c == ' ' || c == '\t' { i++; continue; }
            if (c >= '0' && c <= '9') || c == '.' {
                let start = i;
                while i < line.len && ((line[i] >= '0' && line[i] <= '9') || line[i] == '.') { i++; }
                let v, ok = parse_flt(line[start..i]);
                guard ok else { return 0.0, str("bad number '", line[start..i], "'") from evaluate; }
                tokens.push(Token.Num { v: v });
                continue;
            }
            if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
                let start = i;
                while i < line.len && ((line[i] >= 'a' && line[i] <= 'z') || (line[i] >= 'A' && line[i] <= 'Z')) { i++; }
                guard i - start <= 16 else { return 0.0, "name too long" from evaluate; }
                tokens.push(Token.Name { at: start as i32, len: (i - start) as i32 });
                continue;
            }
            guard find("+-*/()=^", line[i..i + 1]) >= 0 else {
                return 0.0, str("unexpected character '", line[i..i + 1], "'") from evaluate;
            }
            tokens.push(Token.Op { c: c });
            i++;
        }
        tokens.push(Token.End);
    }

    // The token under the cursor, and tests for an operator character.
    fn peek_op(c: u8) -> bool { match tokens[pos] { Op o => o.c == c, _ => false } }
    fn peek_op_at(i: i64, c: u8) -> bool { match tokens[i] { Op o => o.c == c, _ => false } }
    fn peek_end() -> bool { match tokens[pos] { End => true, _ => false } }

    fn name_key(t: Token.Name) -> u8[..16] {
        var k: u8[..16] = [];
        k.append(line[t.at..t.at + t.len]);
        return k;
    }

    // expr := term (('+' | '-') term)*
    recursive fn parse_expr() -> f64 {
        var v = parse_term();
        loop {
            if peek_op('+') { pos++; v += parse_term(); }
            else if peek_op('-') { pos++; v -= parse_term(); }
            else { break; }
        }
        return v;
    }

    // term := power (('*' | '/') power)*
    recursive fn parse_term() -> f64 {
        var v = parse_power();
        loop {
            if peek_op('*') { pos++; v *= parse_power(); }
            else if peek_op('/') {
                pos++;
                let d = parse_power();
                guard d != 0.0 else { return 0.0, "division by zero" from evaluate; }
                v /= d;
            }
            else { break; }
        }
        return v;
    }

    // power := unary ('^' power)?     (right associative)
    recursive fn parse_power() -> f64 {
        let base = parse_unary();
        if peek_op('^') { pos++; return pow(base, parse_power()); }
        return base;
    }

    // unary := '-' unary | '(' expr ')' | number | name
    recursive fn parse_unary() -> f64 {
        if peek_op('-') { pos++; return 0.0 - parse_unary(); }
        if peek_op('(') {
            pos++;
            let v = parse_expr();
            guard peek_op(')') else { return 0.0, "expected ')'" from evaluate; }
            pos++;
            return v;
        }
        let t = tokens[pos];
        pos++;
        match t {
            Num n => n.v,
            Name nm => {
                let v = vars.get(name_key(nm));
                guard v else { return 0.0, str("unknown variable '", line[nm.at..nm.at + nm.len], "'") from evaluate; }
                v
            },
            Op o => { return 0.0, unexpected(o.c) from evaluate; },
            End => { return 0.0, "unexpected end of input" from evaluate; },
        }
    }

    tokenize();
    // An assignment is a name followed by '='.
    if tokens.len > 2 {
        match tokens[0] {
            Name nm => if peek_op_at(1, '=') {
                pos = 2;
                let v = parse_expr();
                guard peek_end() else { return 0.0, "trailing input" from evaluate; }
                vars.insert(name_key(nm), v);
                return v, "";
            },
            _ => {},
        }
    }
    let v = parse_expr();
    guard peek_end() else { return 0.0, "trailing input" from evaluate; }
    return v, "";
}

fn main() {
    vars.insert("pi", PI);
    vars.insert("e", 2.718281828459045);
    print("calc: expressions, `name = expr`, `quit`");
    var line: u8[>..] = [];
    loop {
        write_stdout("> ");
        flush_stdout();
        line.clear();                         // nothing points into it here
        guard read_line(line) else { break; } // false at the end of input
        let t = trim(line);
        if t.len == 0 { continue; }
        if t == "quit" { break; }
        let v, err = evaluate(line);
        if err.len > 0 { print("error: ", err); continue; }
        var out: u8[>..] = [];
        format_flt(out, v, 6);
        // Trim trailing zeros and a dangling point, so 3 prints as 3.
        while out.len > 1 && out[out.len - 1] == '0' { out.pop(); }
        if out[out.len - 1] == '.' { out.pop(); }
        print(out);
    }
    print("bye");
}

// A JSON parser and printer. The document becomes a tree of variable-mode
// enum values in one grow-only pool: a number is a tag and an f64, a
// string is a tag and its bytes, an array is a tag, a count and a link to
// its first child. Every link is a 4-byte self-relative offset within the
// pool, so the parsed document is a single contiguous block that could be
// copied or saved as it is. Children are parsed (and pushed) before their
// parent, and siblings are chained by patching the previous child's link.
// The parser's state -- the text, the cursor, a key buffer -- is a set of
// locals of `parse`, and the functions nested inside it, the recursive
// ones included, use them as free variables. Any syntax error, however
// deep, is one `return ... from parse` carrying the message and position
// back to the top.
//
// Build and run (from this directory):
//   goose -o json.c 18_json.goose && cl json.c && json [file.json]

import std;
import os;

// A node is a sibling link, a key (empty for array elements) and the
// value; the value's payload is exactly as large as its variant needs.
struct Node { next: Node&<u32>?, key: u8[varint], val: Json.. }

enum Json {
    Null,
    Bool { v: bool },
    Num { v: f64 },
    Str { s: u8[varint] },
    Arr { first: Node&<u32>?, count: varint },
    Obj { first: Node&<u32>?, count: varint },
}

var pool: Node[>..] = [];

// --- parsing -----------------------------------------------------------

// The root node, or null and a message. A function in the recursive cycle
// cannot own a growable value, but the cycle lives inside this function,
// whose locals outlive every activation of it: the key buffer is one.
fn parse(text: u8[:]) -> Node?, u8[>..] {
    var pos = 0;
    var keys: u8[>..] = [];              // object keys, decoded before their values

    fn skip_space() {
        while pos < text.len && (text[pos] == ' ' || text[pos] == '\n' || text[pos] == '\r' || text[pos] == '\t') { pos++; }
    }

    fn fail(what: u8[:]) -> u8[>..] { str(what, " at byte ", pos) }

    fn expect(c: u8) {
        skip_space();
        if pos < text.len && text[pos] == c { pos++; return; }
        var msg: u8[>..] = [];
        format(msg, "expected '");
        msg.push(c);                     // the byte itself: str(c) would print its number
        msg.push('\'');
        return null, fail(msg) from parse;
    }

    fn hex_digit(c: u8) -> i64 {
        if c >= '0' && c <= '9' { return c - '0'; }
        if c >= 'a' && c <= 'f' { return c - 'a' + 10; }
        if c >= 'A' && c <= 'F' { return c - 'A' + 10; }
        return null, fail("bad hex digit") from parse;
    }

    // A string's decoded bytes, built straight into the field that receives
    // them. Not part of the recursive cycle, so it may own a builder.
    fn parse_string() -> u8[>..] {
        expect('"');
        var s: u8[>..] = [];
        loop {
            guard pos < text.len else { return null, fail("unterminated string") from parse; }
            let c = text[pos];
            pos++;
            if c == '"' { break; }
            if c != '\\' { s.push(c); continue; }
            guard pos < text.len else { return null, fail("bad escape") from parse; }
            let e = text[pos];
            pos++;
            if e == 'n' { s.push('\n'); }
            else if e == 't' { s.push('\t'); }
            else if e == 'r' { s.push('\r'); }
            else if e == 'u' {
                guard pos + 4 <= text.len else { return null, fail("bad \\u escape") from parse; }
                var cp = 0;
                for i in 4 { cp = cp * 16 + hex_digit(text[pos + i]); }
                pos += 4;
                push_utf8(s, cp);
            }
            else { s.push(e); }          // \" \\ \/ and the rest
        }
        return s;
    }

    fn parse_number() -> f64 {
        let start = pos;
        while pos < text.len && ((text[pos] >= '0' && text[pos] <= '9') || text[pos] == '-' ||
                                 text[pos] == '+' || text[pos] == '.' || text[pos] == 'e' || text[pos] == 'E') { pos++; }
        let v, ok = parse_flt(text[start..pos]);
        guard ok else { return null, fail("bad number") from parse; }
        return v;
    }

    fn parse_word(w: u8[:]) {
        guard pos + w.len <= text.len && text[pos..pos + w.len] == w else { return null, fail("unexpected token") from parse; }
        pos += w.len;
    }

    // One child of a container: an object member (key, colon, value) or an
    // array element. The key is decoded into `keys` and handed down as a
    // slice of it; the node copies its bytes.
    recursive fn parse_child(is_obj: bool) -> Node& {
        if is_obj {
            let start = keys.len;
            keys.append(parse_string());
            expect(':');
            return parse_value(keys[start..]);
        }
        return parse_value("");
    }

    // One value, pushed onto the pool as a node with the given key; the
    // node it returns is what the caller links into its own chain.
    recursive fn parse_value(key: u8[:]) -> Node& {
        skip_space();
        guard pos < text.len else { return null, fail("unexpected end of input") from parse; }
        let c = text[pos];
        if c == '{' || c == '[' {
            let is_obj = c == '{';
            let close = if is_obj { '}' } else { ']' };
            pos++;
            skip_space();
            guard pos < text.len else { return null, fail("unclosed container") from parse; }
            var first: Node? = null;
            var count = 0;
            if text[pos] != close {
                // The first child, then the rest, each linked from the
                // previous one: the link is a fixed-width relative
                // reference, so it can be stored after the node was pushed.
                let head .= parse_child(is_obj);
                first .= head;
                var last .= head;
                count = 1;
                loop {
                    skip_space();
                    guard pos < text.len else { return null, fail("unclosed container") from parse; }
                    if text[pos] == close { break; }
                    expect(',');
                    let child .= parse_child(is_obj);
                    last.next .= child;
                    last .= child;
                    count++;
                }
            }
            pos++;
            if is_obj { return pool.push(Node { next: null, key: key, val: Json.Obj { first: first, count: count } }); }
            return pool.push(Node { next: null, key: key, val: Json.Arr { first: first, count: count } });
        }
        // A leaf is one push: the node is built at the end of the pool, the
        // decoded string straight into its payload, the key's bytes copied
        // in -- no intermediate node value anywhere.
        if c == '"' { return pool.push(Node { next: null, key: key, val: Json.Str { s: parse_string() } }); }
        if c == 't' { parse_word("true"); return pool.push(Node { next: null, key: key, val: Json.Bool { v: true } }); }
        if c == 'f' { parse_word("false"); return pool.push(Node { next: null, key: key, val: Json.Bool { v: false } }); }
        if c == 'n' { parse_word("null"); return pool.push(Node { next: null, key: key, val: Json.Null }); }
        return pool.push(Node { next: null, key: key, val: Json.Num { v: parse_number() } });
    }

    let root .= parse_value("");
    skip_space();
    guard pos == text.len else { return null, fail("trailing input") from parse; }
    return root, str("");
}

// --- printing ----------------------------------------------------------

fn quote(out: u8[>..]&, s: u8[:]) {
    out.push('"');
    for c in s {
        if c == '"' || c == '\\' { out.push('\\'); out.push(c); }
        else if c == '\n' { out.append("\\n"); }
        else if c == '\t' { out.append("\\t"); }
        else { out.push(c); }
    }
    out.push('"');
}

fn newline(out: u8[>..]&, indent: i64) {
    out.push('\n');
    for i in indent * 2 { out.push(' '); }
}

// Renders a node; `indent` < 0 means compact, no whitespace at all.
recursive fn render(n: Node&, out: u8[>..]&, indent: i64) {
    match n.val {
        Null => out.append("null"),
        Bool b => out.append(if b.v { "true" } else { "false" }),
        Num x => {
            // JSON has one number type; a whole one is written as an integer.
            let i = x.v as! i64;
            if i == x.v { format(out, i); } else { format(out, x.v); }
        },
        Str &s => quote(out, s.s),
        Arr &a => render_children(a.first, false, out, indent, '[', ']'),
        Obj &o => render_children(o.first, true, out, indent, '{', '}'),
    }
}

recursive fn render_children(first: Node?, keyed: bool, out: u8[>..]&, indent: i64, open: u8, close: u8) {
    out.push(open);
    var c = first;
    var i = 0;
    while c {                            // a plain reference inside the loop
        if i > 0 { out.push(','); }
        if indent >= 0 { newline(out, indent + 1); }
        if keyed { quote(out, c.key); out.push(':'); if indent >= 0 { out.push(' '); } }
        render(c, out, if indent >= 0 { indent + 1 } else { -1 });
        c .= c.next;
        i++;
    }
    if i > 0 && indent >= 0 { newline(out, indent); }
    out.push(close);
}

// --- querying ------------------------------------------------------------

// The member of an object named `key`, or null.
fn member(n: Node&, key: u8[:]) -> Node? {
    match n.val {
        Obj &o => {
            var c = o.first;
            while c {
                if c.key == key { return c; }
                c .= c.next;
            }
            null
        },
        _ => null,
    }
}

// Element i of an array, or null.
fn element(n: Node&, i: i64) -> Node? {
    match n.val {
        Arr &a => {
            var c = a.first;
            var k = 0;
            while c {
                if k == i { return c; }
                c .= c.next;
                k++;
            }
            null
        },
        _ => null,
    }
}

fn number_of(n: Node?) -> f64 {
    guard n else { return 0.0; }
    match n.val { Num x => x.v, _ => 0.0 }
}

fn main() {
    var path: u8[>..] = [];
    if arg_count() > 1 { arg(1, path); } else { path.append("data/sample.json"); }
    var src: u8[>..] = [];
    guard read_file(path, src) else { print("cannot read ", path); exit(1); }

    let root, err = parse(src);
    guard root else { print("parse error: ", err); exit(1); }
    print("parsed ", src.len, " bytes into ", pool.len, " nodes");

    var out: u8[>..] = [];
    render(root, out, 0);
    print(out);
    out.clear();
    render(root, out, -1);
    print("compact: ", out.len, " bytes");
    print(out);

    // Walking the tree by key and index.
    let name = member(root, "name");
    if name { var s: u8[>..] = []; render(name, s, -1); print("name = ", s); }
    let nested = member(root, "nested");
    if nested {
        let depth = member(nested, "depth");
        print("nested.depth = ", number_of(depth));
        let list = member(nested, "list");
        if list { print("nested.list[2] = ", number_of(element(list, 2))); }
    }
    let authors = member(root, "authors");
    if authors {
        var i = 0;
        loop {
            let a = element(authors, i);
            guard a else { break; }
            let born = number_of(member(a, "born"));
            var s: u8[>..] = [];
            let nm = member(a, "name");
            if nm { render(nm, s, -1); }
            print("author ", i, ": ", s, " born ", born);
            i++;
        }
    }

    // Errors land at `parse` with a position, from wherever they happened.
    for bad in ["[1, 2", "{\"a\" 1}", "[tru]", "\"abc", "{\"k\": [1, 2,]}", "1 2"] {
        let r, e = parse(bad);
        print("'", bad, "' -> ", e);
    }
}

// A stack-machine bytecode interpreter. The program is an array of
// instructions, each a fixed-mode enum value (a 1-byte opcode plus room for
// one operand), and the dispatch loop is a `match` over it: no function
// pointers, no switch on a byte you then have to decode, and a jump target
// is just an index into the same array. Two programs are assembled by
// hand: a countdown loop and an iterative factorial.
//
// Build and run (from this directory):
//   goose -o vm.c 19_vm.goose && cl vm.c && vm

import std;

enum Op {
    Push { v: i64 },                     // push a constant
    Load { slot: u8 },                   // push local variable `slot`
    Store { slot: u8 },                  // pop into local `slot`
    Add, Sub, Mul,                       // pop two, push the result
    Dup,                                 // duplicate the top
    Jump { to: u16 },                    // jump to instruction `to`
    JumpIfZero { to: u16 },              // pop; jump if it was zero
    Print,                               // pop and print
    Halt,
}

struct Vm { stack: i64[>..<] }

fn op_name(o: Op) -> u8[:] {
    match o {
        Push p => "push", Load l => "load", Store s => "store", Add => "add", Sub => "sub",
        Mul => "mul", Dup => "dup", Jump j => "jump", JumpIfZero j => "jz",
        Print => "print", Halt => "halt",
    }
}

// A listing: index, mnemonic, and the operand if there is one.
fn disassemble(code: Op[:]) {
    for o, i in code {
        var l: u8[>..] = [];
        format_int(l, i, 10, 3, ' ');
        format(l, "  ", op_name(o));
        match o {
            Push p => format(l, " ", p.v),
            Load v => format(l, " ", v.slot),
            Store v => format(l, " ", v.slot),
            Jump j => format(l, " ", j.to),
            JumpIfZero j => format(l, " ", j.to),
            _ => {},
        }
        print(l);
    }
}

// Runs code from instruction 0 until Halt; returns the number of
// instructions executed. The operand stack is a grow-shrink array, the
// locals a small fixed array. The `match` is a switch on the tag byte with
// the operand read in place, and a jump is an index store.
fn run(code: Op[:]) -> i64 {
    var stack:  i64[>..<] = [];
    var locals: i64[8]    = [0; 8];
    var pc = 0;
    var steps = 0;
    loop {
        let op = code[pc];
        pc++;
        steps++;
        match op {
            Push p => { stack.push(p.v); },
            Load l => { stack.push(locals[l.slot]); },
            Store s => { locals[s.slot] = stack.pop(); },
            Add => { let b = stack.pop(); let a = stack.pop(); stack.push(a + b); },
            Sub => { let b = stack.pop(); let a = stack.pop(); stack.push(a - b); },
            Mul => { let b = stack.pop(); let a = stack.pop(); stack.push(a * b); },
            Dup => { let a = stack.pop(); stack.push(a); stack.push(a); },
            Jump j => { pc = j.to; },
            JumpIfZero j => { if stack.pop() == 0 { pc = j.to; } },
            Print => { print("  out: ", stack.pop()); },
            Halt => { break; },
        }
    }
    return steps;
}

fn main() {
    // countdown: n = 3; while n != 0 { print n; n = n - 1 }
    var countdown: Op[>..] = [];
    countdown.push(Op.Push { v: 3 });
    countdown.push(Op.Store { slot: 0 });
    countdown.push(Op.Load { slot: 0 });         // 2: loop head
    countdown.push(Op.JumpIfZero { to: 10 });
    countdown.push(Op.Load { slot: 0 });
    countdown.push(Op.Print);
    countdown.push(Op.Load { slot: 0 });
    countdown.push(Op.Push { v: 1 });
    countdown.push(Op.Sub);
    countdown.push(Op.Store { slot: 0 });
    countdown.push(Op.Jump { to: 2 });           // 10 is past this: Halt below
    countdown.push(Op.Halt);
    // A wrong target above: index 10 is the Jump, not the Halt. Patch it,
    // as an assembler's second pass would.
    countdown[3] = Op.JumpIfZero { to: 11 };
    print("countdown:");
    disassemble(countdown);
    let steps = run(countdown);
    print("ran ", steps, " instructions");

    // factorial: acc = 1; n = 10; while n != 0 { acc = acc * n; n = n - 1 }; print acc
    var fact: Op[>..] = [];
    fact.push(Op.Push { v: 1 });
    fact.push(Op.Store { slot: 1 });             // acc
    fact.push(Op.Push { v: 10 });
    fact.push(Op.Store { slot: 0 });             // n
    fact.push(Op.Load { slot: 0 });              // 4: loop head
    fact.push(Op.JumpIfZero { to: 15 });
    fact.push(Op.Load { slot: 1 });
    fact.push(Op.Load { slot: 0 });
    fact.push(Op.Mul);
    fact.push(Op.Store { slot: 1 });
    fact.push(Op.Load { slot: 0 });
    fact.push(Op.Push { v: 1 });
    fact.push(Op.Sub);
    fact.push(Op.Store { slot: 0 });
    fact.push(Op.Jump { to: 4 });
    fact.push(Op.Load { slot: 1 });              // 15
    fact.push(Op.Print);
    fact.push(Op.Halt);
    print("factorial:");
    disassemble(fact);
    let steps2 = run(fact);
    print("ran ", steps2, " instructions");
    print("an instruction is ", 1 + 8, " bytes: a tag and the largest operand");
}

// Conway's Game of Life on a torus. Two byte grids, one for the current
// generation and one for the next, and a step function that reads one and
// writes the other; the grids swap roles by swapping which one is passed
// where, so no cell is ever copied. Wrapping at the edges is `%`, which in
// Goose is Euclidean: (x - 1) % W is W - 1 when x is 0, with no special
// case. Prints a few generations of a glider and a blinker, then runs a
// larger random grid for a while and counts what is left.
//
// Build and run (from this directory):
//   goose -o life.c 20_life.goose && cl life.c && life

import std;

fn neighbours(g: u8[:], w: i64, h: i64, x: i64, y: i64) -> i64 {
    var n = 0;
    for dy in -1..2 {
        for dx in -1..2 {
            if dx == 0 && dy == 0 { continue; }
            let nx = (x + dx) % w;
            let ny = (y + dy) % h;
            n += g[ny * w + nx];
        }
    }
    return n;
}

// One generation: `src` is read, `dst` written, both w*h cells.
fn step(src: u8[:], dst: u8[:], w: i64, h: i64) {
    for y in h {
        for x in w {
            let n = neighbours(src, w, h, x, y);
            let alive = src[y * w + x] == 1;
            dst[y * w + x] = if n == 3 || (alive && n == 2) { 1 } else { 0 };
        }
    }
}

fn show(g: u8[:], w: i64, h: i64) {
    var line: u8[>..] = [];
    for y in h {
        line.clear();
        for x in w { line.push(if g[y * w + x] == 1 { '#' } else { '.' }); }
        print(line);
    }
    print("");
}

fn population(g: u8[:]) -> i64 {
    var n = 0;
    for c in g { n += c; }
    return n;
}

fn main() {
    // A glider and a blinker on a small grid.
    let w = 12;
    let h = 8;
    var a: u8[>..] = [];
    var b: u8[>..] = [];
    a.resize(w * h, 0);
    b.resize(w * h, 0);
    for p in [[1, 0], [2, 1], [0, 2], [1, 2], [2, 2]] { a[p[1] * w + p[0]] = 1; }   // glider
    for x in 8..11 { a[5 * w + x] = 1; }                                        // blinker
    for round in 3 {
        print("generation ", round * 2, ", population ", population(a));
        show(a, w, h);
        step(a, b, w, h);                // a -> b
        print("generation ", round * 2 + 1, ", population ", population(b));
        show(b, w, h);
        step(b, a, w, h);                // b -> a: the roles swap, nothing is copied
    }

    // A random 64x32 soup, 200 generations.
    let W = 64;
    let H = 32;
    var r = rng { 2024 };
    var cur:  u8[>..] = [];
    var next: u8[>..] = [];
    for i in W * H { cur.push(if r.rand_int(4) == 0 { 1 } else { 0 }); }
    next.resize(W * H, 0);
    print("soup: ", population(cur), " cells alive at start");
    for gen in 100 {
        step(cur, next, W, H);
        step(next, cur, W, H);
    }
    print("soup: ", population(cur), " cells alive after 200 generations");
    show(cur, W, H);
}

// A small ray tracer: a few spheres on a checkered floor, one light, hard
// shadows and mirror reflections, written with the library's vec3 math.
// `float3` is an ordinary struct of three f32s; `a + b`, `a - b`, `a * b`
// are the language's elementwise operators on any same-typed struct, and
// dot/normalize/length are library functions. The image is written as a
// binary PPM (open it in any image viewer), and a coarse ASCII version is
// printed so the run shows something without one.
//
// Build and run (from this directory):
//   goose -o raytrace.c 21_raytrace.goose && cl raytrace.c && raytrace

import std;
import vec;
import math;
import os;

struct Sphere { center: float3, radius: f32, color: float3, shine: f32 }
struct Hit { t: f32, point: float3, normal: float3, color: float3, shine: f32 }

let W = 320;
let H = 200;
let LIGHT = float3 { 5.0, 8.0, -3.0 };
let SKY = float3 { 0.55, 0.7, 0.95 };

var spheres: Sphere[>..] = [];

// float3 is three f32s in a plain struct, passed and returned by value; the
// elementwise operators used below are the language's, not overloads.
fn scale(v: float3, k: f32) -> float3 { float3 { v.x * k, v.y * k, v.z * k } }

// The nearest intersection along the ray, and whether there was one.
fn trace(origin: float3, dir: float3) -> Hit, bool {
    var best = Hit { t: 1.0e30, point: float3_0, normal: float3_0, color: float3_0, shine: 0.0 };
    var found = false;
    for s in spheres {
        // |origin + t*dir - center|^2 = r^2, a quadratic in t.
        let oc = origin - s.center;
        let b = dot(oc, dir);
        let c = dot(oc, oc) - s.radius * s.radius;
        let disc = b * b - c;
        if disc < 0.0 { continue; }
        let t = 0.0 - b - sqrt(disc);
        if t > 0.001 && t < best.t {
            let p = origin + scale(dir, t);
            best = Hit { t: t, point: p, normal: normalize(p - s.center), color: s.color, shine: s.shine };
            found = true;
        }
    }
    // The floor: the plane y = -1, checkered in world space.
    if dir.y < 0.0 {
        let t = (0.0 - 1.0 - origin.y) / dir.y;
        if t > 0.001 && t < best.t {
            let p = origin + scale(dir, t);
            let check = ((floor(p.x) as i64 + floor(p.z) as i64) % 2) == 0;
            let color = if check { float3 { 0.9, 0.9, 0.9 } } else { float3 { 0.2, 0.25, 0.3 } };
            best = Hit { t: t, point: p, normal: float3 { 0.0, 1.0, 0.0 }, color: color, shine: 0.15 };
            found = true;
        }
    }
    return best, found;
}

fn shadowed(p: float3) -> bool {
    let h, hit = trace(p, normalize(LIGHT - p));
    return hit;
}

// Diffuse light plus a reflection, up to `depth` bounces.
recursive fn shade(origin: float3, dir: float3, depth: i64) -> float3 {
    let h, hit = trace(origin, dir);
    guard hit else { return SKY; }
    let to_light = normalize(LIGHT - h.point);
    var diffuse = max(dot(h.normal, to_light), 0.0);
    if shadowed(h.point) { diffuse = diffuse * 0.2; }
    var color = scale(h.color, 0.15 + 0.85 * diffuse);
    if h.shine > 0.0 && depth > 0 {
        let reflected = dir - scale(h.normal, 2.0 * dot(dir, h.normal));
        let bounce = shade(h.point, reflected, depth - 1);
        color = color + scale(bounce - color, h.shine);
    }
    return color;
}

fn to_byte(x: f32) -> u8 { (clamp(x, 0.0, 1.0) * 255.0) as u8 }

fn main() {
    spheres.push(Sphere { center: float3 { 0.0, 0.0, 4.0 }, radius: 1.0, color: float3 { 0.9, 0.2, 0.2 }, shine: 0.4 });
    spheres.push(Sphere { center: float3 { -2.2, -0.3, 5.0 }, radius: 0.7, color: float3 { 0.2, 0.8, 0.3 }, shine: 0.1 });
    spheres.push(Sphere { center: float3 { 2.0, 0.2, 6.0 }, radius: 1.2, color: float3 { 0.9, 0.85, 0.3 }, shine: 0.7 });
    spheres.push(Sphere { center: float3 { 0.6, -0.7, 2.6 }, radius: 0.3, color: float3 { 0.3, 0.4, 0.95 }, shine: 0.0 });

    // The image: one byte per channel, row by row, built straight into the
    // buffer that becomes the file -- the header is formatted into the same
    // bytes, so writing the file is one call with no assembly step.
    var img: u8[>..] = [];
    format(img, "P6 ", W, " ", H, " 255\n");
    let t0 = clock();
    let eye = float3 { 0.0, 0.5, 0.0 };
    for y in H {
        for x in W {
            // A pixel's direction: the view plane at z = 1.
            let px = (x as f32 + 0.5) / W * 2.0 - 1.0;
            let py = 1.0 - (y as f32 + 0.5) / H * 2.0;
            let dir = normalize(float3 { px * 1.6, py, 1.0 });
            let c = shade(eye, dir, 3);
            img.push(to_byte(c.x));
            img.push(to_byte(c.y));
            img.push(to_byte(c.z));
        }
    }
    let ms = (clock() - t0) * 1000.0;
    let ok = write_file("raytrace.ppm", img);
    print("wrote raytrace.ppm: ", ok, " (", img.len, " bytes)");
    var note: u8[>..] = [];
    format(note, "traced ", W * H, " pixels in ");
    format_flt(note, ms, 1);
    format(note, " ms\n");
    write_stderr(note);

    // The same scene, 80x25, as brightness characters.
    let header = img.len - W * H * 3;
    let ramp = " .:-=+*#%@";
    var line: u8[>..] = [];
    for cy in 25 {
        line.clear();
        for cx in 80 {
            let x = cx * W / 80;
            let y = cy * H / 25;
            let i = header + (y * W + x) * 3;
            let lum = (img[i] as i64 * 3 + img[i + 1] as i64 * 6 + img[i + 2]) / 10;
            line.push(ramp[lum * ramp.len / 256]);
        }
        print(line);
    }
}

// Image kernels over row slices. A grayscale image is generated, blurred,
// and run through a Sobel edge detector, and the result is written as a
// PGM file. The kernels take the three source rows and the destination row
// as slices whose lengths are asserted once per row, so inside the pixel
// loop every index is a loop counter plus a constant against a known
// length: the compiler proves the pixel loops' bounds checks away and the
// C backend sees the same loop it would see from C.
//
// Build and run (from this directory):
//   goose -o image_filters.c 22_image_filters.goose && cl image_filters.c && image_filters

import std;
import math;
import os;

let W = 512;
let H = 384;

// A test picture: a gradient with rings, a bright disc and some noise.
fn generate(img: u8[>..]&) {
    var r = rng { 99 };
    for y in H {
        for x in W {
            let dx = (x - W / 2) as f64;
            let dy = (y - H / 2) as f64;
            let d = sqrt(dx * dx + dy * dy);
            var v = 96.0 + 64.0 * sin(d / 12.0) + (x as f64) / W * 60.0;
            if d < 60.0 { v = 230.0; }
            if (x / 64 + y / 64) % 2 == 0 && y > H * 3 / 4 { v = 40.0; }
            v += r.rand_int(21) - 10;
            img.push(clamp(v, 0.0, 255.0) as u8);
        }
    }
}

// A 3x3 box blur of the interior; the border is copied. The rows are
// sliced once per output row, and the inner loop indexes those.
fn blur(src: u8[:], dst: u8[:]) {
    assert(src.len == W * H && dst.len == W * H);
    copy_into(dst[..W], src[..W]);
    copy_into(dst[(H - 1) * W..], src[(H - 1) * W..]);
    for y in 1..H - 1 {
        let a = src[(y - 1) * W..y * W];
        let b = src[y * W..(y + 1) * W];
        let c = src[(y + 1) * W..(y + 2) * W];
        let d = dst[y * W..(y + 1) * W];
        assert(a.len == W && b.len == W && c.len == W && d.len == W);
        d[0] = b[0];
        d[W - 1] = b[W - 1];
        for x in 1..W - 1 {
            let s = a[x - 1] as u16 + a[x] + a[x + 1]
                  + b[x - 1] + b[x] + b[x + 1]
                  + c[x - 1] + c[x] + c[x + 1];
            d[x] = (s / 9) as! u8;
        }
    }
}

// Sobel edge magnitude, same shape: two 3x3 kernels, one per axis.
fn sobel(src: u8[:], dst: u8[:]) {
    assert(src.len == W * H && dst.len == W * H);
    fill(dst[..W], 0);
    fill(dst[(H - 1) * W..], 0);
    for y in 1..H - 1 {
        let a = src[(y - 1) * W..y * W];
        let b = src[y * W..(y + 1) * W];
        let c = src[(y + 1) * W..(y + 2) * W];
        let d = dst[y * W..(y + 1) * W];
        assert(a.len == W && b.len == W && c.len == W && d.len == W);
        d[0] = 0;
        d[W - 1] = 0;
        for x in 1..W - 1 {
            let gx = (a[x + 1] as i32 - a[x - 1]) + 2 * (b[x + 1] as i32 - b[x - 1])
                   + (c[x + 1] as i32 - c[x - 1]);
            let gy = (c[x - 1] as i32 - a[x - 1]) + 2 * (c[x] as i32 - a[x])
                   + (c[x + 1] as i32 - a[x + 1]);
            let g = abs(gx) + abs(gy);
            d[x] = if g > 255 { 255 } else { g as! u8 };
        }
    }
}

fn histogram(img: u8[:]) -> i64[8] {
    var h: i64[8] = [0; 8];
    for v in img { h[v / 32] += 1; }
    return h;
}

fn write_pgm(path: u8[:], img: u8[:]) {
    var out: u8[>..] = [];
    format(out, "P5 ", W, " ", H, " 255\n");
    out.append(img);
    print(path, ": ", write_file(path, out), " (", out.len, " bytes)");
}

fn main() {
    var img: u8[>..] = [];
    generate(img);
    var tmp: u8[>..] = [];
    tmp.resize(W * H, 0);
    var edges: u8[>..] = [];
    edges.resize(W * H, 0);

    let t0 = clock();
    for i in 4 {                         // four blur passes, ping-ponging the buffers
        blur(img, tmp);
        blur(tmp, img);
    }
    let t1 = clock();
    sobel(img, edges);
    let t2 = clock();

    var note: u8[>..] = [];
    format(note, "8 blur passes: ");
    format_flt(note, (t1 - t0) * 1000.0, 2);
    format(note, " ms, sobel: ");
    format_flt(note, (t2 - t1) * 1000.0, 2);
    format(note, " ms\n");
    write_stderr(note);

    print("histogram of the blurred image: ", histogram(img));
    print("histogram of the edges: ", histogram(edges));
    var strong = 0;
    for v in edges { if v > 128 { strong++; } }
    print(strong, " strong edge pixels of ", W * H);
    write_pgm("blurred.pgm", img);
    write_pgm("edges.pgm", edges);
}

// The Mandelbrot set, rendered by a pool of worker threads. Goose threads
// share no memory: a worker is a separate program that receives flat
// values through typed queues and sends flat values back. Here the main
// program queues one job per row, spawns as many workers as the machine
// has hardware threads, and collects the finished rows -- a row is a
// struct holding its index and its pixels as an inline byte array -- in
// whatever order they arrive, then prints them in order. The single-thread
// timing is measured too, for the comparison.
//
// Build and run (from this directory):
//   goose -o mandelbrot_threads.c 23_mandelbrot_threads.goose && cl mandelbrot_threads.c && mandelbrot_threads

import std;
import os;

let W = 78;
let H = 36;
let MAXITER = 20000;

struct Job { y: i32 }                    // -1: no more work, exit
struct Row { y: i32, cells: u8[] }        // a flat value: it crosses the queue as one copy

// Iterations until |z| > 2, or MAXITER.
fn iterate(cx: f64, cy: f64) -> i64 {
    var x = 0.0;
    var y = 0.0;
    var i = 0;
    while i < MAXITER && x * x + y * y <= 4.0 {
        let nx = x * x - y * y + cx;
        y = 2.0 * x * y + cy;
        x = nx;
        i++;
    }
    return i;
}

fn render_row(y: i64) -> u8[>..] {
    let ramp = " .:-=+*#%@";
    var cells: u8[>..] = [];
    for x in W {
        let cx = -2.2 + 3.0 * x as f64 / W;
        let cy = -1.2 + 2.4 * y as f64 / H;
        let n = iterate(cx, cy);
        cells.push(if n == MAXITER { '@' } else { ramp[(n * 3) % (ramp.len - 1)] });
    }
    return cells;
}

// A worker: take a job, render it, send the row back; stop on y == -1.
thread_fn worker() {
    loop {
        let job = qget<Job>();
        guard job.y >= 0 else { break; }
        qput(Row { y: job.y, cells: render_row(job.y) });   // one flat value, copied once into the queue
    }
}

fn main() {
    // Single-threaded first.
    let t0 = clock();
    var serial: u8[>..] = [];
    for y in H { serial.append(render_row(y)); }   // rows back to back, W bytes each
    let t1 = clock();

    // Then the pool. Jobs are queued before the workers start, one quit
    // job per worker after them, so every worker exits when the rows run out.
    let n = max(1, hardware_threads());
    for y in H { qput(Job { y: y as i32 }); }
    for i in n { qput(Job { y: -1 }); }
    var ids: i64[>..] = [];
    for i in n { ids.push(thread_spawn(worker)); }
    // Finished rows land in one byte buffer as they arrive; `order` maps a
    // row index to where its bytes went.
    var rows:  u8[>..]  = [];
    var order: i64[>..] = [];
    order.resize(H, -1);
    for done in H {
        let row = qget<Row>();
        order[row.y] = rows.len;
        rows.append(row.cells);
    }
    for id in ids { thread_wait(id); }
    let t2 = clock();

    // Rows arrived in whatever order the workers finished; print them in order.
    var same = true;
    for y in H {
        let k = order[y];
        let line = rows[k..k + W];
        print(line);
        if line != serial[y * W..(y + 1) * W] { same = false; }
    }
    print("rows match the serial render: ", same);
    var note: u8[>..] = [];
    format(note, "serial ");
    format_flt(note, (t1 - t0) * 1000.0, 1);
    format(note, " ms, ", n, " threads ");
    format_flt(note, (t2 - t1) * 1000.0, 1);
    format(note, " ms\n");
    write_stderr(note);
}

// Calling C. An `extern fn` binds a Goose signature to a C symbol: libm's
// functions arrive this way (the `math` module is nothing but such
// declarations), and so does any C the program brings along. What crosses
// the boundary is exactly what has a plain C shape: scalars, flat
// fixed-size structs (by value, or through a reference as a pointer),
// slices of those (as a data-pointer-and-length struct), and a `u8[>..]&`
// string builder, which C appends to. The C for this sample is call_c.h.
//
// Build and run (from this directory):
//   goose --include call_c.h -o call_c.c 24_call_c.goose
//   cc call_c.c -o call_c -lm -pthread && ./call_c   (or: cl call_c.c && call_c)

import std;

struct Stats { lo: i32, hi: i32, mean: f64 }

// libm directly, without the math module: the string is the C symbol.
extern fn cube_root(x: f64) -> f64 = "cbrt";
extern fn hypot(x: f64, y: f64) -> f64;
// `abs` rather than `labs`: C's `long` is 32 bits on Windows and 64 on Linux
// and macOS, so it has no one Goose type, where `int` is i32 everywhere.
extern fn c_abs(x: i32) -> i32 = "abs";

// From call_c.h: a slice in, a scalar out.
extern fn crc32_bytes(s: const u8[:]) -> u32;
// A slice in, a struct filled through a reference.
extern fn stats_of(xs: i32[:], out: Stats&);
// A builder the C side appends to.
extern fn c_version(out: u8[>..]&);

fn main() {
    // libm may return a neighboring representable value for cbrt(27), so
    // give the display a precision instead of depending on its last bit.
    var cube: u8[>..] = [];
    format_flt(cube, cube_root(27.0), 3);
    print(cube, " ", hypot(3.0, 4.0), " ", c_abs(-42));

    // Any u8 array or slice is a u8[:] at the call: a literal, a builder,
    // a sub-range.
    print(crc32_bytes("The quick brown fox jumps over the lazy dog"));
    var text: u8[>..] = [];
    for i in 1000 { format(text, i, ","); }
    print(text.len, " bytes, crc ", crc32_bytes(text), " / ", crc32_bytes(text[..100]));

    var xs: i32[>..] = [];
    var r = rng { 5 };
    for i in 100 { xs.push(r.rand_int(1000) as i32 - 500); }
    var st = Stats { lo: 0, hi: 0, mean: 0.0 };
    stats_of(xs, st);
    print(st);
    stats_of(xs[..10], st);
    print(st.lo, " ", st.hi, " ", st.mean);

    var v: u8[>..] = [];
    v.append("built against ");
    c_version(v);
    print(v);
}

// Data that is already its own file format. A structure whose links are
// self-relative offsets rather than addresses means the same wherever it
// sits, so saving it is a write of its bytes and loading it is a read --
// no serializer, no parser, no pointer fixups, no allocation per node.
//
// The catch is that a file is not trustworthy the way a value the compiler
// built is. `from_bytes` therefore *verifies* before the bytes become a
// value: it walks the image, checks that it frames exactly, and checks
// every link lands on the start of an element of that same image. It
// returns the array and a bool, and a rejected image gives an empty array
// -- so a corrupt or hostile file is a `false`, never a wild reference.
//
// Here that is a word index over a book: build it, save it, load it back,
// and answer the same queries against the loaded copy. Then a compact
// variable-size form of the same data, and then a tampered file.
//
// Build and run (from this directory):
//   goose -o serialize.c 25_serialize.goose && cl serialize.c && serialize

import std;
import dictionary;
import os;

// --- the index ---------------------------------------------------------------
// A binary search tree in one grow-only array, exactly as 14_bst builds one,
// except the key is inline: a limited array, so the node stays fixed-size and
// the pool stays indexable. Nothing in a node is an address -- `left` and
// `right` are 4-byte offsets from their own field to the child.

struct Node { word: u8[..24], count: i32, left: Node&<u32>?, right: Node&<u32>? }

fn insert(pool: Node[>..]&, word: u8[:], count: i32) {
    if pool.len == 0 { pool.push(Node { word: word, count: count }); return; }
    var cur .= pool[0];
    loop {
        let c = compare(word, cur.word[..]);
        if c == 0 { cur.count += count; return; }
        if c < 0 {
            let l = cur.left;
            if l { cur .= l; continue; }
            cur.left .= pool.push(Node { word: word, count: count });
            return;
        }
        let r = cur.right;
        if r { cur .= r; continue; }
        cur.right .= pool.push(Node { word: word, count: count });
        return;
    }
}

fn lookup(pool: Node[>..]&, word: u8[:]) -> i32 {
    guard pool.len > 0 else { return 0; }
    var cur .= pool[0];
    loop {
        let c = compare(word, cur.word[..]);
        if c == 0 { return cur.count; }
        let next = if c < 0 { cur.left } else { cur.right };
        guard next else { return 0; }
        cur .= next;
    }
}

// The deepest path, which is what says the loaded tree really is the tree
// and not merely the same bytes.
recursive fn depth(n: Node&) -> i64 {
    let l = n.left;
    let r = n.right;
    var d = 0;
    if l { d = depth(l); }
    if r { d = max(d, depth(r)); }
    return d + 1;
}

// --- the compact form --------------------------------------------------------
// The same tree with variable-size elements: the word inline behind a varint
// length, the links varint offsets. A node costs what its word costs plus a
// byte or two per link, and the pool is walked rather than indexed. The
// verifier handles both -- for fixed elements a link is valid when it is a
// multiple of the element size, and for variable ones the framing pass
// records where each element began and the link pass asks whether an offset
// is one of those.

enum Tiny {
    Leaf { word: u8[varint], count: varint },
    Fork { word: u8[varint], count: varint,
           left: Tiny..&<varint>?, right: Tiny..&<varint>? },
}

// Rebuilt bottom-up from the big tree: children are pushed before their
// parent, so a parent's links are short backward offsets.
recursive fn compact(n: Node&, out: Tiny..[>..]&) -> Tiny..& {
    let l = n.left;
    let r = n.right;
    guard l || r else {
        return out.push(Tiny.Leaf { word: n.word[..], count: n.count });
    }
    // Both subtrees land in `out` first; `push` hands back a reference to
    // each, and both are rooted at `out`, which is what lets the parent
    // store them as offsets (§3.9).
    if l {
        let lc: Tiny..& = compact(l, out);
        if r {
            let rc: Tiny..& = compact(r, out);
            return out.push(Tiny.Fork { word: n.word[..], count: n.count,
                                        left: lc, right: rc });
        }
        return out.push(Tiny.Fork { word: n.word[..], count: n.count, left: lc });
    }
    guard r else { return out.push(Tiny.Leaf { word: n.word[..], count: n.count }); }
    let rc: Tiny..& = compact(r, out);
    return out.push(Tiny.Fork { word: n.word[..], count: n.count, right: rc });
}

fn total(pool: Tiny..[>..]&) -> i64 {
    var sum = 0;
    for t in pool {
        match t {
            Leaf &l => { sum += l.count; },
            Fork &f => { sum += f.count; },
        }
    }
    return sum;
}

// --- main --------------------------------------------------------------------

fn is_letter(c: u8) -> bool { (c >= 'a' && c <= 'z') || c == '\'' }

fn main() {
    var path: u8[>..] = [];
    if arg_count() > 1 { arg(1, path); } else { path.append("data/alice.txt"); }
    var text: u8[>..] = [];
    guard read_file(path, text) else { print("cannot read ", path); exit(1); }
    to_lower(text);

    // Count the words, then index them. Keys are slices into `text`, so
    // nothing is copied until a word reaches a node.
    var counts = dictionary<u8[:], i32> {};
    var i = 0;
    while i < text.len {
        while i < text.len && !is_letter(text[i]) { i++; }
        let start = i;
        while i < text.len && is_letter(text[i]) { i++; }
        guard i > start && i - start <= 24 else { continue; }
        counts.update(text[start..i], 0) { it += 1; };
    }

    var index: Node[>..] = [];
    counts.each() { k, v => insert(index, k, v); };
    print("indexed ", index.len, " words from ", path);

    // Saving is a write of the element region. There is no serializer to
    // write and no schema to keep in step: the bytes the program has been
    // using all along are the file. `bytes_of` is a *view* of them -- no
    // copy at all -- and the framing prefix `from_bytes` wants is a ULEB
    // byte count, so the save is a tiny header and then the payload.
    let payload = index.bytes_of();
    var head: u8[>..] = [];
    format_uleb(head, payload.len);
    guard write_file("index.gsx", head) && append_file("index.gsx", payload)
    else { print("cannot write"); exit(1); }
    print("image ", head.len + payload.len, " bytes = ", index.len, " nodes x ",
          payload.len / index.len, " + ", head.len);

    // The same image built as one value instead, for the checks below.
    var image: u8[>..] = index.to_bytes();

    // Loading is a read, a verify and a copy. What comes back is an ordinary
    // array rooted at `loaded`: it indexes, it grows, references into it are
    // ordinary references, and §9 needs no new rule for it.
    var file: u8[>..] = [];
    guard read_file("index.gsx", file) else { print("cannot re-read"); exit(1); }
    let n, k = parse_uleb(file[0..]);
    print("prefix says ", n, " bytes after ", k, ", file has ", file.len - k);
    let t0 = clock();
    var loaded, ok = from_bytes<Node[>..]>(file);
    let t1 = clock();
    print("loaded ", ok, ", ", loaded.len, " nodes, same size ",
          loaded.len == index.len);

    // The same queries against the loaded copy.
    var same = true;
    each_split("alice rabbit down think curiosity nonexistentword", ' ') {
        let a = lookup(index, it);
        let b = lookup(loaded, it);
        if a != b { same = false; }
        print("  ", it, " = ", b);
    };
    print("answers match ", same, ", depth ", depth(loaded[0]),
          " = ", depth(index[0]));

    // The compact form: variable-size elements, varint links.
    var tiny: Tiny..[>..] = [];
    compact(index[0], tiny);
    var timage: u8[>..] = tiny.to_bytes();
    var tback, tok = from_bytes<Tiny..[>..]>(timage);
    print("compact ", timage.len, " bytes for ", tiny.len, " nodes, reload ",
          tok, " totals ", total(tback) == total(tiny));

    // What a verifier is for. Flipping a byte of a link makes an offset that
    // points somewhere the array does not reach; in a language that trusted
    // the file, following it would be a wild read. Here it is a `false`.
    var tampered: u8[>..] = [];
    tampered.append(image);
    let pfx = image.len - payload.len;          // the framing prefix
    tampered[pfx + 29] = tampered[pfx + 29] ^ 0x40;   // inside the first link
    var bad, bok = from_bytes<Node[>..]>(tampered);
    print("tampered link ", bok, ", nodes ", bad.len);

    // Verification is about safety, not integrity: a byte inside a *count*
    // still describes a valid tree, so the image is accepted with the wrong
    // number in it. A checksum is the answer to that, and it is not what
    // `from_bytes` promises.
    var edited: u8[>..] = [];
    edited.append(image);
    edited[pfx + 25] = edited[pfx + 25] ^ 0x01;      // inside the first count
    var ed, eok = from_bytes<Node[>..]>(edited);
    print("edited count ", eok, ", still a tree ", ed.len == index.len);

    // Truncation, extension, and an empty file.
    var cut: u8[>..] = [];
    cut.append(image);
    cut.pop();
    var c1, cok = from_bytes<Node[>..]>(cut);
    var grown: u8[>..] = [];
    grown.append(image);
    grown.push(0);
    var g1, gok = from_bytes<Node[>..]>(grown);
    var empty: Node[>..] = [];
    var e1, eok2 = from_bytes<Node[>..]>(empty.to_bytes());
    var z1, zok = from_bytes<Node[>..]>("");
    print("truncated ", cok, ", extended ", gok, ", empty ", eok2, " ", e1.len,
          ", no prefix ", zok);

    // The image is an ordinary resizable result, so it also goes straight
    // into a message with a header of its own -- one copy, not two.
    var msg: u8[>..] = [];
    msg.append("GSX1");
    index.to_bytes(msg);
    var wire, wok = from_bytes<Node[>..]>(msg[4..]);
    print("message ", msg.len, " bytes, tag ", msg[0..4], ", reload ", wok, " ",
          wire.len == index.len);

    delete_file("index.gsx");
    format_stderr("verify+copy of ", image.len, " bytes: ", (t1 - t0) * 1000.0,
                  " ms\n");
}

fn format_stderr(a: u8[:], b: i64, c: u8[:], d: f64, e: u8[:]) {
    var line: u8[>..] = [];
    format(line, a, b, c, d, e);
    write_stderr(line);
}

// A directory tree: an N-ary tree whose child lists grow and shrink. Every
// node lives in a `slot_pool<Node>`, and the program holds ordinary
// references to them, while the tree itself links them with 4-byte offsets
// from the pool's base. A directory's entries are one contiguous run of those
// links in a `slice_pool<Link>`, so an entry list is a plain slice to
// walk. Adding an entry grows that run in place when there is room after it,
// and otherwise moves it where a new run of that size would go. Removing a
// subtree gives its slots and runs back, and the next additions take them
// again: no allocator is involved anywhere.
//
// Build and run (from this directory):
//   goose -o file_tree.c 26_file_tree.goose && cl file_tree.c && file_tree

import slice_pool;
import slot_pool;

// A link to a node: an offset into `nodes.items` (§3.9). The cells a run gains start
// out as the default value, null, so the link is optional, but every link
// inside a directory's run is set before anything reads it.
type Link = Node&<u32 in nodes.items>?;

struct Node {
    name:    u8[..15],  // inline, so a Node is fixed-size, as pool elements must be
    entries: Link[:],   // the run of links to what this directory holds
}

var nodes = slot_pool<Node> {};
var runs = slice_pool<Link> {};

// A node with no entries: an empty run, placed by the first addition.
fn make(name: u8[:]) -> Node& {
    return nodes.alloc_ref(Node { name: name, entries: runs.alloc_slice(0) });
}

let root .= make("/");

// Appends a link to `n` to the entries of directory `dir`. realloc_slice
// returns where the run is now, which the directory keeps. A run reached
// through a reference is not one the checker can place in `runs`, so the
// operations that take one check that when they run.
fn link(dir: Node&, n: Node&) {
    let k = dir.entries.len;
    dir.entries = runs.realloc_slice(dir.entries, k + 1);
    dir.entries[k] .= n;
}

fn add(dir: Node&, name: u8[:]) -> Node& {
    let n .= make(name);
    link(dir, n);
    return n;
}

// Takes entry `i` out of directory `dir`: the entries after it shift down,
// and the run shrinks by one, which gives its last cell back to `runs`.
fn unlink(dir: Node&, i: i64) -> Node& {
    let n = dir.entries[i];
    assert(n);
    for j in i..dir.entries.len - 1 { dir.entries[j] .= dir.entries[j + 1]; }
    dir.entries = runs.realloc_slice(dir.entries, dir.entries.len - 1);
    return n;
}

// Where node `child` sits among the entries of `dir`. `.==` asks whether two
// references name the same node, where `==` would compare their contents.
fn position(dir: Node&, child: Node&) -> i64 {
    for i in dir.entries.len {
        let e = dir.entries[i];
        assert(e);
        if e .== child { return i; }
    }
    abort("not an entry");
}

// Gives a subtree back: its runs to `runs`, its slots to `nodes`, which
// index_of turns a node back into. A freed node keeps its bytes, so a stale
// link would still read a valid Node.
recursive fn release(n: Node&) {
    for e in n.entries {
        assert(e);
        release(e);
    }
    runs.free_slice(n.entries);
    nodes.free_ref(n);
}

// rm -r: unlinked from its directory, then given back.
fn remove(dir: Node&, child: Node&) {
    unlink(dir, position(dir, child));
    release(child);
}

// mv: the node keeps its slot, and only the two runs change.
fn move(dir: Node&, child: Node&, to: Node&) {
    link(to, unlink(dir, position(dir, child)));
}

// One line per node, indented by depth; returns how many nodes it listed.
recursive fn show(n: Node&, depth: i64, out: u8[>..]&) -> i64 {
    for i in depth { format(out, "  "); }
    format(out, n.name, "\n");
    var count = 1;
    for e in n.entries {
        assert(e);
        count += show(e, depth + 1, out);
    }
    return count;
}

// The tree, after a line comparing what is live with what the pools hold:
// every node but the root is one link in some run.
fn listing(what: u8[:]) {
    var out: u8[>..] = [];
    let live = show(root, 0, out);
    print("-- ", what, ": ", live, " nodes in ", nodes.items.len, " slots, ", live - 1, " links in ",
          runs.items.len, " cells");
    print(out[..^1]);
}

fn main() {
    let home .= add(root, "home/");
    let ann .= add(home, "ann/");
    add(ann, "notes.txt");
    let todo .= add(ann, "todo.txt");
    let bob .= add(home, "bob/");
    add(bob, "game.sav");
    let etc .= add(root, "etc/");
    add(etc, "hosts");
    listing("built");

    // Two nodes and their runs go back to the pools...
    remove(home, bob);
    listing("rm -r /home/bob");

    // ...and new nodes and links take them again: nothing grows.
    let carl .= add(home, "carl/");
    add(carl, "a.txt");
    listing("mkdir /home/carl, touch a.txt");

    // ann's run shrinks, giving a cell back. /etc's run has no room after
    // it and no free run holds its two entries, so it moves to the end of
    // the array and leaves its old cell free as well.
    move(ann, todo, etc);
    listing("mv /home/ann/todo.txt /etc");

    // Now /etc's run ends the array and grows in place, while the next
    // entries for ann and carl fill the two free cells.
    for i in 3 { add(etc, str("log", i)); }
    add(ann, "b.txt");
    add(carl, "c.txt");
    listing("more files");
}

// A window with a spinning, lit cube, drawn with the gfx module
// (docs/stdlib.md): SDL3's GPU API behind a small Goose interface.
//
// The shaders are GLSL, written in main as """ strings. embed_shader
// compiles each one when this program is compiled -- to SPIR-V for Vulkan,
// MSL for Metal and HLSL for Direct3D 12, all at once -- so the same program
// runs on whichever the machine has, with nothing to load at run time.
//
// The arrow keys turn the cube, and Escape or closing the window quits.
// `-- --frames N` stops after N frames. Either way the last frame is saved
// as gfx_cube.png.
//
//   goose 27_gfx_cube.goose
//
// Built from the generated C, the program links the gfx layer and SDL, whose
// paths `goose --gfx-link` prints as a response file:
//   goose -o gfx_cube.c 27_gfx_cube.goose
//   cl gfx_cube.c @<goose --gfx-link msvc>          (or clang-cl)
//   cc gfx_cube.c -o gfx_cube @<goose --gfx-link cc>

import std;
import vec;
import math;
import os;
import gfx;

// One corner of one face: where it is, which way the face points, and the
// face's color as four bytes, which the pipeline below has the shader read
// as a vec4 from 0 to 1.
struct Vertex { pos: float3, normal: float3, color: u8[4] }

// The vertex shader's uniform block: two column-major matrices. std140 lays
// those out with no padding, so the packed Goose struct matches it exactly.
struct Transform { model: gfx::mat4, view_proj: gfx::mat4 }

// Four corners and two triangles per face, counterclockwise seen from
// outside, which is what culling back faces keeps.
fn cube(verts: Vertex[>..]&, indices: u16[>..]&) {
    let axes: float3[3] = [float3 { 1.0, 0.0, 0.0 }, float3 { 0.0, 1.0, 0.0 },
                           float3 { 0.0, 0.0, 1.0 }];
    let colors: u8[4][6] = [[230, 80, 60, 255], [240, 170, 50, 255], [90, 200, 90, 255],
                            [70, 160, 230, 255], [160, 100, 220, 255], [230, 230, 230, 255]];
    for f in 6 {
        // A face's normal, and two directions along it whose cross product
        // is the normal.
        let sign: f32 = if f % 2 == 0 { 1.0 } else { -1.0 };
        let n = axes[f / 2] * float3 { sign, sign, sign };
        let u = axes[(f / 2 + 1) % 3] * float3 { sign, sign, sign };
        let v = cross(n, u);
        let base = verts.len as u16;
        let corners: float2[4] = [float2 { -1.0, -1.0 }, float2 { 1.0, -1.0 },
                                  float2 { 1.0, 1.0 }, float2 { -1.0, 1.0 }];
        for c in corners {
            let p = n + u * float3 { c.x, c.x, c.x } + v * float3 { c.y, c.y, c.y };
            verts.push(Vertex { pos: p * float3 { 0.5, 0.5, 0.5 }, normal: n, color: colors[f] });
        }
        indices.append([base, base + 1, base + 2, base, base + 2, base + 3]);
    }
}

fn main() {
    var frames = -1;
    let argv = args();
    if argv.len == 3 && argv[1] == "--frames" {
        let n, ok = parse_int(argv[2]);
        if ok { frames = n; }
    }
    guard gfx::open("Goose: a gfx cube", 640, 480, gfx::WINDOW_RESIZABLE) else {
        write_stderr(str("gfx: ", gfx::error(), "\n"));
        return;
    }
    defer gfx::close();   // On every way out of main from here on.

    var verts:   Vertex[>..] = [];
    var indices: u16[>..]    = [];
    cube(verts, indices);
    let vertex_buffer = gfx::vertex_buffer(bytes_of(verts));
    let index_buffer = gfx::index_buffer(bytes_of(indices));
    // The vertex shader: each corner moved by the model and view-projection
    // matrices of a uniform block, its normal turned with the model.
    let cube_vs = embed_shader("vert", """
        layout(location = 0) in vec3 a_pos;
        layout(location = 1) in vec3 a_normal;
        layout(location = 2) in vec4 a_color;
        layout(set = 1, binding = 0) uniform Transform {
            mat4 model;
            mat4 view_proj;
        };
        layout(location = 0) out vec3 v_normal;
        layout(location = 1) out vec4 v_color;
        void main() {
            v_normal = (model * vec4(a_normal, 0.0)).xyz;
            v_color = a_color;
            gl_Position = view_proj * model * vec4(a_pos, 1.0);
        }
        """);
    // The fragment shader: the face color, lit from one direction, with some
    // light everywhere.
    let cube_fs = embed_shader("frag", """
        layout(location = 0) in vec3 v_normal;
        layout(location = 1) in vec4 v_color;
        layout(location = 0) out vec4 result;
        void main() {
            float light = max(dot(normalize(v_normal), normalize(vec3(0.4, 0.8, 0.6))), 0.0);
            result = vec4(v_color.rgb * (0.25 + 0.75 * light), 1.0);
        }
        """);
    // The vertex shader's inputs are read from a vertex buffer in order,
    // laid out as Vertex is; only the color needs saying, since it is bytes
    // and not floats.
    var desc = gfx::PipelineDesc { cull: gfx::CULL_BACK, depth_test: true, depth_write: true };
    desc.formats[2] = gfx::VERTEX_UBYTE4_NORM;
    let cube_pipeline = gfx::pipeline(cube_vs, cube_fs, desc);

    var yaw:   f32 = 0.6;
    var pitch: f32 = 0.5;
    var drawn = 0;
    while gfx::frame() {
        if gfx::key_pressed("Escape") { break; }
        if gfx::key_down("Left") { yaw -= 0.04; }
        if gfx::key_down("Right") { yaw += 0.04; }
        if gfx::key_down("Up") { pitch -= 0.04; }
        if gfx::key_down("Down") { pitch += 0.04; }
        yaw += 0.01;

        // The screen follows the window's size, and the projection its shape.
        let size = gfx::screen_size();
        let aspect = size.x as f32 / size.y;
        let model = gfx::mul(gfx::rotate(float3 { 1.0, 0.0, 0.0 }, pitch),
                             gfx::rotate(float3 { 0.0, 1.0, 0.0 }, yaw));
        let view = gfx::look_at(float3 { 0.0, 0.4, 3.0 }, float3_0, float3 { 0.0, 1.0, 0.0 });
        let transform = Transform { model: model,
                                    view_proj: gfx::mul(gfx::perspective(0.8, aspect, 0.1, 20.0),
                                                        view) };

        gfx::begin_screen(float4 { 0.1, 0.12, 0.16, 1.0 });
        gfx::bind(cube_pipeline);
        gfx::bind_vertex_buffer(vertex_buffer);
        gfx::bind_index_buffer(index_buffer, 2);
        gfx::uniforms(gfx::VERTEX, 0, transform);
        gfx::draw_indexed(indices.len);
        gfx::end_pass();
        drawn++;
        if drawn == frames { break; }
    }

    // The last frame drawn: saved, and read back to see the cube in it.
    let saved = gfx::screenshot("gfx_cube.png");
    let px = gfx::read_pixels(gfx::screen());
    let size = gfx::screen_size();
    let mid = ((size.y as i64 / 2) * size.x + size.x as i64 / 2) * 4;
    let background: u8[3] = [26, 31, 41];
    var cube_there = false;
    for i in 3 { cube_there = cube_there || abs(px[mid + i] as i64 - background[i]) > 8; }
    print("drew ", drawn, " frames; cube in the middle: ", cube_there, "; saved gfx_cube.png: ",
          saved);
}

// Thousands of boxes raining into a walled arena: the physics module
// (Box3D, docs/stdlib.md) moves them, the gfx module draws them.
//
// Boxes of every size and color fall from high above the whole arena. They
// tumble onto two pyramids and each other, and a long arm turning in the
// middle sweeps the heap around. Once the arena holds as many boxes as asked
// for, the oldest are lifted back up, so the rain never stops. Box3D steps
// the world on as many worker threads as the machine has, up to eight.
//
// Each frame the bodies' transforms come back in one call and go straight
// into an instance buffer: one unit cube drawn once per box, moved, turned
// and colored in the vertex shader, and lit by a sun whose shadow map is
// drawn from the same buffer first. The shaders are GLSL, written below as
// """ strings that embed_shader compiles along with the program.
//
// Space sets off an explosion under the heap; drag with the left mouse
// button to look around and use the wheel to zoom; Up and Down pour faster
// and slower; Escape quits.
//
//   goose 28_physics_boxes.goose
//   goose 28_physics_boxes.goose -- --boxes 20000
//
// `--frames N` stops after N frames and saves the last as physics_boxes.png;
// `--rate N` drops N boxes a frame. Built from the generated C, the program
// links both native layers, whose paths goose prints as response files:
//   goose -o physics_boxes.c 28_physics_boxes.goose
//   cl physics_boxes.c @<goose --gfx-link msvc> @<goose --physics-link msvc>
//   cc physics_boxes.c -o physics_boxes @<goose --gfx-link cc> @<goose --physics-link cc>

import std;
import vec;
import math;
import os;
import gfx;
import physics;

// A corner of the unit cube, with its face's normal.
struct Vertex { pos: float3, normal: float3 }
// One box as the vertex shader reads it, per instance: where, how big, how
// turned, what color.
struct Instance { position: float3, half: float3, rotation: physics::Quat, color: u8[4] }
// The uniform blocks of the shaders: two column-major matrices, and the
// light, each already laid out as std140 wants.
struct Scene { view_proj: gfx::mat4, light_view_proj: gfx::mat4 }
struct Light { sun: float4, eye: float4, haze: float4 }
// What a falling box looks like, by its body.
struct Look { half: float3, color: u8[4] }

let ARENA: f32 = 18.0;          // half the floor's width, inside the walls
let SHADOW_SIZE = 2048;
// The rain falls from a grid of cells over the arena, which it visits in a
// scattered order that comes back to a cell only after all the others:
// by then that cell's last box has fallen well clear, so no box starts
// inside another.
let CELLS = 24;
let CELL: f32 = 1.3;
let DT:   f32 = 1.0 / 60.0;

fn f3(x: f32) -> float3 { float3 { x, x, x } }

// The unit cube: four corners and two triangles a face, counterclockwise
// seen from outside.
fn cube(verts: Vertex[>..]&, indices: u16[>..]&) {
    let axes: float3[3] = [float3 { 1.0, 0.0, 0.0 }, float3 { 0.0, 1.0, 0.0 },
                           float3 { 0.0, 0.0, 1.0 }];
    for f in 6 {
        let sign: f32 = if f % 2 == 0 { 1.0 } else { -1.0 };
        let n = axes[f / 2] * f3(sign);
        let u = axes[(f / 2 + 1) % 3] * f3(sign);
        let v = cross(n, u);
        let base = verts.len as u16;
        let corners: float2[4] = [float2 { -1.0, -1.0 }, float2 { 1.0, -1.0 },
                                  float2 { 1.0, 1.0 }, float2 { -1.0, 1.0 }];
        for c in corners { verts.push(Vertex { pos: n + u * f3(c.x) + v * f3(c.y), normal: n }); }
        indices.append([base, base + 1, base + 2, base, base + 2, base + 3]);
    }
}

// A bright color from around the color wheel, h from 0 to 1.
fn hue(h: f32) -> u8[4] {
    let r = clamp(abs(h * 6.0 - 3.0) - 1.0, 0.0, 1.0);
    let g = clamp(2.0 - abs(h * 6.0 - 2.0), 0.0, 1.0);
    let b = clamp(2.0 - abs(h * 6.0 - 4.0), 0.0, 1.0);
    [round(50.0 + 190.0 * r) as u8, round(50.0 + 190.0 * g) as u8, round(50.0 + 190.0 * b) as u8,
     255]
}

// A random number from lo to hi; the f64 rounds to the nearest f32.
fn flt(r: rng&, lo: f32, hi: f32) -> f32 { lo + (hi - lo) * r.rand_flt() as f32 }

// Where the n-th box starts: 263 shares no factor with the 576 cells, so
// stepping by it visits them all before any twice.
fn raindrop(n: i64, r: rng&) -> float3 {
    let c = n * 263 % (CELLS * CELLS);
    let middle = (CELLS - 1) as f32 * 0.5;
    float3 { (c % CELLS - middle) * CELL + flt(r, -0.15, 0.15), flt(r, 24.0, 25.0),
             (c / CELLS - middle) * CELL + flt(r, -0.15, 0.15) }
}

// --- shaders -----------------------------------------------------------------

// The first part of both vertex shaders: a corner of the cube from vertex
// buffer 0, an Instance from buffer 1, the Scene, and where that corner of
// that box is in the world. Both shaders read the same buffers, so both
// declare every input, which is what the pipeline lays the buffers out by.
let box_input = """
    layout(location = 0) in vec3 a_pos;
    layout(location = 1) in vec3 a_normal;
    layout(location = 2) in vec3 i_position;
    layout(location = 3) in vec3 i_half;
    layout(location = 4) in vec4 i_rotation;
    layout(location = 5) in vec4 i_color;
    layout(set = 1, binding = 0) uniform Scene {
        mat4 view_proj;
        mat4 light_view_proj;
    };

    // Rotates v by the unit quaternion q.
    vec3 rotate_q(vec4 q, vec3 v) {
        vec3 t = 2.0 * cross(q.xyz, v);
        return v + q.w * t + cross(q.xyz, t);
    }

    vec3 world_corner() {
        return i_position + rotate_q(i_rotation, a_pos * i_half);
    }
    """;

// A box seen from the camera, with what its light needs.
let boxes_vert = """
    layout(location = 0) out vec3 v_world;
    layout(location = 1) out vec3 v_normal;
    layout(location = 2) out vec4 v_color;
    layout(location = 3) out vec4 v_shadow;
    layout(location = 4) out vec3 v_local;
    void main() {
        vec3 world = world_corner();
        v_world = world;
        v_normal = rotate_q(i_rotation, a_normal);
        v_color = i_color;
        v_shadow = light_view_proj * vec4(world, 1.0);
        // Where on the face this corner is, from -1 to 1, for darkening edges.
        v_local = a_pos * 2.0;
        gl_Position = view_proj * vec4(world, 1.0);
    }
    """;

// The boxes' light: the sun, softened by a shadow map read through hardware
// depth comparison, sky light from above, darker edges so that boxes in a
// heap stay apart, and haze with distance.
let boxes_frag = """
    layout(location = 0) in vec3 v_world;
    layout(location = 1) in vec3 v_normal;
    layout(location = 2) in vec4 v_color;
    layout(location = 3) in vec4 v_shadow;
    layout(location = 4) in vec3 v_local;
    layout(location = 0) out vec4 result;
    layout(set = 2, binding = 0) uniform sampler2DShadow shadow_map;
    layout(set = 3, binding = 0) uniform Light {
        vec4 sun;       // xyz: toward the sun
        vec4 eye;
        vec4 haze;      // rgb: its color, w: density
    };

    float sunlit(vec4 s) {
        vec3 p = s.xyz / s.w;
        vec2 uv = vec2(p.x * 0.5 + 0.5, 0.5 - p.y * 0.5);
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return 1.0;
        float texel = 1.0 / 2048.0;
        float lit = 0.0;
        lit += texture(shadow_map, vec3(uv + vec2(-texel, -texel), p.z));
        lit += texture(shadow_map, vec3(uv + vec2(texel, -texel), p.z));
        lit += texture(shadow_map, vec3(uv + vec2(-texel, texel), p.z));
        lit += texture(shadow_map, vec3(uv + vec2(texel, texel), p.z));
        return lit * 0.25;
    }

    void main() {
        vec3 n = normalize(v_normal);
        float diffuse = max(dot(n, sun.xyz), 0.0) * sunlit(v_shadow);
        float sky = 0.35 + 0.25 * n.y;
        // The two coordinates across this face nearest 1 in size make an edge.
        vec3 a = abs(v_local);
        float across = max(max(min(a.x, a.y), min(a.y, a.z)), min(a.x, a.z));
        float edge = 1.0 - 0.35 * smoothstep(0.85, 1.0, across);
        vec3 light = vec3(1.0, 0.95, 0.85) * diffuse + vec3(0.55, 0.65, 0.8) * sky;
        vec3 color = v_color.rgb * light * edge;
        float dist = length(eye.xyz - v_world);
        result = vec4(mix(color, haze.rgb, 1.0 - exp(-dist * haze.w)), 1.0);
    }
    """;

// A box seen from the sun, for the shadow map: only its depth.
let shadow_vert = """
    void main() {
        gl_Position = light_view_proj * vec4(world_corner(), 1.0);
    }
    """;

fn main() {
    var frames = -1;
    var max_boxes = 10000;
    var rate = 25;
    let argv = args();
    var a = 1;
    while a + 1 < argv.len {
        let n, ok = parse_int(argv[a + 1]);
        if ok && argv[a] == "--frames" { frames = n; }
        if ok && argv[a] == "--boxes" { max_boxes = max(n, 1); }
        if ok && argv[a] == "--rate" { rate = max(n, 0); }
        a += 2;
    }
    guard gfx::open("Goose: boxes", 1280, 720, gfx::WINDOW_RESIZABLE) else {
        write_stderr(str("gfx: ", gfx::error(), "\n"));
        return;
    }
    defer gfx::close();

    // --- the world -----------------------------------------------------------
    let world = physics::create_world(physics::WorldDef {
        workers: min(hardware_threads(), 8) as i32,
        capacity: physics::Capacity { dynamic_bodies: max_boxes as i32 } });
    defer physics::destroy(world);   // Before the window closes: defers run latest first.
    // The floor and four walls, all shapes of one static body; the arena's
    // pieces are drawn as boxes too.
    var props: Instance[>..] = [];
    let arena = physics::create_body(world, physics::BodyDef {});
    let wall_color: u8[4] = [150, 155, 165, 255];
    let pieces: float3[10] = [
        float3 { 0.0, -0.5, 0.0 }, float3 { ARENA + 1.0, 0.5, ARENA + 1.0 },
        float3 { 0.0, 1.5, ARENA + 0.5 }, float3 { ARENA + 1.0, 1.5, 0.5 },
        float3 { 0.0, 1.5, -ARENA - 0.5 }, float3 { ARENA + 1.0, 1.5, 0.5 },
        float3 { ARENA + 0.5, 1.5, 0.0 }, float3 { 0.5, 1.5, ARENA + 1.0 },
        float3 { -ARENA - 0.5, 1.5, 0.0 }, float3 { 0.5, 1.5, ARENA + 1.0 }];
    for i in 5 {
        let at = pieces[i * 2];
        let half = pieces[i * 2 + 1];
        physics::create_box_shape(arena, physics::ShapeDef {}, half,
                                  physics::Transform { p: at, q: physics::quat_identity });
        props.push(Instance { position: at, half: half, rotation: physics::quat_identity,
                              color: if i == 0 { [96, 104, 112, 255] } else { wall_color } });
    }

    // The arm: kinematic, so it turns at its own speed whatever it hits.
    let arm_half = float3 { ARENA * 0.55, 0.6, 0.35 };
    let arm = physics::create_body(world, physics::BodyDef {
        body_type: physics::KINEMATIC, position: float3 { 0.0, 0.6, 0.0 },
        angular_velocity: float3 { 0.0, 0.5, 0.0 } });
    physics::create_box_shape(arm, physics::ShapeDef {}, arm_half);

    // Two pyramids for the pour to bury and the arm to knock down.
    var bodies: physics::Body[>..] = [];
    var looks:  Look[>..]          = [];
    for p in 2 {
        let center = if p == 0 { float3 { 8.0, 0.0, 5.0 } } else { float3 { -7.0, 0.0, -8.0 } };
        let rows = 8;
        for row in rows {
            for k in rows - row {
                let at = center + float3 { (k - (rows - row - 1) * 0.5) * 1.02,
                                           0.5 + row * 1.0, 0.0 };
                let b = physics::create_body(world, physics::BodyDef { body_type: physics::DYNAMIC,
                                                                       position: at });
                physics::create_box_shape(b, physics::ShapeDef {}, f3(0.5));
                bodies.push(b);
                let shade = (180 + row * 9) as u8;
                looks.push(Look { half: f3(0.5), color: if p == 0 { [shade, shade, 90, 255] }
                                                        else { [90, shade, shade, 255] } });
            }
        }
    }
    let pyramid_boxes = bodies.len;

    // --- drawing -------------------------------------------------------------
    var verts:   Vertex[>..] = [];
    var indices: u16[>..]    = [];
    cube(verts, indices);
    let cube_vb = gfx::vertex_buffer(bytes_of(verts));
    let cube_ib = gfx::index_buffer(bytes_of(indices));
    // Room for every instance there will ever be: filled from the start
    // each frame.
    let one:  Instance[1] = [default<Instance>()];
    let none: u8[>..]     = [];
    let instance_bytes = bytes_of(one).len;
    let inst_vb = gfx::buffer(gfx::BUFFER_VERTEX,
                              (props.len + 1 + pyramid_boxes + max_boxes) * instance_bytes, none);
    // Corners from buffer 0, the rest per instance from buffer 1; the color
    // comes as four bytes.
    var desc = gfx::PipelineDesc { cull: gfx::CULL_BACK, depth_test: true, depth_write: true,
                                   instance_location: 2 };
    desc.formats[5] = gfx::VERTEX_UBYTE4_NORM;
    let boxes_pipe = gfx::pipeline(embed_shader("vert", box_input, boxes_vert),
                                   embed_shader("frag", boxes_frag), desc);
    var shadow_desc = gfx::PipelineDesc { cull: gfx::CULL_FRONT, depth_test: true,
                                          depth_write: true, instance_location: 2,
                                          depth_bias: 1.0, depth_bias_slope: 1.5 };
    shadow_desc.formats[5] = gfx::VERTEX_UBYTE4_NORM;
    // A pass with only depth still needs a fragment shader: an empty one.
    let shadow_pipe = gfx::pipeline(embed_shader("vert", box_input, shadow_vert),
                                    embed_shader("frag", "void main() { }"), shadow_desc);
    let shadow_map = gfx::depth_target(SHADOW_SIZE, SHADOW_SIZE);
    let shadow_cmp = gfx::shadow_sampler();

    // The sun, and a view of the whole arena from it.
    let sun = normalize(float3 { 0.45, 1.0, 0.3 });
    let up = float3 { 0.0, 1.0, 0.0 };
    let light_view_proj = gfx::mul(gfx::ortho(-30.0, 30.0, -30.0, 30.0, 1.0, 100.0),
                                   gfx::look_at(sun * f3(50.0), float3_0, up));

    // --- the pour ------------------------------------------------------------
    var r = rng { 2026 };
    var instances:  Instance[>..]           = [];
    var transforms: physics::Transform[>..] = [];
    var dropped = 0;
    var oldest = 0;
    var yaw:      f32 = 0.6;
    var pitch:    f32 = 0.45;
    var distance: f32 = 48.0;
    var drawn = 0;
    var stats_time: f64 = 0.0;
    var stats_frames = 0;
    while gfx::frame() {
        if gfx::key_pressed("Escape") { break; }
        if gfx::key_pressed("Up") { rate = min(rate * 2, 400); }
        if gfx::key_pressed("Down") { rate = rate / 2; }
        if gfx::key_pressed("Space") {
            physics::explode(world, physics::ExplosionDef { position: float3 { 0.0, -1.0, 0.0 },
                                                            radius: 14.0, falloff: 6.0,
                                                            impulse_per_area: 60.0 });
        }
        if gfx::mouse_down(gfx::MOUSE_LEFT) {
            let d = gfx::mouse_delta();
            yaw += d.x * 0.005;
            pitch = clamp(pitch + d.y * 0.005, 0.05, 1.45);
        } else {
            yaw += 0.001;
        }
        distance = clamp(distance - gfx::mouse_wheel() * 2.0, 10.0, 120.0);

        // New boxes, and once there are enough, the oldest lifted back up.
        for k in rate {
            let at = raindrop(dropped, r);
            let turn = physics::quat_axis_angle(float3 { flt(r, -1.0, 1.0), flt(r, -1.0, 1.0),
                                                         flt(r, -1.0, 1.0) } + f3(0.01),
                                                flt(r, 0.0, 3.14));
            let velocity = float3 { flt(r, -0.3, 0.3), flt(r, -5.0, -3.0), flt(r, -0.3, 0.3) };
            let spin = float3 { flt(r, -3.0, 3.0), flt(r, -3.0, 3.0), flt(r, -3.0, 3.0) };
            let h = dropped * 0.0007 + flt(r, 0.0, 0.05);
            let look = Look { half: float3 { flt(r, 0.18, 0.45), flt(r, 0.18, 0.45),
                                             flt(r, 0.18, 0.45) },
                              color: hue(h - floor(h)) };
            if bodies.len - pyramid_boxes < max_boxes {
                let b = physics::create_body(world, physics::BodyDef {
                    body_type: physics::DYNAMIC, position: at, rotation: turn,
                    linear_velocity: velocity, angular_velocity: spin });
                physics::create_box_shape(b, physics::ShapeDef {}, look.half);
                bodies.push(b);
                looks.push(look);
            } else {
                // The oldest box, back up; it keeps its shape.
                let i = pyramid_boxes + oldest;
                oldest = (oldest + 1) % max_boxes;
                physics::set_transform(bodies[i], at, turn);
                physics::set_linear_velocity(bodies[i], velocity);
                physics::set_angular_velocity(bodies[i], spin);
                physics::set_awake(bodies[i], true);
                looks[i].color = look.color;
            }
            dropped++;
        }

        let before = clock();
        physics::step(world, DT, 4);
        stats_time += clock() - before;
        stats_frames++;

        // Every body's transform in one call, into the instances.
        transforms.resize(bodies.len, physics::transform_identity);
        physics::transforms(bodies, transforms);
        // A box knocked over a wall has nothing under it: it rains again.
        for i in bodies.len {
            if transforms[i].p.y < -10.0 {
                transforms[i].p = raindrop(dropped, r);
                dropped++;
                physics::set_transform(bodies[i], transforms[i].p, transforms[i].q);
                physics::set_linear_velocity(bodies[i], float3 { 0.0, -4.0, 0.0 });
            }
        }
        instances.clear();
        instances.append(props);
        let arm_at = physics::transform(arm);
        instances.push(Instance { position: arm_at.p, half: arm_half, rotation: arm_at.q,
                                  color: [230, 90, 60, 255] });
        for i in bodies.len {
            instances.push(Instance { position: transforms[i].p, half: looks[i].half,
                                      rotation: transforms[i].q, color: looks[i].color });
        }
        gfx::update_buffer(inst_vb, bytes_of(instances));

        let size = gfx::screen_size();
        let aspect = size.x as f32 / size.y;
        let eye = float3 { distance * cos(pitch) * cos(yaw), distance * sin(pitch),
                           distance * cos(pitch) * sin(yaw) };
        let scene = Scene {
            view_proj: gfx::mul(gfx::perspective(0.9, aspect, 0.5, 300.0),
                                gfx::look_at(eye, float3 { 0.0, 2.0, 0.0 }, up)),
            light_view_proj: light_view_proj };

        // The shadow map, then the boxes lit and shadowed.
        gfx::begin_pass(gfx::PassDesc { depth: shadow_map });
        gfx::bind(shadow_pipe);
        gfx::bind_vertex_buffer(0, cube_vb, 0);
        gfx::bind_vertex_buffer(1, inst_vb, 0);
        gfx::bind_index_buffer(cube_ib, 2);
        gfx::uniforms(gfx::VERTEX, 0, scene);
        gfx::draw_indexed_instanced(indices.len, instances.len);
        gfx::end_pass();

        gfx::begin_screen(float4 { 0.62, 0.72, 0.84, 1.0 });
        gfx::bind(boxes_pipe);
        gfx::bind_vertex_buffer(0, cube_vb, 0);
        gfx::bind_vertex_buffer(1, inst_vb, 0);
        gfx::bind_index_buffer(cube_ib, 2);
        gfx::bind_texture(gfx::FRAGMENT, 0, shadow_map, shadow_cmp);
        gfx::uniforms(gfx::VERTEX, 0, scene);
        gfx::uniforms(gfx::FRAGMENT, 0, Light { sun: float4 { sun.x, sun.y, sun.z, 0.0 },
                                                eye: float4 { eye.x, eye.y, eye.z, 1.0 },
                                                haze: float4 { 0.62, 0.72, 0.84, 0.006 } });
        gfx::draw_indexed_instanced(indices.len, instances.len);
        gfx::end_pass();

        if stats_frames == 30 {
            gfx::set_title(str("Goose: ", bodies.len - pyramid_boxes, " boxes, ",
                               physics::awake_body_count(world), " awake, a step takes ",
                               round(stats_time / 30.0 * 1000.0) as i64, " ms on ",
                               physics::worker_count(world), " threads (",
                               rate, " a frame; Space, mouse, Up/Down)"));
            stats_time = 0.0;
            stats_frames = 0;
        }
        drawn++;
        if drawn == frames { break; }
    }

    // How the last frame left things: every box still in the arena, the
    // pyramids knocked about, the arm turned.
    physics::transforms(bodies, transforms);
    var inside = true;
    var toppled = 0;
    for i in bodies.len {
        let p = transforms[i].p;
        inside = inside && abs(p.x) < ARENA + 1.0 && abs(p.z) < ARENA + 1.0 && p.y > -0.1;
    }
    for i in pyramid_boxes {
        if length(physics::linear_velocity(bodies[i])) > 0.01 { toppled++; }
    }
    let arm_turn = physics::rotation(arm);
    let saved = gfx::screenshot("physics_boxes.png");
    print("drew ", drawn, " frames; dropped ", dropped, " boxes; all in the arena: ", inside,
          "; the arm turned ", round(2.0 * acos(arm_turn.w) * 57.29578) as i64,
          " degrees; saved physics_boxes.png: ", saved);
    write_stderr(str(toppled, " of ", pyramid_boxes, " pyramid boxes moving\n"));
}

// A small to-do list, and a color mixer for what lies behind it, built with
// the ui module (docs/stdlib.md): Nuklear's immediate-mode widgets, drawn
// through gfx.
//
// Immediate mode means each frame the program says which windows and
// widgets there are, in order, and learns what the user did to them from
// the same calls: a button's returns true on the frame it is clicked, a
// check box flips the bool it is given, a text field edits the text it is
// given. The program keeps its own data as it likes; the ui keeps only
// where the windows are and what is open or active.
//
// Type a task and press Enter or Add, tick tasks off, pick which to show,
// mix the backdrop, and make the whole ui bigger or smaller. Escape or
// closing the window quits. `-- --frames N` stops after N frames. Either
// way the last frame is saved as ui_todo.png.
//
//   goose 29_ui_todo.goose
//
// Built from the generated C, the program links the ui layer and gfx's,
// whose paths `goose --ui-link` and `goose --gfx-link` print:
//   goose -o ui_todo.c 29_ui_todo.goose
//   cl ui_todo.c @<goose --ui-link msvc> @<goose --gfx-link msvc>
//   cc ui_todo.c -o ui_todo @<goose --ui-link cc> @<goose --gfx-link cc>

import std;
import vec;
import math;
import os;
import gfx;
import ui;

// Roboto (Apache 2.0, one of Nuklear's extra fonts), read into the program
// when it is compiled: no file to ship beside the executable.
let ROBOTO: const u8[:] = embed_file("data/Roboto-Regular.ttf");

struct Task { text: u8[..40], done: bool }

fn task(text: const u8[:], done: bool) -> Task {
    var t = Task { text: [], done: done };
    t.text.append(text);
    t
}

let SHOW_ALL = 0;
let SHOW_TO_DO = 1;
let SHOW_DONE = 2;

fn main() {
    var frames = -1;
    let argv = args();
    if argv.len == 3 && argv[1] == "--frames" {
        let n, ok = parse_int(argv[2]);
        if ok { frames = n; }
    }
    guard gfx::open("Goose: a ui to-do list", 760, 520, gfx::WINDOW_RESIZABLE) else {
        write_stderr(str("gfx: ", gfx::error(), "\n"));
        return;
    }
    defer gfx::close();   // Closed on every way out, the early return below included.
    // A context holds the ui's state; this one draws with the embedded
    // Roboto, 16 pixels high at a scale of 1 and baked again whenever the
    // scale changes.
    var ctx = ui::create_from_memory(ROBOTO, 16.0);
    guard ctx.id != 0 else {
        write_stderr(str("ui: ", ui::error(), "\n"));
        return;
    }
    defer ui::destroy(ctx);
    // Its style is Nuklear's, but for a brighter mark in ticked check boxes
    // and chosen options.
    var colors = ui::default_color_table();
    colors[ui::COLOR_TOGGLE_CURSOR] = ui::rgb(120, 200, 140);
    ui::style_from_table(ctx, colors);

    var tasks: Task[>..] = [];
    tasks.push(task("Feed the goose", true));
    tasks.push(task("Read docs/stdlib.md", false));
    tasks.push(task("Draw a window with ui", false));
    var entry: u8[..40] = [];
    var show = SHOW_ALL;
    var backdrop = ui::Colorf { 0.18, 0.24, 0.30, 1.0 };
    var next_scale = ui::scale(ctx);
    let window = ui::WINDOW_BORDER | ui::WINDOW_MOVABLE | ui::WINDOW_SCALABLE |
                 ui::WINDOW_TITLE | ui::WINDOW_MINIMIZABLE;
    var drawn = 0;

    while gfx::frame() {
        if gfx::key_pressed("Escape") { break; }
        // The frame's keys, mouse and typing, from gfx.
        ui::input_from_gfx(ctx);
        var quit = false;

        if ui::begin(ctx, "To do", ui::rect(30, 30, 380, 365), window) {
            // A menu bar goes first in its window.
            ui::menubar_begin(ctx);
            ui::layout_row_static(ctx, 20.0, 60, 1);
            if ui::menu_begin_label(ctx, "Tasks", ui::TEXT_LEFT, float2 { 140.0, 100.0 }) {
                ui::layout_row_dynamic(ctx, 22.0, 1);
                if ui::menu_item_label(ctx, "Tick them all", ui::TEXT_LEFT) {
                    for i in tasks.len { tasks[i].done = true; }
                }
                if ui::menu_item_label(ctx, "Clear the done", ui::TEXT_LEFT) {
                    var i = tasks.len;
                    while i > 0 {
                        i--;
                        if tasks[i].done { remove_at(tasks, i); }
                    }
                }
                if ui::menu_item_label(ctx, "Quit", ui::TEXT_LEFT) { quit = true; }
                ui::menu_end(ctx);
            }
            ui::menubar_end(ctx);

            // The text field takes three quarters of the row, the button
            // the rest. Enter commits the field as the button does.
            let ratios: f32[2] = [0.75, 0.25];
            ui::layout_row(ctx, ui::DYNAMIC, 28.0, ratios);
            let edited = ui::edit_string(ctx, ui::EDIT_FIELD | ui::EDIT_SIG_ENTER, entry,
                                         ui::FILTER_DEFAULT);
            // A tooltip is asked for before the widget it is about.
            if ui::widget_is_hovered(ctx) { ui::tooltip(ctx, "Adds the task (Enter does too)"); }
            let add = ui::button_label(ctx, "Add");
            if (add || (edited & ui::EDIT_COMMITTED) != 0) && entry.len > 0 {
                tasks.push(Task { text: entry, done: false });
                entry.resize(0);
            }

            // Which tasks show: one of three.
            ui::layout_row_dynamic(ctx, 24.0, 3);
            if ui::option_label(ctx, "All", show == SHOW_ALL) { show = SHOW_ALL; }
            if ui::option_label(ctx, "To do", show == SHOW_TO_DO) { show = SHOW_TO_DO; }
            if ui::option_label(ctx, "Done", show == SHOW_DONE) { show = SHOW_DONE; }

            // A check box per task, with a button that removes it.
            let row: f32[2] = [0.88, 0.12];
            var remove = -1;
            for i in tasks.len {
                let done = tasks[i].done;
                if (show == SHOW_TO_DO && done) || (show == SHOW_DONE && !done) { continue; }
                ui::layout_row(ctx, ui::DYNAMIC, 24.0, row);
                let text = tasks[i].text;
                ui::checkbox_label(ctx, text, tasks[i].done);
                if ui::button_symbol(ctx, ui::SYMBOL_X) { remove = i; }
            }
            if remove >= 0 { remove_at(tasks, remove); }

            var finished = 0;
            for t in tasks { if t.done { finished++; } }
            ui::layout_row_dynamic(ctx, 22.0, 1);
            ui::label(ctx, str(finished, " of ", tasks.len, " done"), ui::TEXT_LEFT);
            ui::progress(ctx, finished, max(tasks.len, 1), false);
        }
        ui::end(ctx);

        if ui::begin(ctx, "Backdrop", ui::rect(440, 30, 290, 365), window) {
            ui::layout_row_dynamic(ctx, 20.0, 1);
            ui::label(ctx, "The color behind the windows:", ui::TEXT_LEFT);
            ui::layout_row_dynamic(ctx, 150.0, 1);
            backdrop = ui::color_picker(ctx, backdrop, ui::RGB);
            // Properties: drag them, click their arrows, or type a value.
            ui::layout_row_dynamic(ctx, 24.0, 1);
            ui::property_float(ctx, "#Red:", 0.0, backdrop.r, 1.0, 0.01, 0.005);
            ui::property_float(ctx, "#Green:", 0.0, backdrop.g, 1.0, 0.01, 0.005);
            ui::property_float(ctx, "#Blue:", 0.0, backdrop.b, 1.0, 0.01, 0.005);
            // The whole ui bigger or smaller, from the next frame on.
            ui::layout_row_dynamic(ctx, 24.0, 3);
            ui::label(ctx, str("Scale ", ui::scale(ctx)), ui::TEXT_LEFT);
            if ui::button_symbol(ctx, ui::SYMBOL_MINUS) {
                next_scale = max(ui::scale(ctx) - 0.25, 0.5);
            }
            if ui::button_symbol(ctx, ui::SYMBOL_PLUS) {
                next_scale = min(ui::scale(ctx) + 0.25, 3.0);
            }
        }
        ui::end(ctx);

        // The backdrop, then the windows over it.
        gfx::begin_screen(float4 { backdrop.r, backdrop.g, backdrop.b, 1.0 });
        gfx::end_pass();
        ui::render(ctx);
        // Between frames: the context's font is baked again at the scale.
        if next_scale != ui::scale(ctx) { ui::set_scale(ctx, next_scale); }
        drawn++;
        if quit || drawn == frames { break; }
    }

    let saved = gfx::screenshot("ui_todo.png");
    var finished = 0;
    for t in tasks { if t.done { finished++; } }
    print("drew ", drawn, " frames; ", finished, " of ", tasks.len,
          " tasks done; saved ui_todo.png: ", saved);
}

// A little block world, built entirely from code: terrain, caves, trees,
// pixel textures, sky, and even the tiny font. There are no asset files.
// Start empty-handed, gather wood, make a pick, mine stone and coal, then
// build a cabin and light it. This is a programming sample, not an engine:
// a finite grid, a few plain structs, and one update/draw loop.
//
//   goose samples/30_mini_minecraft.goose
//   goose samples/30_mini_minecraft.goose -- --seed 123
//   goose samples/30_mini_minecraft.goose -- --frames 120
//   goose samples/30_mini_minecraft.goose -- --test
//
// WASD walk; Space jump/swim up; Shift run; mouse or arrows look.
// Ctrl sneaks slowly and stops at ledges; jumping releases that protection.
// Hold left mouse to mine; right mouse or E places (hold to build a row).
// 1-8 or wheel selects a slot; middle click picks the aimed-at material.
// C opens crafting; hold Shift with a recipe to make all affordable batches.
// H toggles help. Menus release the mouse cursor.
// Escape pauses/resumes; F5 saves; F9 loads; F12 takes a screenshot.
// Losing focus pauses. Click or Escape resumes when you return.
// Close the window to quit. Saving is explicit, to mini_minecraft.sav in
// the working directory; starting a new game never overwrites a save.
// --frames runs a fresh, deterministic world and saves mini_minecraft.png.
// --test checks gameplay without opening a window or touching save files.
//
// Deliberate limits: 80 x 40 x 80 blocks, no mobs, hunger, damage, dropped
// items, fluid simulation, tool wear, or infinite streaming. Water stays
// where it was generated. Materials go straight into the inventory.
// Lamps are full blocks, with at most sixteen placed lights. Lighting is
// approximate, so it can leak through a wall. Tools are permanent upgrades.
// A day lasts ten minutes; night is peaceful, but lamps help you see.
//
// Collision with this grid is simpler to show directly than to maintain
// a separate physics world full of static boxes.

import std;
import vec;
import math;
import os;
import gfx;

// --- blocks and game state ----------------------------------------------------

let WIDTH = 80;
let HEIGHT = 40;
let DEPTH = 80;
let VOLUME = WIDTH * HEIGHT * DEPTH;
let CHUNK = 16;
let CHUNKS_X = WIDTH / CHUNK;
let CHUNKS_Z = DEPTH / CHUNK;
let SEA = 12;
let SLOTS = 8;
let MAX_LAMPS = 16;
let DAY_LENGTH: f32 = 600.0;

let AIR:     u8 = 0;
let GRASS:   u8 = 1;
let DIRT:    u8 = 2;
let STONE:   u8 = 3;
let SAND:    u8 = 4;
let WOOD:    u8 = 5;
let LEAVES:  u8 = 6;
let PLANKS:  u8 = 7;
let COBBLE:  u8 = 8;
let COAL:    u8 = 9;
let WATER:   u8 = 10;
let BEDROCK: u8 = 11;
let LAMP:    u8 = 12;

// Inventory slots are separate from block IDs: stone drops cobblestone,
// grass drops dirt, and coal is a crafting ingredient rather than a block.
let SLOT_BLOCK: u8[SLOTS]          = [DIRT, COBBLE, WOOD, PLANKS, LEAVES, SAND, LAMP, AIR];
let SLOT_NAME:  const u8[:][SLOTS] =
    ["DIRT", "STONE", "WOOD", "PLANKS", "LEAVES", "SAND", "LAMPS", "COAL"];

struct Cell { x: i64, y: i64, z: i64 }
struct Player {
    feet:     float3,
    velocity: f32,
    yaw:      f32,
    pitch:    f32,
    grounded: bool,
}

// This small, pointer-free record is the save header. The large block grid
// stays in global storage: passing or copying Game never copies the world.
// Transient input and GPU handles are kept outside the saved state.
struct Game {
    version:  u32,
    seed:     u32,
    player:   Player,
    bag:      i32[SLOTS],
    tool:     i32,             // 0: hands, 1: wooden pick, 2: stone pick
    selected: i32,
}
var game:     Game;
var blocks:   u8[VOLUME];
var day_time: f32 = 90.0;       // Morning; zero is sunrise.

// Compute lighting once per frame, not once per block. The meshes contain
// only static sky exposure, so a moving sun never needs to rebuild them.
fn sun_direction() -> float3 {
    let angle: f32 = day_time / DAY_LENGTH * TAU;
    normalize(float3 { -cos(angle), sin(angle), 0.3 })
}
fn daylight() -> f32 { clamp(sun_direction().y * 3.0 + 0.35, 0.0, 1.0) }
fn horizon() -> float3 {
    let day = daylight();
    let dusk = 1.0 - abs(day * 2.0 - 1.0);
    float3 { 0.045, 0.065, 0.12 } * f3(1.0 - day) +
        float3 { 0.70, 0.82, 0.87 } * f3(day) + float3 { 0.30, 0.04, 0.0 } * f3(dusk)
}
fn advance_time(dt: f32) { day_time = (day_time + dt) % DAY_LENGTH; }

struct Mesh {
    vertices: gfx::Buffer,
    indices:  gfx::Buffer,
    count:    i64,
    dirty:    bool,
}
var meshes: Mesh[CHUNKS_X * CHUNKS_Z];
var lamps:  float4[MAX_LAMPS];
var lamp_count = 0;
var message:      u8[..100];
var message_time: f32 = 0.0;

// Cosmetic fragments are a fixed pool: breaking another block reuses the
// oldest slots. They never affect collisions, inventory, or saved games.
let MAX_DEBRIS = 48;
struct Debris { pos: float3, velocity: float3, life: f32, tile: i64 }
var debris: Debris[MAX_DEBRIS];
var next_debris = 0;

fn scatter(c: Cell, b: u8) {
    for i in 12 {
        let h = hash(c.x + i, c.y, c.z, game.seed);
        let velocity = float3 { (h & 255) / 64.0 - 2.0, 1.5 + ((h >> 8) & 255) / 128.0,
                                ((h >> 16) & 255) / 64.0 - 2.0 };
        debris[next_debris] = Debris {
            position(c) + f3(0.5) + velocity * f3(0.12), velocity, 0.45 + i * 0.012, tile_for(b, 4) };
        next_debris = (next_debris + 1) % MAX_DEBRIS;
    }
}
fn animate_debris(dt: f32) {
    for i in MAX_DEBRIS {
        if debris[i].life <= 0.0 { continue; }
        debris[i].life -= dt;
        debris[i].velocity.y -= 10.0 * dt;
        debris[i].pos += debris[i].velocity * f3(dt);
    }
}

fn say(text: const u8[:]) {
    message.resize(0);
    message.append(text);
    message_time = 4.0;
}

fn f3(n: f32) -> float3 { float3 { n, n, n } }
fn cell(x: i64, y: i64, z: i64) -> Cell { Cell { x, y, z } }
fn floor_cell(p: float3) -> Cell {
    Cell { floor(p.x) as i64, floor(p.y) as i64, floor(p.z) as i64 }
}
fn position(c: Cell) -> float3 { float3 { c.x, c.y, c.z } }
fn inside(c: Cell) -> bool {
    c.x >= 0 && c.x < WIDTH && c.y >= 0 && c.y < HEIGHT && c.z >= 0 && c.z < DEPTH
}
fn index(c: Cell) -> i64 { (c.y * DEPTH + c.z) * WIDTH + c.x }

fn block_at(c: Cell) -> u8 {
    if !inside(c) { return AIR; }
    blocks[index(c)]
}
fn solid(b: u8) -> bool { b != AIR && b != WATER }
fn put(c: Cell, b: u8) {
    if inside(c) { blocks[index(c)] = b; }
}
fn dirty_all() {
    for i in meshes.len { meshes[i].dirty = true; }
}
fn dirty_at(x: i64, z: i64) {
    if x >= 0 && x < WIDTH && z >= 0 && z < DEPTH {
        meshes[(z / CHUNK) * CHUNKS_X + x / CHUNK].dirty = true;
    }
}
fn find_lamps() {
    lamps = [float4_0; MAX_LAMPS];
    lamp_count = 0;
    for y in HEIGHT {
        for z in DEPTH {
            for x in WIDTH {
                if block_at(cell(x, y, z)) == LAMP && lamp_count < MAX_LAMPS {
                    lamps[lamp_count] = float4 { x + 0.5, y + 0.5, z + 0.5, 1.0 };
                    lamp_count++;
                }
            }
        }
    }
}
fn edit(c: Cell, b: u8) {
    let old = block_at(c);
    put(c, b);
    // Corner shading samples diagonal neighbours too. Rebuild all chunks
    // touched by a one-cell border; most edits still touch only one chunk.
    for dz in -1..2 {
        for dx in -1..2 { dirty_at(c.x + dx, c.z + dz); }
    }
    if old == LAMP || b == LAMP { find_lamps(); }
}

// --- deterministic terrain ---------------------------------------------------

// Unsigned arithmetic wraps. A coordinate hash needs no mutable random
// state, so adding a tree does not change the hills or texture patterns.
fn hash(x: i64, y: i64, z: i64, seed: u32) -> u32 {
    var h = (x as! u32) * 374761393 + (y as! u32) * 668265263;
    h += (z as! u32) * 2246822519 + seed * 3266489917;
    h = (h ^ (h >> 13)) * 1274126177;
    h ^ (h >> 16)
}
fn noise_value(x: i64, z: i64) -> f32 {
    (hash(x, 0, z, game.seed) & 65535) / 65535.0
}
fn noise(x: f32, z: f32) -> f32 {
    let ix = floor(x) as i64;
    let iz = floor(z) as i64;
    let fx = x - ix;
    let fz = z - iz;
    let u = fx * fx * (3.0 - 2.0 * fx);
    let v = fz * fz * (3.0 - 2.0 * fz);
    let a = noise_value(ix, iz) * (1.0 - u) + noise_value(ix + 1, iz) * u;
    let b = noise_value(ix, iz + 1) * (1.0 - u) + noise_value(ix + 1, iz + 1) * u;
    a * (1.0 - v) + b * v
}
fn ground_height(x: i64, z: i64) -> i64 {
    let broad = noise(x / 24.0, z / 24.0);
    let detail = noise(x / 8.0, z / 8.0);
    // A basin guarantees a lake; a broad ridge gives the cave a hillside.
    let lake = max(0.0, 1.0 - sqrt((x - 23.0) * (x - 23.0) +
                                  (z - 28.0) * (z - 28.0)) / 18.0);
    let ridge = max(0.0, 1.0 - abs(x - 58.0) / 15.0);
    let terrain = 13.0 + broad * 7.0 + detail * 3.0 - lake * 11.0 + ridge * 7.0;
    let distance = sqrt((x - 40.0) * (x - 40.0) + (z - 40.0) * (z - 40.0));
    let clearing = clamp((distance - 8.0) / 5.0, 0.0, 1.0);
    floor(19.0 * (1.0 - clearing) + terrain * clearing) as i64
}
fn highest(x: i64, z: i64) -> i64 {
    var y = HEIGHT - 1;
    while y > 0 && !solid(block_at(cell(x, y, z))) { y--; }
    y
}
fn tree(x: i64, z: i64) {
    let base = ground_height(x, z) + 1;
    if block_at(cell(x, base - 1, z)) != GRASS { return; }
    let height = 4 + (hash(x, 1, z, game.seed) % 2) as i64;
    for y in base + 3..base + height + 2 {
        let radius = if y == base + height + 1 { 1 } else { 2 };
        for dz in -radius..radius + 1 {
            for dx in -radius..radius + 1 {
                if abs(dx) == 2 && abs(dz) == 2 { continue; }
                let c = cell(x + dx, y, z + dz);
                if block_at(c) == AIR { put(c, LEAVES); }
            }
        }
    }
    for y in base..base + height { put(cell(x, y, z), WOOD); }
}
fn respawn() {
    // Search dry ground from the centre, without placing the player in a
    // trunk, a leaf canopy, a saved building, or the lake.
    for radius in 0..WIDTH / 2 {
        for z in max(1, 40 - radius)..min(DEPTH - 1, 41 + radius) {
            for x in max(1, 40 - radius)..min(WIDTH - 1, 41 + radius) {
                let y = highest(x, z);
                let b = block_at(cell(x, y, z));
                if (b == GRASS || b == SAND || b == STONE) && y >= SEA && y < HEIGHT - 3 {
                    game.player = Player {
                        feet: float3 { x + 0.5, y + 1.001, z + 0.5 },
                        velocity: 0.0, yaw: -0.4, pitch: -0.12, grounded: false };
                    return;
                }
            }
        }
    }
    game.player = Player { feet: float3 { 40.5, 41.0, 40.5 }, .. };
}
fn generate(seed: u32) {
    game = Game { version: 1, seed: seed, .. };
    day_time = 90.0;
    debris = [Debris { .. }; MAX_DEBRIS];
    message_time = 0.0;
    for i in VOLUME { blocks[i] = AIR; }
    for z in DEPTH {
        for x in WIDTH {
            let top = ground_height(x, z);
            for y in 0..max(top + 1, SEA + 1) {
                var b = STONE;
                if y == 0 { b = BEDROCK; }
                else if y > top { b = WATER; }
                else if y == top { b = if top <= SEA + 1 { SAND } else { GRASS }; }
                else if y >= top - 3 { b = if top <= SEA + 1 { SAND } else { DIRT }; }
                else {
                    // Coarse vein clusters with little ragged edges.
                    let vein = hash(x / 3, y / 3, z / 3, seed) % 13 == 0;
                    if vein && hash(x, y, z, seed) % 4 != 0 { b = COAL; }
                    let cave = sin(x * 0.24) + cos(z * 0.21) + sin(y * 0.55 + x * 0.11);
                    if y > 2 && y < top - 4 && cave > 2.25 { b = AIR; }
                }
                put(cell(x, y, z), b);
            }
        }
    }
    // A walk-in tunnel starts at the clearing and slopes into the ridge.
    // Carving overlapping little spheres is easy to read and modify.
    let entrance = ground_height(46, 40);
    for step in 22 {
        let cx: f32 = 45.0 + step * 0.65;
        let cy: f32 = entrance + 1.3 - step * 0.22;
        let cz: f32 = 40.0 - step * 0.38;
        for y in 2..HEIGHT - 1 {
            for z in 28..44 {
                for x in 43..63 {
                    let d = float3 { x + 0.5 - cx, y + 0.5 - cy, z + 0.5 - cz };
                    if length_sq(d) < 3.2 { put(cell(x, y, z), AIR); }
                }
            }
        }
    }
    for z in 4..DEPTH - 4 {
        for x in 4..WIDTH - 4 {
            let clearing = abs(x - 40) < 11 && abs(z - 40) < 11;
            if !clearing && x % 4 == 0 && z % 4 == 0 && hash(x, 5, z, seed) % 3 == 0 {
                tree(x, z);
            }
        }
    }
    tree(38, 34);           // The first resource is always a few steps away.
    respawn();
    find_lamps();
    dirty_all();
}

// --- walking, swimming, and a grid ray ---------------------------------------

let RADIUS:      f32 = 0.29;
let BODY_HEIGHT: f32 = 1.8;
let EYE_HEIGHT:  f32 = 1.62;
let STEP:        f32 = 1.0 / 120.0;

fn eye() -> float3 { game.player.feet + float3 { 0.0, EYE_HEIGHT, 0.0 } }
fn forward() -> float3 {
    let p = game.player;
    float3 { sin(p.yaw) * cos(p.pitch), sin(p.pitch), -cos(p.yaw) * cos(p.pitch) }
}
fn overlaps(feet: float3, c: Cell) -> bool {
    feet.x + RADIUS > c.x && feet.x - RADIUS < c.x + 1 &&
    feet.y + BODY_HEIGHT > c.y && feet.y < c.y + 1 &&
    feet.z + RADIUS > c.z && feet.z - RADIUS < c.z + 1
}
fn blocked(feet: float3) -> bool {
    // The finite map's edges are walls, while its sky is open.
    if feet.x < RADIUS || feet.z < RADIUS || feet.x > WIDTH - RADIUS ||
       feet.z > DEPTH - RADIUS || feet.y < 1.0 { return true; }
    let lo = floor_cell(feet - float3 { RADIUS, 0.0, RADIUS });
    let hi = floor_cell(feet + float3 { RADIUS, BODY_HEIGHT - 0.001, RADIUS });
    for y in lo.y..hi.y + 1 {
        for z in lo.z..hi.z + 1 {
            for x in lo.x..hi.x + 1 {
                if solid(block_at(cell(x, y, z))) { return true; }
            }
        }
    }
    false
}
fn wet(feet: float3) -> bool {
    block_at(floor_cell(feet + float3 { 0.0, 0.05, 0.0 })) == WATER
}
fn supported(feet: float3) -> bool {
    // Leave a little overlap with the floor when sneaking onto a ledge.
    // Water does not count as support, and only the layer below the feet
    // matters: a nearby wall must not let us walk off a roof.
    let margin: f32 = RADIUS - 0.02;
    let lo = floor_cell(feet - float3 { margin, 0.05, margin });
    let hi = floor_cell(feet + float3 { margin, -0.05, margin });
    for z in lo.z..hi.z + 1 {
        for x in lo.x..hi.x + 1 {
            if solid(block_at(cell(x, lo.y, z))) { return true; }
        }
    }
    false
}
fn move_axis(delta: float3, keep_support: bool = false) -> bool {
    let start = game.player.feet;
    if !blocked(start + delta) && (!keep_support || supported(start + delta)) {
        game.player.feet += delta;
        return false;
    }
    // Find the contact point. The fixed timestep bounds each move to less
    // than a block, and bisection leaves the player just outside the wall.
    var lo: f32 = 0.0;
    var hi: f32 = 1.0;
    for i in 10 {
        let mid = (lo + hi) * 0.5;
        let candidate = start + delta * f3(mid);
        if blocked(candidate) || (keep_support && !supported(candidate)) { hi = mid; }
        else { lo = mid; }
    }
    game.player.feet += delta * f3(lo);
    true
}
fn walk(direction: float2, jump: bool, run: bool, sneak: bool = false) {
    let swimming = wet(game.player.feet);
    let speed: f32 = if swimming { 2.6 } else if sneak { 1.5 } else if run { 6.0 } else { 4.2 };
    let right = float3 { cos(game.player.yaw), 0.0, sin(game.player.yaw) };
    let ahead = float3 { sin(game.player.yaw), 0.0, -cos(game.player.yaw) };
    var input = direction;
    if length_sq(input) > 1.0 { input = normalize(input); }
    let delta = (right * f3(input.x) + ahead * f3(input.y)) * f3(speed * STEP);
    let keep_support = sneak && game.player.grounded && !jump && !swimming;
    move_axis(float3 { delta.x, 0.0, 0.0 }, keep_support);
    move_axis(float3 { 0.0, 0.0, delta.z }, keep_support);
    if swimming {
        game.player.velocity = max(game.player.velocity - 4.0 * STEP, -2.0);
        if jump {
            game.player.velocity = 4.0;
            // A kick near the surface clears a one-block shore. Testing
            // the feet for water keeps this active until we actually exit.
            if block_at(floor_cell(game.player.feet + float3 { 0.0, 1.0, 0.0 })) != WATER {
                game.player.velocity = 8.0;
            }
        }
    } else {
        if jump && game.player.grounded { game.player.velocity = 8.0; }
        game.player.velocity = max(game.player.velocity - 23.0 * STEP, -30.0);
    }
    let hit = move_axis(float3 { 0.0, game.player.velocity * STEP, 0.0 });
    game.player.grounded = hit && game.player.velocity < 0.0;
    if hit { game.player.velocity = 0.0; }
}

struct Hit { found: bool, at: Cell, before: Cell, distance: f32 }
fn ray(origin: float3, direction: float3, reach: f32) -> Hit {
    // DDA: cross exactly one grid plane each step. This neither skips thin
    // targets nor guesses the placement face from a small sampling step.
    var at = floor_cell(origin);
    var before = at;
    let step = Cell { if direction.x >= 0.0 { 1 } else { -1 },
                      if direction.y >= 0.0 { 1 } else { -1 },
                      if direction.z >= 0.0 { 1 } else { -1 } };
    let delta = float3 {
        if abs(direction.x) < 0.00001 { 1.0e8 } else { abs(1.0 / direction.x) },
        if abs(direction.y) < 0.00001 { 1.0e8 } else { abs(1.0 / direction.y) },
        if abs(direction.z) < 0.00001 { 1.0e8 } else { abs(1.0 / direction.z) } };
    var next = float3 {
        (if step.x > 0 { at.x + 1.0 - origin.x } else { origin.x - at.x }) * delta.x,
        (if step.y > 0 { at.y + 1.0 - origin.y } else { origin.y - at.y }) * delta.y,
        (if step.z > 0 { at.z + 1.0 - origin.z } else { origin.z - at.z }) * delta.z };
    var travelled: f32 = 0.0;
    while travelled <= reach {
        if solid(block_at(at)) { return Hit { true, at, before, travelled }; }
        before = at;
        if next.x <= next.y && next.x <= next.z {
            travelled = next.x;
            next.x += delta.x;
            at.x += step.x;
        } else if next.y <= next.z {
            travelled = next.y;
            next.y += delta.y;
            at.y += step.y;
        } else {
            travelled = next.z;
            next.z += delta.z;
            at.z += step.z;
        }
    }
    Hit { found: false, .. }
}

// --- mining, building, and four recipes --------------------------------------

fn drop_slot(b: u8) -> i64 {
    if b == GRASS || b == DIRT { return 0; }
    if b == STONE || b == COBBLE { return 1; }
    if b == COAL { return 7; }
    for i in SLOTS { if SLOT_BLOCK[i] == b { return i; } }
    -1
}
fn pick_material(hit: Hit) {
    if !hit.found { return; }
    let slot = drop_slot(block_at(hit.at));
    if slot >= 0 && SLOT_BLOCK[slot] != AIR {
        game.selected = slot as i32;
        if game.bag[slot] == 0 { say("MINE SOME OF THIS MATERIAL FIRST"); }
    }
}
fn mining_seconds(b: u8) -> f32 {
    if b == BEDROCK { return 0.0; }
    if b == STONE || b == COBBLE || b == COAL {
        if game.tool == 0 { return 0.0; }
        return if game.tool == 1 { 1.15 } else { 0.45 };
    }
    if b == WOOD { return 1.0; }
    if b == PLANKS { return 0.65; }
    if b == LEAVES || b == LAMP { return 0.18; }
    0.35
}
fn mine(c: Cell) -> bool {
    let b = block_at(c);
    let slot = drop_slot(b);
    if slot < 0 || mining_seconds(b) <= 0.0 { return false; }
    if game.bag[slot] >= 999 { say("THAT STACK IS FULL (999)"); return false; }
    game.bag[slot]++;
    edit(c, AIR);
    scatter(c, b);
    true
}
fn place(hit: Hit) -> bool {
    if !hit.found || hit.at == hit.before || !inside(hit.before) { return false; }
    let slot = game.selected;
    let b = SLOT_BLOCK[slot];
    if b == AIR { say("COAL IS FOR CRAFTING LAMPS"); return false; }
    if game.bag[slot] == 0 { say("MINE OR CRAFT SOME FIRST"); return false; }
    if solid(block_at(hit.before)) || overlaps(game.player.feet, hit.before) { return false; }
    if b == LAMP && lamp_count == MAX_LAMPS {
        say("SIXTEEN LIGHTS MAX - PICK ONE UP FIRST");
        return false;
    }
    edit(hit.before, b);
    game.bag[slot]--;
    true
}
fn can_craft(recipe: i64) -> bool {
    if recipe == 0 { return game.bag[2] >= 1 && game.bag[3] <= 995; }
    if recipe == 1 { return game.tool == 0 && game.bag[3] >= 5; }
    if recipe == 2 { return game.tool == 1 && game.bag[1] >= 3 && game.bag[3] >= 2; }
    if recipe == 3 { return game.bag[7] >= 1 && game.bag[3] >= 1 && game.bag[6] <= 995; }
    false
}
fn craft(recipe: i64) -> bool {
    if !can_craft(recipe) {
        say("NOT ENOUGH MATERIALS, OR UPGRADE ALREADY OWNED");
        return false;
    }
    if recipe == 0 {
        game.bag[2]--;
        game.bag[3] += 4;
        say("MADE FOUR PLANKS");
        return true;
    }
    if recipe == 1 {
        game.bag[3] -= 5;
        game.tool = 1;
        say("WOODEN PICK - NOW YOU CAN MINE STONE");
        return true;
    }
    if recipe == 2 {
        game.bag[1] -= 3;
        game.bag[3] -= 2;
        game.tool = 2;
        say("STONE PICK - FASTER MINING");
        return true;
    }
    if recipe == 3 {
        game.bag[7]--;
        game.bag[3]--;
        game.bag[6] += 4;
        say("MADE FOUR LAMPS - SELECT SLOT 7 TO PLACE");
        return true;
    }
    false
}
fn craft_batches(recipe: i64, all: bool) -> i64 {
    if !craft(recipe) { return 0; }
    var batches = 1;
    // can_craft checks both ingredients and stack capacity. Tools become
    // unavailable once owned, so even "craft all" makes only one upgrade.
    while all && can_craft(recipe) {
        craft(recipe);
        batches++;
    }
    if batches > 1 {
        say(str("MADE ", batches * 4, if recipe == 0 { " PLANKS" } else { " LAMPS" }));
    }
    batches
}

// --- explicit saves ----------------------------------------------------------

fn valid_save(g: const Game&, cells: const u8[:]) -> bool {
    if cells.len != VOLUME { return false; }
    if g.version != 1 || g.tool < 0 || g.tool > 2 || g.selected < 0 || g.selected >= SLOTS {
        return false;
    }
    for n in g.bag { if n < 0 || n > 999 { return false; } }
    var lights = 0;
    for b in cells {
        if b > LAMP { return false; }
        if b == LAMP { lights++; }
    }
    if lights > MAX_LAMPS { return false; }
    let p = g.player;
    // Positive tests reject NaNs as well as out-of-range values.
    if !(p.feet.x >= RADIUS && p.feet.x <= WIDTH - RADIUS &&
         p.feet.z >= RADIUS && p.feet.z <= DEPTH - RADIUS &&
         p.feet.y >= 1.0 && p.feet.y <= HEIGHT + 8.0 &&
         p.yaw >= -100.0 && p.yaw <= 100.0 && abs(p.pitch) <= 1.5 &&
         abs(p.velocity) <= 30.0) { return false; }
    for z in DEPTH {
        for x in WIDTH { if cells[z * WIDTH + x] != BEDROCK { return false; } }
    }
    true
}
fn save_image() -> u8[>..] {
    var image: u8[>..] = [];
    image.append("GSM2");
    to_bytes([game], image);
    image.append(blocks);
    to_bytes([day_time], image);
    image
}
fn restore(image: const u8[:]) -> bool {
    // The header uses Goose's framed serialization; the grid is just bytes
    // of block IDs. Validate both before changing anything in the game.
    let header_size = to_bytes([Game { .. }]).len;
    let grid_end = 4 + header_size + VOLUME;
    let clock_size = to_bytes([day_time]).len;
    if image.len < 4 { return false; }
    let legacy = image[..4] == "GSM1";
    if legacy {
        if image.len != grid_end { return false; }
    } else if image[..4] != "GSM2" || image.len != grid_end + clock_size { return false; }
    var header, ok = from_bytes<Game[>..]>(image[4..4 + header_size]);
    if !ok || header.len != 1 { return false; }
    let saved_blocks = image[4 + header_size..grid_end];
    if !valid_save(header[0], saved_blocks) { return false; }
    // The first version had no clock. Old worlds resume in the morning.
    var saved_time: f32 = 90.0;
    if !legacy {
        let clock, clock_ok = from_bytes<f32[>..]>(image[grid_end..]);
        if !clock_ok || clock.len != 1 || !(clock[0] >= 0.0 && clock[0] < DAY_LENGTH) { return false; }
        saved_time = clock[0];
    }
    game = header[0];
    day_time = saved_time;
    debris = [Debris { .. }; MAX_DEBRIS];
    for i in VOLUME { blocks[i] = saved_blocks[i]; }
    if blocked(game.player.feet) { respawn(); }
    find_lamps();
    dirty_all();
    true
}
fn save_game() {
    let image = save_image();
    if write_file_atomic("mini_minecraft.sav", image) { say("SAVED MINI_MINECRAFT.SAV"); }
    else { say("SAVE FAILED - CHECK THE WORKING DIRECTORY"); }
}
fn load_game() {
    var image: u8[>..] = [];
    if !read_file("mini_minecraft.sav", image) { say("NO READABLE MINI_MINECRAFT.SAV"); return; }
    if !restore(image) { say("SAVE FILE IS DAMAGED OR INCOMPATIBLE"); return; }
    say("WORLD LOADED");
}

// --- a 256 x 16 texture atlas, painted one pixel at a time --------------------

let TILE_SIZE = 16;
let TILES = 16;
let WHITE_TILE = 14;
let TILE_COLOR: int3[TILES] = [
    int3 { 101, 153, 58 }, int3 { 126, 89, 55 }, int3 { 126, 89, 55 },
    int3 { 129, 132, 130 }, int3 { 220, 204, 150 }, int3 { 106, 76, 43 },
    int3 { 173, 137, 81 }, int3 { 65, 120, 48 }, int3 { 177, 135, 79 },
    int3 { 126, 131, 133 }, int3 { 121, 126, 128 }, int3 { 52, 126, 176 },
    int3 { 61, 64, 74 }, int3 { 244, 198, 94 }, int3 { 255, 255, 255 },
    int3 { 255, 255, 255 }];

fn tile_for(b: u8, face: i64) -> i64 {
    if b == GRASS { return if face == 2 { 0 } else if face == 3 { 2 } else { 1 }; }
    if b == WOOD { return if face == 2 || face == 3 { 6 } else { 5 }; }
    if b == DIRT { return 2; }
    if b == STONE { return 3; }
    if b == SAND { return 4; }
    if b == LEAVES { return 7; }
    if b == PLANKS { return 8; }
    if b == COBBLE { return 9; }
    if b == COAL { return 10; }
    if b == WATER { return 11; }
    if b == BEDROCK { return 12; }
    if b == LAMP { return 13; }
    WHITE_TILE
}
fn pixel(tile: i64, x: i64, y: i64) -> u8[4] {
    var color = TILE_COLOR[tile];
    var grain = (hash(x, tile, y, 71) % 27) as i64 - 13;
    if tile == 1 && y < 3 + (hash(x / 2, 0, 0, 8) % 3) as i64 {
        color = TILE_COLOR[0];
    }
    if tile == 3 { grain += if (x + y * 3) % 11 == 0 { -20 } else { 0 }; }
    if tile == 5 { grain += if (x + (y / 5)) % 4 == 0 { -30 } else { 9 }; }
    if tile == 6 {
        let ring = max(abs(x - 7), abs(y - 7));
        grain += if ring % 3 == 0 { -30 } else { 12 };
    }
    if tile == 7 {
        grain += if hash(x / 2, 0, y / 2, 17) % 3 == 0 { -28 } else { 10 };
    }
    if tile == 8 {
        if y % 4 == 0 || (x + (y / 4) * 7) % 16 == 0 { grain = -42; }
        else { grain += if y % 4 == 1 { 12 } else { 0 }; }
    }
    if tile == 9 {
        let row = y / 5;
        if y % 5 == 0 || (x + row * 3) % 7 == 0 { grain = -45; }
        else if y % 5 == 1 { grain = 18; }
    }
    if tile == 10 && hash(x / 2, 0, y / 2, 9) % 5 == 0 { color = int3 { 32, 34, 39 }; }
    if tile == 11 { grain = if (x + y * 3) % 13 < 2 { 20 } else { 0 }; }
    if tile == 12 { grain *= 2; }
    if tile == 13 {
        if x < 2 || x > 13 || y < 2 || y > 13 { color = int3 { 94, 66, 39 }; }
        else { grain = if x == 7 || y == 7 { 25 } else { 0 }; }
    }
    if tile >= WHITE_TILE { grain = 0; }
    [clamp(color.x + grain, 0, 255) as u8, clamp(color.y + grain, 0, 255) as u8,
     clamp(color.z + grain, 0, 255) as u8, 255]
}
fn make_atlas() -> gfx::Texture {
    var pixels: u8[>..] = [];
    for y in TILE_SIZE {
        for tile in TILES {
            for x in TILE_SIZE { pixels.append(pixel(tile, x, y)); }
        }
    }
    let texture = gfx::texture2d(TILE_SIZE * TILES, TILE_SIZE);
    if texture.id == 0 || !gfx::update_texture(texture, pixels) {
        abort(str("texture: ", gfx::error()));
    }
    texture
}
fn atlas_uv(tile: i64, x: f32, y: f32) -> float2 {
    // Sample inside the tile, so the nearest sampler never grabs a pixel
    // from its neighbour, even right at the edge of a face.
    float2 { (tile * TILE_SIZE + 0.5 + x * 15.0) / (TILE_SIZE * TILES),
             (0.5 + y * 15.0) / TILE_SIZE }
}

// --- exposed faces, split into 16 x 40 x 16 chunks ----------------------------

struct Vertex {
    pos:      float3,
    normal:   float3,
    uv:       float2,
    shade:    f32,
    material: f32,
}
let NORMAL: Cell[6] = [Cell { 1, 0, 0 }, Cell { -1, 0, 0 },
                        Cell { 0, 1, 0 }, Cell { 0, -1, 0 },
                        Cell { 0, 0, 1 }, Cell { 0, 0, -1 }];
let ACROSS: Cell[6] = [Cell { 0, 0, -1 }, Cell { 0, 0, 1 },
                        Cell { 1, 0, 0 }, Cell { 1, 0, 0 },
                        Cell { 1, 0, 0 }, Cell { -1, 0, 0 }];
let UP: Cell[6] = [Cell { 0, 1, 0 }, Cell { 0, 1, 0 },
                    Cell { 0, 0, -1 }, Cell { 0, 0, 1 },
                    Cell { 0, 1, 0 }, Cell { 0, 1, 0 }];
let CORNERS: float2[4] = [float2 { -1.0, -1.0 }, float2 { 1.0, -1.0 },
                          float2 { 1.0, 1.0 }, float2 { -1.0, 1.0 }];
var column_top: i64[WIDTH * DEPTH];

fn offset(c: Cell, dir: Cell, amount: i64) -> Cell {
    Cell { c.x + dir.x * amount, c.y + dir.y * amount, c.z + dir.z * amount }
}
fn sky_light(c: Cell) -> f32 {
    if c.x < 0 || c.x >= WIDTH || c.z < 0 || c.z >= DEPTH { return 1.0; }
    if c.y > column_top[c.z * WIDTH + c.x] { return 1.0; }
    0.32
}
fn face_visible(b: u8, neighbour: u8) -> bool {
    if b == WATER { return neighbour == AIR; }
    neighbour == AIR || neighbour == WATER
}
fn add_face(vertices: Vertex[>..]&, indices: u32[>..]&, c: Cell, b: u8, face: i64) {
    let n = NORMAL[face];
    let u = ACROSS[face];
    let v = UP[face];
    let outside = c + n;
    let base = vertices.len as u32;
    for corner in CORNERS {
        let side_u = offset(outside, u, corner.x as i64);
        let side_v = offset(outside, v, corner.y as i64);
        let diagonal = offset(side_u, v, corner.y as i64);
        let a = solid(block_at(side_u));
        let d = solid(block_at(side_v));
        let e = solid(block_at(diagonal));
        // Three neighbouring blocks darken a corner; two touching sides
        // close it completely, even if the diagonal happens to be air.
        var occlusion = 0;
        if a { occlusion++; }
        if d { occlusion++; }
        if e { occlusion++; }
        if a && d { occlusion = 3; }
        let shade = sky_light(outside) * (1.0 - occlusion * 0.16);
        let p = position(c) + f3(0.5) + position(n) * f3(0.5) +
                position(u) * f3(corner.x * 0.5) + position(v) * f3(corner.y * 0.5);
        let uv = atlas_uv(tile_for(b, face), corner.x * 0.5 + 0.5, 0.5 - corner.y * 0.5);
        vertices.push(Vertex { p, position(n), uv, shade, b });
    }
    indices.append([base, base + 1, base + 2, base, base + 2, base + 3]);
}
fn rebuild_chunk(cx: i64, cz: i64) {
    // Scratch lives only until this function returns. The GPU owns a copy.
    var vertices: Vertex[>..] = [];
    var indices:  u32[>..]    = [];
    for y in HEIGHT {
        for z in cz * CHUNK..(cz + 1) * CHUNK {
            for x in cx * CHUNK..(cx + 1) * CHUNK {
                let c = cell(x, y, z);
                let b = block_at(c);
                if b == AIR { continue; }
                for face in 6 {
                    if face_visible(b, block_at(c + NORMAL[face])) {
                        add_face(vertices, indices, c, b, face);
                    }
                }
            }
        }
    }
    let i = cz * CHUNKS_X + cx;
    if meshes[i].vertices.id != 0 { gfx::release(meshes[i].vertices); }
    if meshes[i].indices.id != 0 { gfx::release(meshes[i].indices); }
    meshes[i] = Mesh { count: indices.len, .. };
    if indices.len > 0 {
        meshes[i].vertices = gfx::vertex_buffer(bytes_of(vertices));
        meshes[i].indices = gfx::index_buffer(bytes_of(indices));
        if meshes[i].vertices.id == 0 || meshes[i].indices.id == 0 {
            abort(str("chunk buffers: ", gfx::error()));
        }
    }
}
fn rebuild_dirty() {
    var any = false;
    for m in meshes { any = any || m.dirty; }
    if !any { return; }
    for z in DEPTH {
        for x in WIDTH { column_top[z * WIDTH + x] = highest(x, z); }
    }
    for cz in CHUNKS_Z {
        for cx in CHUNKS_X {
            if meshes[cz * CHUNKS_X + cx].dirty { rebuild_chunk(cx, cz); }
        }
    }
}

fn debris_vertices(right: float3, up: float3) -> Vertex[>..] {
    // Camera-facing squares reuse the world's texture atlas and lighting.
    // Only a small patch of each tile is needed for a chip of that material.
    var vertices: Vertex[>..] = [];
    let order: i64[6] = [0, 1, 2, 0, 2, 3];
    let normal = cross(right, up);
    for bit in debris {
        if bit.life <= 0.0 { continue; }
        let size: f32 = 0.065 * min(1.0, bit.life * 8.0);
        for i in order {
            let corner = CORNERS[i];
            let p = bit.pos + right * f3(corner.x * size) + up * f3(corner.y * size);
            let uv = atlas_uv(bit.tile, 0.5 + corner.x * 0.125, 0.5 - corner.y * 0.125);
            vertices.push(Vertex { p, normal, uv, sky_light(floor_cell(p)), -1.0 });
        }
    }
    vertices
}

// --- shaders ----------------------------------------------------------------

// Every field begins on a 16-byte boundary, exactly as GLSL std140 wants.
// eye.w is time; target.w is mining progress, or -1 if nothing is targeted.
struct Scene {
    view_proj: gfx::mat4,
    eye:       float4,
    target:    float4,
    lights:    float4[MAX_LAMPS],
    haze:      float4,
    sun:       float4,        // xyz: direction, w: daylight strength
}
let scene_uniform = """
    layout(set = 3, binding = 0) uniform Scene {
        mat4 view_proj;
        vec4 eye;
        vec4 target;
        vec4 lights[16];
        vec4 haze;
        vec4 sun;
    };
    """;
let world_vertex = """
    layout(location = 0) in vec3 a_pos;
    layout(location = 1) in vec3 a_normal;
    layout(location = 2) in vec2 a_uv;
    layout(location = 3) in float a_shade;
    layout(location = 4) in float a_material;
    layout(set = 1, binding = 0) uniform Camera { mat4 view_proj; };
    layout(location = 0) out vec3 v_world;
    layout(location = 1) out vec3 v_normal;
    layout(location = 2) out vec2 v_uv;
    layout(location = 3) out float v_shade;
    layout(location = 4) flat out float v_material;
    void main() {
        v_world = a_pos;
        v_normal = a_normal;
        v_uv = a_uv;
        v_shade = a_shade;
        v_material = a_material;
        gl_Position = view_proj * vec4(a_pos, 1.0);
    }
    """;
let world_fragment = """
    layout(location = 0) in vec3 v_world;
    layout(location = 1) in vec3 v_normal;
    layout(location = 2) in vec2 v_uv;
    layout(location = 3) in float v_shade;
    layout(location = 4) flat in float v_material;
    layout(set = 2, binding = 0) uniform sampler2D atlas;
    layout(location = 0) out vec4 result;
    void main() {
        vec3 base = texture(atlas, v_uv).rgb;
        float direct = max(dot(v_normal, sun.xyz), 0.0) * sun.w;
        vec3 light = mix(vec3(0.10, 0.14, 0.23), vec3(0.64, 0.73, 0.82) * 0.48, sun.w);
        light += vec3(0.66, 0.59, 0.43) * direct;
        light *= v_shade;
        for (int i = 0; i < 16; i++) {
            float d = length(lights[i].xyz - v_world);
            float glow = max(0.0, 1.0 - d / 7.0);
            light += vec3(1.0, 0.63, 0.25) * glow * glow * lights[i].w;
        }
        if (v_material == 12.0) light = max(light, vec3(1.1, 0.96, 0.7));
        if (v_material == 10.0) {
            float wave = sin(v_world.x * 2.7 + eye.w) * sin(v_world.z * 3.1 - eye.w);
            base += vec3(0.04, 0.07, 0.08) * wave;
            light = max(light, vec3(mix(0.15, 0.72, sun.w)));
        }
        vec3 color = base * light;
        vec3 cell = floor(v_world - v_normal * 0.002);
        bool targeted = all(lessThan(abs(cell - target.xyz), vec3(0.1)));
        if (v_material >= 0.0 && target.w >= 0.0 && targeted) {
            vec3 local = fract(v_world);
            vec3 edge = min(local, 1.0 - local) + abs(v_normal);
            float border = min(edge.x, min(edge.y, edge.z));
            if (border < 0.018) color = vec3(1.0, 0.91, 0.57);
            // A progressively denser cracked pattern while holding mine.
            vec3 crack = abs(fract(v_world * 5.0 + sin(v_world.zxy * 13.0) * 0.2) - 0.5);
            if (target.w > 0.0 && min(crack.x + crack.y, crack.y + crack.z) < target.w * 0.18)
                color *= 0.28;
        }
        float fog = smoothstep(34.0, 83.0, length(eye.xyz - v_world));
        if (haze.w > 0.0) fog = 1.0 - exp(-length(eye.xyz - v_world) * 0.17);
        result = vec4(mix(color, haze.rgb, fog), 1.0);
    }
    """;
let sky_vertex = """
    layout(location = 0) out vec2 v_uv;
    void main() {
        vec2 p = vec2(float((gl_VertexIndex << 1) & 2), float(gl_VertexIndex & 2));
        v_uv = p;
        gl_Position = vec4(p * 2.0 - 1.0, 0.9999, 1.0);
    }
    """;
struct Sky { ahead: float4, right: float4, up: float4, info: float4, sun: float4, haze: float4 }
let sky_fragment = """
    layout(location = 0) in vec2 v_uv;
    layout(location = 0) out vec4 result;
    layout(set = 3, binding = 0) uniform Sky {
        vec4 ahead; vec4 right; vec4 up; vec4 info; vec4 sun; vec4 haze;
    };
    void main() {
        vec2 p = v_uv * 2.0 - 1.0;
        vec3 ray = normalize(ahead.xyz + right.xyz * p.x * info.x + up.xyz * p.y);
        vec3 zenith = mix(vec3(0.008, 0.015, 0.045), vec3(0.29, 0.57, 0.79), sun.w);
        vec3 color = mix(haze.rgb, zenith,
                         clamp(ray.y * 1.4, 0.0, 1.0));
        float glow = pow(max(dot(ray, sun.xyz), 0.0), 32.0);
        color += vec3(0.18, 0.14, 0.05) * glow * sun.w;
        if (ray.y > 0.0 && dot(ray, sun.xyz) > 0.9975) color = vec3(1.0, 0.95, 0.72);
        if (ray.y > 0.0 && dot(ray, -sun.xyz) > 0.9985) color = vec3(0.72, 0.79, 0.9);
        // A sparse hash of direction cells makes stars stay fixed as we turn.
        vec3 star_cell = floor(ray * 220.0);
        float star = fract(sin(dot(star_cell, vec3(12.9898, 78.233, 37.719))) * 43758.5453);
        if (ray.y > 0.12 && star > 0.9985) color += vec3(0.65) * (1.0 - sun.w);
        if (ray.y > 0.08) {
            vec2 p = ray.xz * (30.0 / ray.y) + vec2(info.y * 0.22, 0.0);
            vec2 grid = floor(p / 5.0);
            float n = sin(grid.x * 1.7 + sin(grid.y * 2.3)) + cos(grid.y * 1.2);
            vec3 cloud = mix(vec3(0.09, 0.12, 0.20), vec3(0.95, 0.96, 0.92), sun.w);
            if (n > 0.8) color = mix(color, cloud, smoothstep(0.08, 0.3, ray.y));
        }
        if (info.z > 0.0) color = vec3(0.08, 0.28, 0.38);
        result = vec4(color, 1.0);
    }
    """;

// --- a tiny immediate-mode HUD, also drawn with gfx ---------------------------

// A 5 x 7 font is enough for this sample. Each row is a five-bit mask.
// No font file, font rasterizer, or text texture is needed: set bits become
// little rectangles in the same batch as the panels and inventory icons.
fn glyph(c: u8) -> u8[7] {
    match c {
        'A' => [14, 17, 17, 31, 17, 17, 17], 'B' => [30, 17, 17, 30, 17, 17, 30],
        'C' => [14, 17, 16, 16, 16, 17, 14], 'D' => [30, 17, 17, 17, 17, 17, 30],
        'E' => [31, 16, 16, 30, 16, 16, 31], 'F' => [31, 16, 16, 30, 16, 16, 16],
        'G' => [14, 17, 16, 23, 17, 17, 15], 'H' => [17, 17, 17, 31, 17, 17, 17],
        'I' => [14, 4, 4, 4, 4, 4, 14], 'J' => [7, 2, 2, 2, 18, 18, 12],
        'K' => [17, 18, 20, 24, 20, 18, 17], 'L' => [16, 16, 16, 16, 16, 16, 31],
        'M' => [17, 27, 21, 21, 17, 17, 17], 'N' => [17, 25, 21, 19, 17, 17, 17],
        'O' => [14, 17, 17, 17, 17, 17, 14], 'P' => [30, 17, 17, 30, 16, 16, 16],
        'Q' => [14, 17, 17, 17, 21, 18, 13], 'R' => [30, 17, 17, 30, 20, 18, 17],
        'S' => [15, 16, 16, 14, 1, 1, 30], 'T' => [31, 4, 4, 4, 4, 4, 4],
        'U' => [17, 17, 17, 17, 17, 17, 14], 'V' => [17, 17, 17, 17, 17, 10, 4],
        'W' => [17, 17, 17, 21, 21, 21, 10], 'X' => [17, 17, 10, 4, 10, 17, 17],
        'Y' => [17, 17, 10, 4, 4, 4, 4], 'Z' => [31, 1, 2, 4, 8, 16, 31],
        '0' => [14, 17, 19, 21, 25, 17, 14], '1' => [4, 12, 4, 4, 4, 4, 14],
        '2' => [14, 17, 1, 2, 4, 8, 31], '3' => [30, 1, 1, 14, 1, 1, 30],
        '4' => [2, 6, 10, 18, 31, 2, 2], '5' => [31, 16, 16, 30, 1, 1, 30],
        '6' => [14, 16, 16, 30, 17, 17, 14], '7' => [31, 1, 2, 4, 8, 8, 8],
        '8' => [14, 17, 17, 14, 17, 17, 14], '9' => [14, 17, 17, 15, 1, 1, 14],
        '-' => [0, 0, 0, 31, 0, 0, 0], '+' => [0, 4, 4, 31, 4, 4, 0],
        '.' => [0, 0, 0, 0, 0, 12, 12], ':' => [0, 12, 12, 0, 12, 12, 0],
        '/' => [1, 2, 2, 4, 8, 8, 16], '(' => [2, 4, 8, 8, 8, 4, 2],
        ')' => [8, 4, 2, 2, 2, 4, 8], _ => [0; 7],
    }
}
struct HudVertex { pos: float2, uv: float2, color: u8[4] }
let INK:   u8[4] = [235, 237, 223, 255];
let MUTED: u8[4] = [166, 183, 181, 255];
let GOLD:  u8[4] = [250, 209, 116, 255];
let PANEL: u8[4] = [22, 34, 40, 225];
let WHITE: u8[4] = [255, 255, 255, 255];

fn quad(out: HudVertex[>..]&, x: f32, y: f32, w: f32, h: f32, color: u8[4], tile: i64) {
    let a = HudVertex { float2 { x, y }, atlas_uv(tile, 0.0, 0.0), color };
    let b = HudVertex { float2 { x + w, y }, atlas_uv(tile, 1.0, 0.0), color };
    let c = HudVertex { float2 { x + w, y + h }, atlas_uv(tile, 1.0, 1.0), color };
    let d = HudVertex { float2 { x, y + h }, atlas_uv(tile, 0.0, 1.0), color };
    out.append([a, b, c, a, c, d]);
}
fn rect(out: HudVertex[>..]&, x: f32, y: f32, w: f32, h: f32, color: u8[4]) {
    quad(out, x, y, w, h, color, WHITE_TILE);
}
fn text(out: HudVertex[>..]&, x: f32, y: f32, words: const u8[:], color: u8[4], scale: f32) {
    var at = x;
    for c in words {
        let rows = glyph(c);
        for row in 7 {
            for col in 5 {
                if (rows[row] & (1 << (4 - col))) != 0 {
                    rect(out, at + col * scale, y + row * scale, scale, scale, color);
                }
            }
        }
        at += 6.0 * scale;
    }
}
fn centred(out: HudVertex[>..]&, middle: f32, y: f32, words: const u8[:], color: u8[4]) {
    text(out, middle - words.len * 6.0, y, words, color, 2.0);
}
fn next_goal() -> const u8[:] {
    if game.tool == 0 && game.bag[2] < 2 && game.bag[3] < 5 { return "GATHER TWO WOOD BLOCKS"; }
    if game.tool == 0 { return "C - MAKE PLANKS AND A WOODEN PICK"; }
    if game.tool == 1 { return "MINE THREE STONE - C TO UPGRADE"; }
    if game.bag[6] == 0 && lamp_count == 0 { return "FIND COAL - C TO CRAFT LAMPS"; }
    "BUILD A CABIN - LIGHT YOUR CAVE"
}
fn block_name(b: u8) -> const u8[:] {
    if b == BEDROCK { return "BEDROCK - UNBREAKABLE"; }
    if (b == STONE || b == COAL || b == COBBLE) && game.tool == 0 { return "NEEDS A PICK - PRESS C"; }
    if b == GRASS { return "GRASS"; }
    if b == COAL { return "COAL ORE"; }
    let slot = drop_slot(b);
    if slot >= 0 { return SLOT_NAME[slot]; }
    ""
}
fn hud(out: HudVertex[>..]&, size: float2, hit: Hit, progress: f32,
       crafting: bool, paused: bool, help: bool) {
    rect(out, 18.0, 18.0, 418.0, 99.0, PANEL);
    rect(out, 18.0, 18.0, 4.0, 99.0, GOLD);
    text(out, 34.0, 31.0, "MINI MINECRAFT", GOLD, 2.0);
    text(out, 34.0, 56.0, next_goal(), INK, 1.5);
    let tool = if game.tool == 0 { "HANDS" } else if game.tool == 1 { "WOODEN PICK" } else { "STONE PICK" };
    text(out, 34.0, 79.0, str(tool, "  /  SEED ", game.seed), MUTED, 1.0);
    let phase = if daylight() < 0.2 { "NIGHT - LIGHT YOUR HOME" }
                else if day_time > 450.0 { "DAWN" }
                else if day_time > 270.0 { "DUSK - CRAFT SOME LAMPS" }
                else if day_time < 150.0 { "MORNING" } else { "AFTERNOON" };
    text(out, 34.0, 95.0, phase, MUTED, 1.0);

    if help && !crafting && !paused {
        let x = size.x - 316.0;
        rect(out, x, 18.0, 298.0, 192.0, PANEL);
        text(out, x + 14.0, 31.0, "MAKE YOURSELF AT HOME", GOLD, 1.5);
        let lines: const u8[:][9] = [
            "WASD WALK  /  SPACE JUMP OR SWIM", "SHIFT RUN  /  ARROWS LOOK",
            "CTRL SNEAK - STOPS AT LEDGES",
            "MOUSE LOOK  /  LEFT HOLD MINE", "RIGHT OR E PLACE - HOLD TO BUILD",
            "MIDDLE CLICK PICKS MATERIAL",
            "1-8 OR WHEEL SELECT  /  C CRAFT", "F5 SAVE  /  F9 LOAD  /  F12 PHOTO",
            "ESC PAUSE  /  H HIDE HELP"];
        for i in lines.len { text(out, x + 14.0, 58.0 + i * 16.0, lines[i], INK, 1.0); }
    } else if !crafting && !paused { text(out, size.x - 132.0, 26.0, "H - HELP", INK, 1.5); }

    let bar_x = (size.x - SLOTS * 66.0) * 0.5;
    let bar_y = size.y - 82.0;
    for i in SLOTS {
        let x = bar_x + i * 66.0;
        rect(out, x, bar_y, 62.0, 64.0, if game.selected == i { GOLD } else { PANEL });
        rect(out, x + 3.0, bar_y + 3.0, 56.0, 58.0, PANEL);
        let tile = if i == 7 { 10 } else { tile_for(SLOT_BLOCK[i], 4) };
        let tint: u8[4] = if game.bag[i] == 0 { [105, 110, 113, 255] } else { WHITE };
        quad(out, x + 17.0, bar_y + 8.0, 28.0, 28.0, tint, tile);
        text(out, x + 7.0, bar_y + 8.0, str(i + 1), GOLD, 1.0);
        text(out, x + 7.0, bar_y + 40.0, SLOT_NAME[i], MUTED, 1.0);
        text(out, x + 7.0, bar_y + 51.0, str(game.bag[i]), INK, 1.0);
    }
    centred(out, size.x * 0.5, bar_y - 25.0, SLOT_NAME[game.selected], INK);
    if !crafting && !paused {
        let cx = size.x * 0.5;
        let cy = size.y * 0.5;
        rect(out, cx - 7.0, cy - 2.0, 15.0, 5.0, PANEL);
        rect(out, cx - 2.0, cy - 7.0, 5.0, 15.0, PANEL);
        rect(out, cx - 6.0, cy, 13.0, 1.0, INK);
        rect(out, cx, cy - 6.0, 1.0, 13.0, INK);
        if hit.found {
            let label = block_name(block_at(hit.at));
            text(out, cx - label.len * 3.0, cy + 22.0, label, INK, 1.0);
            if progress > 0.0 {
                rect(out, cx - 40.0, cy + 37.0, 80.0, 5.0, PANEL);
                rect(out, cx - 40.0, cy + 37.0, 80.0 * progress, 5.0, GOLD);
            }
        }
    }
    if message_time > 0.0 {
        let width: f32 = message.len * 9.0 + 28.0;
        rect(out, (size.x - width) * 0.5, bar_y - 65.0, width, 28.0, PANEL);
        text(out, (size.x - width) * 0.5 + 14.0, bar_y - 57.0, message, GOLD, 1.5);
    }
    if crafting {
        let x = (size.x - 504.0) * 0.5;
        let y = (size.y - 300.0) * 0.5;
        rect(out, x, y, 504.0, 300.0, PANEL);
        rect(out, x, y, 504.0, 3.0, GOLD);
        text(out, x + 22.0, y + 20.0, "CRAFTING", GOLD, 2.0);
        text(out, x + 22.0, y + 48.0, "CLICK A RECIPE OR PRESS ITS NUMBER", MUTED, 1.5);
        let titles: const u8[:][4] = ["1  FOUR PLANKS", "2  WOODEN PICK", "3  STONE PICK", "4  FOUR LAMPS"];
        let costs: const u8[:][4] = ["1 WOOD", "5 PLANKS", "3 STONE + 2 PLANKS + WOODEN PICK",
                                      "1 COAL + 1 PLANK"];
        for i in 4 {
            let row_y = y + 78.0 + i * 46.0;
            rect(out, x + 16.0, row_y, 472.0, 40.0, [42, 57, 60, 250]);
            let ready = can_craft(i);
            text(out, x + 28.0, row_y + 7.0, titles[i], if ready { INK } else { MUTED }, 1.5);
            let owned = (i == 1 && game.tool >= 1) || (i == 2 && game.tool >= 2);
            text(out, x + 424.0, row_y + 8.0, if ready { "READY" } else if owned { "OWNED" } else { "NEED" },
                 if ready { GOLD } else { MUTED }, 1.0);
            text(out, x + 28.0, row_y + 26.0, costs[i], MUTED, 1.0);
        }
        text(out, x + 22.0, y + 264.0, "HOLD SHIFT WITH A RECIPE TO CRAFT ALL.", GOLD, 1.0);
        text(out, x + 22.0, y + 280.0, "TOOLS EQUIP AUTOMATICALLY. C OR ESC CLOSES.", MUTED, 1.0);
    } else if paused {
        rect(out, (size.x - 400.0) * 0.5, size.y * 0.5 - 45.0, 400.0, 90.0, PANEL);
        centred(out, size.x * 0.5, size.y * 0.5 - 26.0, "PAUSED", GOLD);
        text(out, size.x * 0.5 - 162.0, size.y * 0.5 + 4.0,
             "CLICK OR ESC TO RESUME. F5 SAVES.", INK, 1.5);
    }
}
let hud_vertex = """
